@dataclass(frozen=True)
class EvidenceAsset:
    """Read-only summary of an external or local evidence asset."""

    path: str
    asset_id: str
    matched_node_id: str | None
    asset_schema: str | None = None
    decision: str | None = None
    status: str | None = None
    route_hint: str | None = None
    content_hash: str | None = None

    def to_dict(self) -> dict[str, Any]:
        return {
            "path": self.path,
            "asset_id": self.asset_id,
            "matched_node_id": self.matched_node_id,
            "asset_schema": self.asset_schema,
            "decision": self.decision,
            "status": self.status,
            "route_hint": self.route_hint,
            "content_hash": self.content_hash,
        }


@dataclass(frozen=True)
class TransitionProposal:
    """A reviewable proposal emitted by the research-intelligence cycle.

    Proposals are advisory. They never grant construct status by themselves.
    """

    node_id: str
    proposal_type: str
    priority: str
    rationale: str
    required_review_gate: str
    forbidden_auto_actions: tuple[str, ...] = REQUIRED_PROPOSAL_GUARDRAILS
    supporting_assets: tuple[str, ...] = ()

    def to_dict(self) -> dict[str, Any]:
        return {
            "node_id": self.node_id,
            "proposal_type": self.proposal_type,
            "priority": self.priority,
            "rationale": self.rationale,
            "required_review_gate": self.required_review_gate,
            "forbidden_auto_actions": list(self.forbidden_auto_actions),
            "supporting_assets": list(self.supporting_assets),
        }


@dataclass(frozen=True)
class ExecutionPlanStep:
    """A bounded execution step the system may recommend."""

    step_id: str
    action: str
    autonomy_level: str
    requires_approval: bool
    rationale: str

    def to_dict(self) -> dict[str, Any]:
        return {
            "step_id": self.step_id,
            "action": self.action,
            "autonomy_level": self.autonomy_level,
            "requires_approval": self.requires_approval,
            "rationale": self.rationale,
        }


@dataclass(frozen=True)
class IntelligenceCycleReport:
    """Observe-orient-propose-plan report for the construct architecture."""

    evidence_assets: tuple[EvidenceAsset, ...]
    proposals: tuple[TransitionProposal, ...]
    execution_plan: tuple[ExecutionPlanStep, ...]
    unmatched_assets: tuple[EvidenceAsset, ...] = field(default_factory=tuple)
    architecture_counts: dict[str, Any] = field(default_factory=dict)
    boundary_hubs: tuple[tuple[str, int], ...] = field(default_factory=tuple)

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema": "consciousness_benchmark.research_intelligence_cycle.v1",
            "cycle_policy": {
                "mode": "read_only_observe_orient_propose_plan",
                "status_changes_allowed": False,
                "experiment_execution_allowed": False,
                "human_or_agent_review_required": True,
            },
            "counts": {
                "evidence_assets": len(self.evidence_assets),
                "matched_assets": len(self.evidence_assets) - len(self.unmatched_assets),
                "unmatched_assets": len(self.unmatched_assets),
                "proposals": len(self.proposals),
                "execution_plan_steps": len(self.execution_plan),
            },
            "architecture_counts": self.architecture_counts,
            "boundary_hubs": [
                {"id": node_id, "mentions": mentions}
                for node_id, mentions in self.boundary_hubs
            ],
            "evidence_assets": [asset.to_dict() for asset in self.evidence_assets],
            "unmatched_assets": [asset.to_dict() for asset in self.unmatched_assets],
            "proposals": [proposal.to_dict() for proposal in self.proposals],
            "execution_plan": [step.to_dict() for step in self.execution_plan],
        }

    def summary_markdown(self, *, proposal_limit: int = 30) -> str:
        data = self.to_dict()
        lines = [
            "# Research Intelligence Cycle",
            "",
            "| Metric | Count |",
            "|---|---:|",
        ]
        for key, value in data["counts"].items():
            lines.append(f"| `{key}` | {value} |")
        lines.extend(["", "## Boundary Hubs", "", "| Hub | Mentions |", "|---|---:|"])
        for node_id, mentions in self.boundary_hubs[:10]:
            lines.append(f"| `{node_id}` | {mentions} |")
        lines.extend(["", "## Transition Proposals", "", "| Node | Type | Priority | Gate |", "|---|---|---|---|"])
        for proposal in self.proposals[:proposal_limit]:
            lines.append(
                f"| `{proposal.node_id}` | `{proposal.proposal_type}` | "
                f"`{proposal.priority}` | {proposal.required_review_gate} |"
            )
        if len(self.proposals) > proposal_limit:
            lines.append(f"| ... | ... | ... | {len(self.proposals) - proposal_limit} more proposals omitted |")
        lines.extend(["", "## Bounded Execution Plan", "", "| Step | Action | Approval |", "|---|---|---|"])
        for step in self.execution_plan:
            approval = "required" if step.requires_approval else "not required"
            lines.append(f"| `{step.step_id}` | {step.action} | {approval} |")
        return "\n".join(lines)


@dataclass(frozen=True)
class ExecutionArtifact:
    """Artifact written by the bounded executor."""

    path: str
    artifact_type: str
    content_hash: str

    def to_dict(self) -> dict[str, Any]:
        return {
            "path": self.path,
            "artifact_type": self.artifact_type,
            "content_hash": self.content_hash,
        }


@dataclass(frozen=True)
class BoundedExecutionReport:
    """Report for safe autonomous execution over the intelligence cycle."""

    cycle_report: IntelligenceCycleReport
    artifacts: tuple[ExecutionArtifact, ...]
    executed_actions: tuple[str, ...]
    output_dir: str
    risk_mode: str
    integrity_checks: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        allowed_actions = (
            MEDIUM_RISK_ALLOWED_ACTIONS if self.risk_mode == "medium" else LOW_RISK_ALLOWED_ACTIONS
        )
        return {
            "schema": "consciousness_benchmark.bounded_research_execution.v1",
            "execution_policy": {
                "mode": (
                    "medium_risk_bounded_execution"
                    if self.risk_mode == "medium"
                    else "low_risk_bounded_artifact_generation"
                ),
                "risk_mode": self.risk_mode,
                "allowed_actions": list(allowed_actions),
                "forbidden_actions": list(FORBIDDEN_EXECUTION_ACTIONS),
                "status_changes_allowed": False,
                "experiment_execution_allowed": False,
                "writes_limited_to_output_dir": True,
                "human_or_agent_review_required_for_transition_work": True,
            },
            "output_dir": self.output_dir,
            "executed_actions": list(self.executed_actions),
            "artifacts": [artifact.to_dict() for artifact in self.artifacts],
            "integrity_checks": self.integrity_checks,
            "cycle_counts": self.cycle_report.to_dict()["counts"],
        }

    def summary_markdown(self) -> str:
        integrity_state = self.integrity_checks.get("passed", "not_run")
        lines = [
            "# Bounded Research Execution",
            "",
            "| Field | Value |",
            "|---|---|",
            f"| output dir | `{self.output_dir}` |",
            f"| risk mode | `{self.risk_mode}` |",
            f"| integrity checks | `{integrity_state}` |",
            f"| artifacts | {len(self.artifacts)} |",
            f"| executed actions | {len(self.executed_actions)} |",
            "",
            "## Executed Actions",
            "",
        ]
        for action in self.executed_actions:
            lines.append(f"- {action}")
        lines.extend(["", "## Artifacts", "", "| Type | Path |", "|---|---|"])
        for artifact in self.artifacts:
            lines.append(f"| `{artifact.artifact_type}` | `{artifact.path}` |")
        lines.extend(
            [
                "",
                "## Safety",
                "",
                "- No construct status was changed.",
                "- No experiment was executed.",
                "- No reference or sixth-construct status was granted.",
                "- Transition work remains review-gated.",
                "- Medium-risk mode may create local review work orders and append-only snapshots only.",
            ]
        )
        return "\n".join(lines)


