@dataclass(frozen=True)
class GateExecutionResult:
    """Result of an allowed local gate check.

    This is not a construct transition and not an experiment result. It is a
    controlled execution of local evidence, boundary, and firewall checks.
    """

    node_id: str
    proposal_type: str
    required_review_gate: str
    status: str
    supporting_asset_count: int
    boundary_hub_overlap: tuple[str, ...]
    executed_checks: tuple[str, ...]
    critic_findings: tuple[str, ...]
    allowed_next_action: str

    def to_dict(self) -> dict[str, Any]:
        return {
            "node_id": self.node_id,
            "proposal_type": self.proposal_type,
            "required_review_gate": self.required_review_gate,
            "status": self.status,
            "supporting_asset_count": self.supporting_asset_count,
            "boundary_hub_overlap": list(self.boundary_hub_overlap),
            "executed_checks": list(self.executed_checks),
            "critic_findings": list(self.critic_findings),
            "allowed_next_action": self.allowed_next_action,
        }


