def run_maintainer_merge_review_cycle(
    *,
    asset_dirs: Iterable[Path],
    approval_dirs: Iterable[Path] = (),
    approval_files: Iterable[Path] = (),
    execution_approval_dirs: Iterable[Path] = (),
    execution_approval_files: Iterable[Path] = (),
    authority_decision_dirs: Iterable[Path] = (),
    authority_decision_files: Iterable[Path] = (),
    application_decision_dirs: Iterable[Path] = (),
    application_decision_files: Iterable[Path] = (),
    maintainer_decision_dirs: Iterable[Path] = (),
    maintainer_decision_files: Iterable[Path] = (),
    output_dir: Path,
    schedule_file: Path | None = None,
    state_file: Path | None = None,
    architecture: ConstructArchitecture | None = None,
    max_assets: int | None = None,
    date_tag: str = "20260601",
    max_gate_executions: int = 5,
    max_goals: int = 3,
    max_cycles: int = 3,
    stable_stop_cycles: int = 1,
    sleep_seconds: float = 0.0,
    max_approvals: int = 5,
    max_hypotheses: int = 18,
    max_experiment_plans: int = 18,
    max_execution_approvals: int = 5,
    max_priority_updates: int = 12,
    max_next_approval_candidates: int = 8,
    max_authority_decisions: int = 5,
    max_application_decisions: int = 5,
    max_maintainer_decisions: int = 5,
) -> MaintainerMergeReport:
    """Run A18 maintainer merge review into simulated registry overlays."""

    architecture = architecture or all_construct_architecture()
    output_dir = output_dir.resolve()
    output_dir.mkdir(parents=True, exist_ok=True)
    application_report = run_formal_proposal_application_cycle(
        asset_dirs=asset_dirs,
        approval_dirs=approval_dirs,
        approval_files=approval_files,
        execution_approval_dirs=execution_approval_dirs,
        execution_approval_files=execution_approval_files,
        authority_decision_dirs=authority_decision_dirs,
        authority_decision_files=authority_decision_files,
        application_decision_dirs=application_decision_dirs,
        application_decision_files=application_decision_files,
        output_dir=output_dir,
        schedule_file=schedule_file,
        state_file=state_file,
        architecture=architecture,
        max_assets=max_assets,
        date_tag=f"{date_tag}_application",
        max_gate_executions=max_gate_executions,
        max_goals=max_goals,
        max_cycles=max_cycles,
        stable_stop_cycles=stable_stop_cycles,
        sleep_seconds=sleep_seconds,
        max_approvals=max_approvals,
        max_hypotheses=max_hypotheses,
        max_experiment_plans=max_experiment_plans,
        max_execution_approvals=max_execution_approvals,
        max_priority_updates=max_priority_updates,
        max_next_approval_candidates=max_next_approval_candidates,
        max_authority_decisions=max_authority_decisions,
        max_application_decisions=max_application_decisions,
    )
    decision_packets = _load_maintainer_merge_decisions(
        maintainer_decision_dirs=maintainer_decision_dirs,
        maintainer_decision_files=maintainer_decision_files,
        max_decisions=max_maintainer_decisions,
    )
    patches_by_id = {
        patch.patch_id: patch for patch in application_report.application_patches
    }
    patches_by_focus = {
        patch.focus_node_id: patch for patch in application_report.application_patches
    }

    artifacts = list(application_report.artifacts)
    simulated_overlays: list[SimulatedRegistryMergeOverlay] = []
    decision_records: list[dict[str, Any]] = []
    consumed_patch_ids: set[str] = set()
    overlay_dir = output_dir / f"simulated_registry_merge_overlays_{date_tag}"
    overlay_dir.mkdir(parents=True, exist_ok=True)

    for packet in decision_packets:
        patch = patches_by_id.get(packet.target_patch_id)
        if patch is None:
            patch = patches_by_focus.get(packet.target_focus_node_id)
        block_reason = _maintainer_merge_block_reason(packet=packet, patch=patch)
        if (
            block_reason is None
            and patch is not None
            and packet.merge_decision == "accept_simulated_registry_overlay"
        ):
            overlay = _simulated_registry_overlay_from_patch_decision(
                patch=patch,
                packet=packet,
            )
            simulated_overlays.append(overlay)
            consumed_patch_ids.add(patch.patch_id)
            decision_records.append(
                {
                    "decision_id": packet.decision_id,
                    "target_patch_id": patch.patch_id,
                    "decision_status": "applied_to_simulated_registry_overlay",
                    "overlay_id": overlay.overlay_id,
                    "formal_construct_status_change": "none",
                    "source_registry_mutated": False,
                }
            )
            json_path = overlay_dir / f"{overlay.overlay_id}.json"
            _write_artifact(json_path, json.dumps(overlay.to_dict(), indent=2, sort_keys=True) + "\n")
            artifacts.append(_artifact_for(json_path, "simulated_registry_overlay_json"))
            md_path = overlay_dir / f"{overlay.overlay_id}.md"
            _write_artifact(md_path, overlay.markdown())
            artifacts.append(_artifact_for(md_path, "simulated_registry_overlay_markdown"))
        else:
            decision_records.append(
                {
                    "decision_id": packet.decision_id,
                    "target_patch_id": packet.target_patch_id,
                    "target_focus_node_id": packet.target_focus_node_id,
                    "decision_status": "blocked",
                    "block_reason": block_reason or "decision did not accept simulated registry overlay",
                    "formal_construct_status_change": "none",
                    "source_registry_mutated": False,
                }
            )

    deferred_patches = _deferred_application_patches(
        application_report.application_patches,
        consumed_patch_ids=consumed_patch_ids,
    )
    merge_memory = _maintainer_merge_memory(
        application_report=application_report,
        decision_packets=decision_packets,
        overlays=tuple(simulated_overlays),
        deferred_patches=deferred_patches,
    )

    decisions_path = output_dir / f"maintainer_merge_decision_packets_{date_tag}.json"
    _write_artifact(
        decisions_path,
        json.dumps([packet.to_dict() for packet in decision_packets], indent=2, sort_keys=True)
        + "\n",
    )
    artifacts.append(_artifact_for(decisions_path, "maintainer_merge_decision_packets"))

    ledger_path = output_dir / f"maintainer_merge_ledger_{date_tag}.json"
    _write_artifact(ledger_path, json.dumps(decision_records, indent=2, sort_keys=True) + "\n")
    artifacts.append(_artifact_for(ledger_path, "maintainer_merge_ledger"))

    overlay_ledger_path = output_dir / f"simulated_registry_overlay_ledger_{date_tag}.json"
    _write_artifact(
        overlay_ledger_path,
        json.dumps([overlay.to_dict() for overlay in simulated_overlays], indent=2, sort_keys=True)
        + "\n",
    )
    artifacts.append(_artifact_for(overlay_ledger_path, "simulated_registry_overlay_ledger"))

    deferred_path = output_dir / f"deferred_application_patches_{date_tag}.json"
    _write_artifact(deferred_path, json.dumps(deferred_patches, indent=2, sort_keys=True) + "\n")
    artifacts.append(_artifact_for(deferred_path, "deferred_application_patches"))

    review_packet_path = output_dir / f"maintainer_merge_review_packet_{date_tag}.md"
    _write_artifact(
        review_packet_path,
        _maintainer_merge_review_packet_markdown(
            tuple(simulated_overlays),
            deferred_patches,
        ),
    )
    artifacts.append(_artifact_for(review_packet_path, "maintainer_merge_review_packet"))

    memory_path = output_dir / f"maintainer_merge_memory_{date_tag}.json"
    _write_artifact(memory_path, json.dumps(merge_memory, indent=2, sort_keys=True) + "\n")
    artifacts.append(_artifact_for(memory_path, "maintainer_merge_memory"))

    partial = MaintainerMergeReport(
        proposal_application_report=application_report,
        maintainer_decision_packets=decision_packets,
        simulated_merge_overlays=tuple(simulated_overlays),
        deferred_patches=deferred_patches,
        merge_memory=tuple(merge_memory),
        artifacts=tuple(artifacts),
        output_dir=str(output_dir),
        date_tag=date_tag,
    )
    summary_path = output_dir / f"maintainer_merge_summary_{date_tag}.md"
    _write_artifact(summary_path, partial.summary_markdown() + "\n")
    artifacts.append(_artifact_for(summary_path, "maintainer_merge_summary"))

    final_report = MaintainerMergeReport(
        proposal_application_report=application_report,
        maintainer_decision_packets=decision_packets,
        simulated_merge_overlays=tuple(simulated_overlays),
        deferred_patches=deferred_patches,
        merge_memory=tuple(merge_memory),
        artifacts=tuple(artifacts),
        output_dir=str(output_dir),
        date_tag=date_tag,
    )
    manifest_path = output_dir / f"maintainer_merge_manifest_{date_tag}.json"
    _write_artifact(manifest_path, json.dumps(final_report.to_dict(), indent=2, sort_keys=True) + "\n")
    artifacts.append(_artifact_for(manifest_path, "maintainer_merge_manifest"))

    return MaintainerMergeReport(
        proposal_application_report=application_report,
        maintainer_decision_packets=decision_packets,
        simulated_merge_overlays=tuple(simulated_overlays),
        deferred_patches=deferred_patches,
        merge_memory=tuple(merge_memory),
        artifacts=tuple(artifacts),
        output_dir=str(output_dir),
        date_tag=date_tag,
    )


