def _formal_proposal_review_packet_markdown(
    proposals: tuple[FormalStatusProposalDraft, ...],
) -> str:
    lines = [
        "# Formal Proposal External Review Packet",
        "",
        "Status: A16 proposal draft packet. It requests external review and does not apply formal construct status.",
        "",
        "| Focus | Proposal | Requested Decision | Review State | Registry Action |",
        "|---|---|---|---|---|",
    ]
    for proposal in proposals:
        lines.append(
            f"| `{proposal.focus_node_id}` | `{proposal.proposal_id}` | "
            f"`{proposal.requested_external_decision}` | "
            f"`{proposal.proposed_review_state}` | "
            f"`{proposal.proposed_registry_action}` |"
        )
    lines.extend(["", "## Required Conditions", ""])
    if not proposals:
        lines.append("- no retained council consensus was available for proposal drafting")
    else:
        seen_conditions: set[str] = set()
        for proposal in proposals:
            for condition in proposal.hard_conditions:
                if condition in seen_conditions:
                    continue
                seen_conditions.add(condition)
                lines.append(f"- {condition}")
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- formal status application: blocked",
            "- source registry mutation: blocked",
            "- reference status grant: blocked",
            "- open-ended experiment execution: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_formal_proposal_application_decisions(
    *,
    application_decision_dirs: Iterable[Path],
    application_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[FormalProposalApplicationDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in application_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in application_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[FormalProposalApplicationDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(_formal_proposal_application_decision_from_payload(payload, path))
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _formal_proposal_application_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> FormalProposalApplicationDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    return FormalProposalApplicationDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_proposal_id=str(payload.get("target_proposal_id") or ""),
        target_focus_node_id=str(payload.get("target_focus_node_id") or ""),
        application_decision=str(payload.get("application_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_application_state=str(
            payload.get("approved_application_state") or "unknown"
        ),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _formal_proposal_application_block_reason(
    *,
    packet: FormalProposalApplicationDecisionPacket,
    proposal: FormalStatusProposalDraft | None,
) -> str | None:
    if proposal is None:
        return "target A16 formal proposal draft was not found"

    allowed_decisions = {
        "accept_append_only_application_patch",
        "defer_proposal_application",
        "reject_proposal_application",
    }
    if packet.application_decision not in allowed_decisions:
        return f"application_decision {packet.application_decision!r} is not allowed"

    if packet.review_gate != "external_formal_proposal_application":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'external_formal_proposal_application'"
        )

    allowed_application_states = {
        "append_only_patch_ready",
        "deferred_by_application_authority",
        "rejected_by_application_authority",
    }
    if packet.approved_application_state not in allowed_application_states:
        return (
            "approved_application_state "
            f"{packet.approved_application_state!r} is not allowed"
        )

    if packet.target_focus_node_id != proposal.focus_node_id:
        return (
            f"target_focus_node_id {packet.target_focus_node_id!r} does not match "
            f"{proposal.focus_node_id!r}"
        )

    if not packet.signed_by:
        return "application decision is missing signed_by"
    if not packet.signature_token:
        return "application decision is missing signature_token"

    if bool(packet.constraints.get("allow_source_registry_mutation", False)):
        return "application decision attempted to allow source registry mutation"
    if bool(packet.constraints.get("allow_formal_status_change", False)):
        return "application decision attempted to allow formal construct status change"
    if bool(packet.constraints.get("allow_reference_status", False)):
        return "application decision attempted to allow reference status grant"
    if bool(packet.constraints.get("allow_open_ended_experiment", False)):
        return "application decision attempted to allow open-ended experiment execution"

    if packet.application_decision == "accept_append_only_application_patch":
        if packet.approved_application_state != "append_only_patch_ready":
            return "accepted application must approve append_only_patch_ready"
        if not bool(packet.constraints.get("allow_append_only_patch_draft", False)):
            return "accepted application must explicitly allow append-only patch draft"

    return None


def _application_patch_from_proposal_decision(
    *,
    proposal: FormalStatusProposalDraft,
    packet: FormalProposalApplicationDecisionPacket,
    architecture: ConstructArchitecture,
) -> FormalProposalApplicationPatch:
    node = _architecture_node_or_none(architecture, proposal.focus_node_id)
    prior_status = node.status if node is not None else "unknown"
    delta = {
        "operation": "append_review_state_application_record",
        "target_node_id": proposal.focus_node_id,
        "prior_formal_status": prior_status,
        "review_state": proposal.proposed_review_state,
        "proposal_id": proposal.proposal_id,
        "decision_id": packet.decision_id,
        "application_state": packet.approved_application_state,
        "formal_construct_status_change": "none",
        "source_registry_mutation": False,
    }
    rationale = packet.rationale or (
        "External formal proposal application decision accepted append-only patch drafting.",
        "A17 writes a patch draft for external maintainer merge review only.",
    )
    return FormalProposalApplicationPatch(
        patch_id=_safe_artifact_id(
            f"{packet.decision_id}_{proposal.focus_node_id}_application_patch"
        ),
        focus_node_id=proposal.focus_node_id,
        source_proposal_id=proposal.proposal_id,
        source_decision_id=packet.decision_id,
        patch_type="append_only_registry_patch_draft",
        patch_status=packet.approved_application_state,
        proposed_registry_delta=(delta,),
        merge_gate="external_registry_maintainer_review",
        rationale=tuple(rationale),
        required_external_actions=(
            "external maintainer reviews the append-only patch draft",
            "source registry merge remains outside autonomous runtime authority",
            "formal construct status change remains none unless a later external process acts",
        ),
    )


def _deferred_formal_proposals(
    proposals: tuple[FormalStatusProposalDraft, ...],
    *,
    consumed_proposal_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for proposal in proposals:
        if proposal.proposal_id in consumed_proposal_ids:
            continue
        deferred.append(
            {
                "proposal_id": proposal.proposal_id,
                "focus_node_id": proposal.focus_node_id,
                "proposal_type": proposal.proposal_type,
                "deferred_reason": "no accepted signed application decision packet",
                "recommended_next_gate": "external_formal_proposal_application",
                "formal_construct_status_change": "none",
                "source_registry_mutated": False,
                "reference_status_granted": False,
                "open_ended_experiment_allowed": False,
            }
        )
    return tuple(deferred)


