def _load_source_control_pr_decisions(
    *,
    pr_decision_dirs: Iterable[Path],
    pr_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlPrDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in pr_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in pr_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlPrDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(_source_control_pr_decision_from_payload(payload, path))
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_pr_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlPrDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    return SourceControlPrDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_overlay_id=str(payload.get("target_overlay_id") or ""),
        target_focus_node_id=str(payload.get("target_focus_node_id") or ""),
        pr_decision=str(payload.get("pr_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_pr_state=str(payload.get("approved_pr_state") or "unknown"),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_pr_block_reason(
    *,
    packet: SourceControlPrDecisionPacket,
    overlay: SimulatedRegistryMergeOverlay | None,
) -> str | None:
    if overlay is None:
        return "target A18 simulated registry overlay was not found"

    allowed_decisions = {
        "accept_source_control_pr_draft",
        "defer_source_control_pr_draft",
        "reject_source_control_pr_draft",
    }
    if packet.pr_decision not in allowed_decisions:
        return f"pr_decision {packet.pr_decision!r} is not allowed"

    if packet.review_gate != "external_source_control_pr_drafting":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'external_source_control_pr_drafting'"
        )

    allowed_pr_states = {
        "source_control_pr_draft_ready",
        "deferred_by_source_control_review",
        "rejected_by_source_control_review",
    }
    if packet.approved_pr_state not in allowed_pr_states:
        return f"approved_pr_state {packet.approved_pr_state!r} is not allowed"

    if packet.target_focus_node_id != overlay.focus_node_id:
        return (
            f"target_focus_node_id {packet.target_focus_node_id!r} does not match "
            f"{overlay.focus_node_id!r}"
        )

    if overlay.merge_state != "simulated_overlay_ready":
        return f"overlay merge_state {overlay.merge_state!r} is not ready for PR drafting"
    if overlay.patch_applied_to_source_registry:
        return "overlay reports patch already applied to source registry"
    if overlay.source_registry_mutated:
        return "overlay reports source registry mutation"

    if not packet.signed_by:
        return "source-control PR decision is missing signed_by"
    if not packet.signature_token:
        return "source-control PR decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_branch_creation",
        "allow_commit_creation",
        "allow_push",
        "allow_pull_request_creation",
        "allow_source_file_mutation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"source-control PR decision attempted to allow {key}"

    if packet.pr_decision == "accept_source_control_pr_draft":
        if packet.approved_pr_state != "source_control_pr_draft_ready":
            return "accepted PR draft must approve source_control_pr_draft_ready"
        if not bool(packet.constraints.get("allow_pr_draft", False)):
            return "accepted source-control decision must explicitly allow PR draft"

    return None


def _source_control_pr_draft_from_overlay_decision(
    *,
    overlay: SimulatedRegistryMergeOverlay,
    packet: SourceControlPrDecisionPacket,
) -> SourceControlPrDraft:
    branch_name = _safe_artifact_id(f"codex/a19-pr-draft-{overlay.focus_node_id}")
    draft_id = _safe_artifact_id(f"{packet.decision_id}_{overlay.focus_node_id}_pr_draft")
    title = f"A19 draft: source-control overlay for {overlay.focus_node_id}"
    body = "\n".join(
        [
            "This is a generated PR draft package only.",
            "",
            f"Focus node: `{overlay.focus_node_id}`",
            f"Source overlay: `{overlay.overlay_id}`",
            f"Source maintainer decision: `{overlay.source_decision_id}`",
            "",
            "The runtime did not create a branch, commit, push, pull request, or source-file mutation.",
        ]
    )
    proposed_changes = tuple(
        dict(
            change,
            source_control_pr_decision_id=packet.decision_id,
            pr_draft_state=packet.approved_pr_state,
            branch_created=False,
            commit_created=False,
            pull_request_created=False,
        )
        for change in overlay.simulated_registry_delta
    )
    return SourceControlPrDraft(
        draft_id=draft_id,
        focus_node_id=overlay.focus_node_id,
        source_overlay_id=overlay.overlay_id,
        source_decision_id=packet.decision_id,
        pr_state=packet.approved_pr_state,
        branch_name=branch_name,
        title=title,
        body=body,
        target_files=(
            "consciousness_benchmark/constructs/architecture.py",
            "configs/construct_architecture_20260531.json",
            "docs/construct_architecture_capability_validation_20260601.md",
        ),
        proposed_changes=proposed_changes,
        review_checklist=(
            "external maintainer confirms simulated overlay provenance",
            "external maintainer confirms no reference status is granted by this draft",
            "external maintainer confirms source changes happen only in a separate reviewed workflow",
            "external maintainer confirms rollback path is clear before any future merge",
        ),
        rollback_plan=(
            "discard the PR draft package if source-control review rejects it",
            "retain A18 overlay and A19 draft artifacts as audit history",
            "return the focus node to maintainer merge review before regenerating a draft",
        ),
        required_external_actions=(
            "a human or external source-control agent may create a branch from this draft",
            "a separate source-control review must approve any real commit or PR",
            "the autonomous runtime must not self-merge or mutate registry files",
        ),
    )


