def _source_control_execution_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlExecutionDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    target_pr_draft_id = payload.get("target_pr_draft_id")
    if not target_pr_draft_id:
        target_pr_draft_id = payload.get("target_draft_id")
    return SourceControlExecutionDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_pr_draft_id=str(target_pr_draft_id or ""),
        target_focus_node_id=str(payload.get("target_focus_node_id") or ""),
        execution_decision=str(payload.get("execution_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_execution_state=str(payload.get("approved_execution_state") or "unknown"),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_execution_block_reason(
    *,
    packet: SourceControlExecutionDecisionPacket,
    pr_draft: SourceControlPrDraft | None,
) -> str | None:
    if pr_draft is None:
        return "target A19 source-control PR draft was not found"

    allowed_decisions = {
        "accept_external_source_control_execution_packet",
        "defer_source_control_execution_packet",
        "reject_source_control_execution_packet",
    }
    if packet.execution_decision not in allowed_decisions:
        return f"execution_decision {packet.execution_decision!r} is not allowed"

    if packet.review_gate != "external_source_control_execution":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'external_source_control_execution'"
        )

    allowed_execution_states = {
        "external_execution_packet_ready",
        "deferred_by_source_control_execution_review",
        "rejected_by_source_control_execution_review",
    }
    if packet.approved_execution_state not in allowed_execution_states:
        return f"approved_execution_state {packet.approved_execution_state!r} is not allowed"

    if packet.target_focus_node_id != pr_draft.focus_node_id:
        return (
            f"target_focus_node_id {packet.target_focus_node_id!r} does not match "
            f"{pr_draft.focus_node_id!r}"
        )

    if pr_draft.pr_state != "source_control_pr_draft_ready":
        return f"PR draft state {pr_draft.pr_state!r} is not ready for execution packaging"
    if pr_draft.branch_created:
        return "PR draft reports a branch was already created"
    if pr_draft.commit_created:
        return "PR draft reports a commit was already created"
    if pr_draft.push_performed:
        return "PR draft reports a push was already performed"
    if pr_draft.pull_request_created:
        return "PR draft reports a pull request was already created"
    if pr_draft.source_files_modified:
        return "PR draft reports runtime source-file mutation"
    if pr_draft.source_registry_mutated:
        return "PR draft reports source registry mutation"
    if pr_draft.formal_construct_status_change != "none":
        return "PR draft reports a formal construct status change"
    if pr_draft.reference_status_granted:
        return "PR draft reports reference status was granted"
    if pr_draft.open_ended_experiment_allowed:
        return "PR draft reports open-ended experiment permission"

    if not packet.signed_by:
        return "source-control execution decision is missing signed_by"
    if not packet.signature_token:
        return "source-control execution decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_runtime_git_operations",
        "allow_runtime_branch_creation",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_runtime_source_file_mutation",
        "allow_branch_creation",
        "allow_commit_creation",
        "allow_push",
        "allow_pull_request_creation",
        "allow_source_file_mutation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"source-control execution decision attempted to allow {key}"

    if packet.execution_decision == "accept_external_source_control_execution_packet":
        if packet.approved_execution_state != "external_execution_packet_ready":
            return "accepted execution packet must approve external_execution_packet_ready"
        if not bool(packet.constraints.get("allow_external_execution_packet", False)):
            return "accepted source-control execution decision must allow an external packet"

    return None


def _source_control_execution_packet_from_pr_draft_decision(
    *,
    pr_draft: SourceControlPrDraft,
    packet: SourceControlExecutionDecisionPacket,
) -> SourceControlExecutionPacket:
    packet_id = _safe_artifact_id(f"{packet.decision_id}_{pr_draft.focus_node_id}_execution_packet")
    review_packet_hint = "source_control_execution_review_packet_<date_tag>.md"
    command_plan = (
        {
            "step": 1,
            "command": f"git checkout -b {pr_draft.branch_name}",
            "purpose": "create the reviewed branch in an external source-control session",
            "runtime_executed": False,
        },
        {
            "step": 2,
            "command": f"apply reviewed changes described by PR draft {pr_draft.draft_id}",
            "purpose": "materialize the A19 draft outside this runtime",
            "runtime_executed": False,
            "target_files": list(pr_draft.target_files),
        },
        {
            "step": 3,
            "command": "python -m pytest -q",
            "purpose": "verify the external branch before commit",
            "runtime_executed": False,
        },
        {
            "step": 4,
            "command": "git add " + " ".join(pr_draft.target_files),
            "purpose": "stage only reviewed architecture artifacts",
            "runtime_executed": False,
        },
        {
            "step": 5,
            "command": f"git commit -m \"{pr_draft.title}\"",
            "purpose": "create the external reviewed commit",
            "runtime_executed": False,
        },
        {
            "step": 6,
            "command": f"git push -u origin {pr_draft.branch_name}",
            "purpose": "publish the external branch after review",
            "runtime_executed": False,
        },
        {
            "step": 7,
            "command": (
                f"gh pr create --draft --title \"{pr_draft.title}\" "
                f"--body-file {review_packet_hint}"
            ),
            "purpose": "open a draft PR in a separate source-control workflow",
            "runtime_executed": False,
        },
    )
    return SourceControlExecutionPacket(
        packet_id=packet_id,
        focus_node_id=pr_draft.focus_node_id,
        source_pr_draft_id=pr_draft.draft_id,
        source_decision_id=packet.decision_id,
        execution_state=packet.approved_execution_state,
        branch_name=pr_draft.branch_name,
        title=pr_draft.title,
        command_plan=command_plan,
        preflight_checks=(
            "external actor confirms the worktree is clean before creating a branch",
            "external actor reads the A19 PR draft JSON and markdown",
            "external actor confirms no formal status or reference status is granted",
            "external actor confirms all command_plan entries are still reviewed and current",
            "external actor runs the repository test suite before creating a commit",
        ),
        expected_external_artifacts=(
            f"external branch {pr_draft.branch_name}",
            "one reviewed source-control commit",
            "one draft pull request URL",
            "passing CI or local test evidence attached to the PR",
        ),
        rollback_commands=(
            {
                "command": "git restore --staged .",
                "purpose": "unwind staged files in the external session",
                "runtime_executed": False,
            },
            {
                "command": "git restore .",
                "purpose": "discard external local source edits if review rejects them",
                "runtime_executed": False,
            },
            {
                "command": f"git branch -D {pr_draft.branch_name}",
                "purpose": "delete the external local branch after rejection",
                "runtime_executed": False,
            },
            {
                "command": f"git push origin --delete {pr_draft.branch_name}",
                "purpose": "delete the external remote branch if it was pushed",
                "runtime_executed": False,
            },
        ),
        required_external_actions=(
            "a human or external source-control agent must execute the command plan",
            "a separate reviewer must approve the draft PR before merge",
            "this runtime must not create branches, commits, pushes, or pull requests",
            "this runtime must not mutate the source construct registry",
        ),
    )


def _deferred_source_control_pr_drafts(
    pr_drafts: tuple[SourceControlPrDraft, ...],
    *,
    consumed_draft_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for draft in pr_drafts:
        if draft.draft_id in consumed_draft_ids:
            continue
        deferred.append(
            {
                "draft_id": draft.draft_id,
                "focus_node_id": draft.focus_node_id,
                "pr_state": draft.pr_state,
                "deferred_reason": "no accepted external source-control execution decision packet",
                "recommended_next_gate": "external_source_control_execution",
                "runtime_executed": False,
                "runtime_branch_created": False,
                "runtime_commit_created": False,
                "runtime_push_performed": False,
                "runtime_pull_request_created": False,
                "runtime_source_files_modified": False,
                "source_registry_mutated": False,
                "formal_construct_status_change": "none",
            }
        )
    return tuple(deferred)


