def _source_control_patch_preview_block_reason(
    *,
    packet: SourceControlPatchPreviewDecisionPacket,
    dry_run_result: SourceControlDryRunResult | None,
    execution_packet: SourceControlExecutionPacket | None,
) -> str | None:
    if dry_run_result is None:
        return "target A21 source-control dry-run result was not found"
    if execution_packet is None:
        return "source execution packet for dry-run result was not found"

    allowed_decisions = {
        "accept_isolated_source_control_patch_preview",
        "defer_source_control_patch_preview",
        "reject_source_control_patch_preview",
    }
    if packet.preview_decision not in allowed_decisions:
        return f"preview_decision {packet.preview_decision!r} is not allowed"

    if packet.review_gate != "isolated_source_control_patch_preview":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'isolated_source_control_patch_preview'"
        )

    allowed_states = {
        "isolated_patch_preview_ready",
        "deferred_by_source_control_patch_preview_review",
        "rejected_by_source_control_patch_preview_review",
    }
    if packet.approved_preview_state not in allowed_states:
        return f"approved_preview_state {packet.approved_preview_state!r} is not allowed"

    if packet.target_focus_node_id != dry_run_result.focus_node_id:
        return (
            f"target_focus_node_id {packet.target_focus_node_id!r} does not match "
            f"{dry_run_result.focus_node_id!r}"
        )

    if dry_run_result.dry_run_state != "sandbox_dry_run_passed":
        return f"dry-run state {dry_run_result.dry_run_state!r} is not ready for patch preview"
    if not dry_run_result.sandbox_dry_run_executed:
        return "dry-run result was not executed"
    if dry_run_result.git_operations_executed:
        return "dry-run result reports git operations were executed"
    if dry_run_result.branch_created:
        return "dry-run result reports branch creation"
    if dry_run_result.commit_created:
        return "dry-run result reports commit creation"
    if dry_run_result.push_performed:
        return "dry-run result reports push"
    if dry_run_result.pull_request_created:
        return "dry-run result reports pull request creation"
    if dry_run_result.source_files_modified:
        return "dry-run result reports source-file mutation"
    if dry_run_result.source_registry_mutated:
        return "dry-run result reports source registry mutation"
    if dry_run_result.formal_construct_status_change != "none":
        return "dry-run result reports formal construct status change"
    if dry_run_result.reference_status_granted:
        return "dry-run result reports reference status grant"
    if dry_run_result.open_ended_experiment_allowed:
        return "dry-run result reports open-ended experiment permission"
    if any(not bool(check.get("allowed_syntax", False)) for check in dry_run_result.command_checks):
        return "dry-run result has command syntax failures"

    if execution_packet.runtime_executed:
        return "source execution packet reports runtime execution"
    if execution_packet.source_files_modified:
        return "source execution packet reports source-file mutation"
    if execution_packet.source_registry_mutated:
        return "source execution packet reports source registry mutation"

    if not packet.signed_by:
        return "source-control patch-preview decision is missing signed_by"
    if not packet.signature_token:
        return "source-control patch-preview decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_worktree_mutation",
        "allow_source_file_mutation",
        "allow_runtime_source_file_mutation",
        "allow_git_execution",
        "allow_runtime_git_operations",
        "allow_runtime_branch_creation",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"source-control patch-preview decision attempted to allow {key}"

    if packet.preview_decision == "accept_isolated_source_control_patch_preview":
        if packet.approved_preview_state != "isolated_patch_preview_ready":
            return "accepted patch-preview decision must approve isolated_patch_preview_ready"
        if not bool(packet.constraints.get("allow_isolated_patch_preview", False)):
            return "accepted source-control patch-preview decision must allow isolated preview"

    return None


def _source_control_patch_preview_from_dry_run_decision(
    *,
    dry_run_result: SourceControlDryRunResult,
    execution_packet: SourceControlExecutionPacket,
    packet: SourceControlPatchPreviewDecisionPacket,
) -> SourceControlPatchPreview:
    preview_id = _safe_artifact_id(f"{packet.decision_id}_{dry_run_result.focus_node_id}_patch_preview")
    target_files = _source_control_preview_target_files(execution_packet)
    preview_files = tuple(
        {
            "target_file": path,
            "preview_action": "isolated_review_only_patch_preview",
            "preview_status": packet.approved_preview_state,
            "worktree_modified": False,
            "source_file_modified": False,
            "diff_hunk_count": 1,
        }
        for path in target_files
    )
    diff_preview = _source_control_patch_preview_diff(
        focus_node_id=dry_run_result.focus_node_id,
        preview_id=preview_id,
        source_dry_run_result_id=dry_run_result.result_id,
        target_files=target_files,
    )
    findings = (
        f"{len(target_files)} target files received isolated preview hunks",
        "patch preview was written as artifacts only",
        "repository worktree was not modified",
        "git operations remained blocked",
    )
    return SourceControlPatchPreview(
        preview_id=preview_id,
        focus_node_id=dry_run_result.focus_node_id,
        source_dry_run_result_id=dry_run_result.result_id,
        source_execution_packet_id=execution_packet.packet_id,
        source_decision_id=packet.decision_id,
        preview_state=packet.approved_preview_state,
        isolation_mode="artifact_only_patch_preview_no_worktree_mutation",
        target_files=target_files,
        preview_files=preview_files,
        unified_diff_preview=diff_preview,
        findings=findings,
        required_external_actions=(
            "external maintainer must inspect isolated patch preview before applying any change",
            "external source-control actor must create real diffs outside this runtime",
            "runtime must not modify repository files from preview artifacts",
            "runtime must not create branches, commits, pushes, or pull requests",
        ),
    )


def _source_control_preview_target_files(
    execution_packet: SourceControlExecutionPacket,
) -> tuple[str, ...]:
    for command in execution_packet.command_plan:
        target_files = command.get("target_files")
        if isinstance(target_files, list):
            cleaned = tuple(str(path) for path in target_files if isinstance(path, str))
            if cleaned:
                return cleaned
    return (
        "consciousness_benchmark/constructs/architecture.py",
        "configs/construct_architecture_20260531.json",
        "docs/construct_architecture_capability_validation_20260601.md",
    )


def _source_control_patch_preview_diff(
    *,
    focus_node_id: str,
    preview_id: str,
    source_dry_run_result_id: str,
    target_files: tuple[str, ...],
) -> str:
    sections: list[str] = []
    for path in target_files:
        sections.extend(
            [
                f"diff --git a/{path} b/{path}",
                f"--- a/{path}",
                f"+++ b/{path}",
                "@@",
                f"+# A22 isolated patch preview for {focus_node_id}",
                f"+# preview_id: {preview_id}",
                f"+# source_dry_run_result_id: {source_dry_run_result_id}",
                "+# This hunk is an artifact-only preview and was not applied to the worktree.",
            ]
        )
    return "\n".join(sections)


def _deferred_source_control_dry_run_results(
    dry_run_results: tuple[SourceControlDryRunResult, ...],
    *,
    consumed_dry_run_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in dry_run_results:
        if result.result_id in consumed_dry_run_result_ids:
            continue
        deferred.append(
            {
                "dry_run_result_id": result.result_id,
                "focus_node_id": result.focus_node_id,
                "dry_run_state": result.dry_run_state,
                "deferred_reason": "no accepted external source-control patch-preview decision packet",
                "recommended_next_gate": "isolated_source_control_patch_preview",
                "isolated_preview_written": False,
                "worktree_modified": False,
                "git_operations_executed": False,
                "runtime_source_files_modified": False,
                "source_registry_mutated": False,
                "formal_construct_status_change": "none",
            }
        )
    return tuple(deferred)


