def _load_source_control_apply_simulation_decisions(
    *,
    source_control_apply_simulation_decision_dirs: Iterable[Path],
    source_control_apply_simulation_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlApplySimulationDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_apply_simulation_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_apply_simulation_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlApplySimulationDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(_source_control_apply_simulation_decision_from_payload(payload, path))
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_apply_simulation_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlApplySimulationDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    return SourceControlApplySimulationDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_patch_preview_id=str(payload.get("target_patch_preview_id") or ""),
        target_focus_node_id=str(payload.get("target_focus_node_id") or ""),
        simulation_decision=str(payload.get("simulation_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_simulation_state=str(
            payload.get("approved_simulation_state") or "unknown"
        ),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_apply_simulation_block_reason(
    *,
    packet: SourceControlApplySimulationDecisionPacket,
    patch_preview: SourceControlPatchPreview | None,
) -> str | None:
    if patch_preview is None:
        return "target A22 source-control patch preview was not found"

    allowed_decisions = {
        "accept_worktree_apply_simulation",
        "defer_source_control_apply_simulation",
        "reject_source_control_apply_simulation",
    }
    if packet.simulation_decision not in allowed_decisions:
        return f"simulation_decision {packet.simulation_decision!r} is not allowed"

    if packet.review_gate != "worktree_apply_simulation":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'worktree_apply_simulation'"
        )

    allowed_states = {
        "worktree_apply_simulation_ready",
        "deferred_by_source_control_apply_simulation_review",
        "rejected_by_source_control_apply_simulation_review",
    }
    if packet.approved_simulation_state not in allowed_states:
        return (
            f"approved_simulation_state {packet.approved_simulation_state!r} "
            "is not allowed"
        )

    if packet.target_focus_node_id != patch_preview.focus_node_id:
        return (
            f"target_focus_node_id {packet.target_focus_node_id!r} does not match "
            f"{patch_preview.focus_node_id!r}"
        )
    if (
        packet.target_patch_preview_id
        and packet.target_patch_preview_id != patch_preview.preview_id
    ):
        return (
            f"target_patch_preview_id {packet.target_patch_preview_id!r} does not match "
            f"{patch_preview.preview_id!r}"
        )

    if patch_preview.preview_state != "isolated_patch_preview_ready":
        return (
            f"patch preview state {patch_preview.preview_state!r} "
            "is not ready for apply simulation"
        )
    if not patch_preview.isolated_preview_written:
        return "patch preview was not written"
    if patch_preview.worktree_modified:
        return "patch preview reports worktree mutation"
    if patch_preview.git_operations_executed:
        return "patch preview reports git operations"
    if patch_preview.branch_created:
        return "patch preview reports branch creation"
    if patch_preview.commit_created:
        return "patch preview reports commit creation"
    if patch_preview.push_performed:
        return "patch preview reports push"
    if patch_preview.pull_request_created:
        return "patch preview reports pull request creation"
    if patch_preview.source_files_modified:
        return "patch preview reports source-file mutation"
    if patch_preview.source_registry_mutated:
        return "patch preview reports source registry mutation"
    if patch_preview.formal_construct_status_change != "none":
        return "patch preview reports formal construct status change"
    if patch_preview.reference_status_granted:
        return "patch preview reports reference status grant"
    if patch_preview.open_ended_experiment_allowed:
        return "patch preview reports open-ended experiment permission"
    if "diff --git" not in patch_preview.unified_diff_preview:
        return "patch preview does not contain a unified diff header"
    if any(bool(item.get("worktree_modified", False)) for item in patch_preview.preview_files):
        return "patch preview file record reports worktree mutation"
    if any(bool(item.get("source_file_modified", False)) for item in patch_preview.preview_files):
        return "patch preview file record reports source-file mutation"

    if not packet.signed_by:
        return "source-control apply-simulation decision is missing signed_by"
    if not packet.signature_token:
        return "source-control apply-simulation decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_worktree_mutation",
        "allow_patch_application",
        "allow_source_file_mutation",
        "allow_runtime_source_file_mutation",
        "allow_git_execution",
        "allow_runtime_git_operations",
        "allow_runtime_branch_creation",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"source-control apply-simulation decision attempted to allow {key}"

    if packet.simulation_decision == "accept_worktree_apply_simulation":
        if packet.approved_simulation_state != "worktree_apply_simulation_ready":
            return (
                "accepted apply-simulation decision must approve "
                "worktree_apply_simulation_ready"
            )
        if not bool(packet.constraints.get("allow_worktree_apply_simulation", False)):
            return "accepted source-control apply-simulation decision must allow simulation"

    return None


def _source_control_apply_simulation_from_patch_preview_decision(
    *,
    patch_preview: SourceControlPatchPreview,
    packet: SourceControlApplySimulationDecisionPacket,
) -> SourceControlApplySimulationResult:
    result_id = _safe_artifact_id(
        f"{packet.decision_id}_{patch_preview.focus_node_id}_apply_simulation"
    )
    preview_files_by_path = {
        str(item.get("target_file")): item
        for item in patch_preview.preview_files
        if isinstance(item.get("target_file"), str)
    }
    target_file_results = tuple(
        {
            "target_file": path,
            "file_declared": True,
            "preview_file_recorded": path in preview_files_by_path,
            "simulated_status": "would_apply_to_preview_only",
            "worktree_modified": False,
            "source_file_modified": False,
        }
        for path in patch_preview.target_files
    )
    diff_hunk_results = _source_control_diff_hunk_results(
        patch_preview.unified_diff_preview
    )
    all_hunks_clean = bool(diff_hunk_results) and all(
        item["simulated_apply_status"] == "clean_in_preview_space"
        for item in diff_hunk_results
    )
    all_files_recorded = all(
        bool(item["preview_file_recorded"]) for item in target_file_results
    )
    simulation_state = (
        "worktree_apply_simulation_passed"
        if all_hunks_clean and all_files_recorded
        else "worktree_apply_simulation_needs_revision"
    )
    findings = (
        f"{len(target_file_results)} target files were checked in preview space",
        f"{len(diff_hunk_results)} diff sections were simulated without applying patches",
        "worktree was not modified",
        "git operations remained blocked",
    )
    return SourceControlApplySimulationResult(
        result_id=result_id,
        focus_node_id=patch_preview.focus_node_id,
        source_patch_preview_id=patch_preview.preview_id,
        source_decision_id=packet.decision_id,
        simulation_state=simulation_state,
        simulation_mode="preview_space_apply_simulation_no_worktree_mutation",
        target_file_results=target_file_results,
        diff_hunk_results=diff_hunk_results,
        findings=findings,
        required_external_actions=(
            "external source-control actor must run any real patch application",
            "runtime must not apply preview hunks to the repository worktree",
            "runtime must not create branches, commits, pushes, or pull requests",
            "external maintainer must review passing simulations before source mutation",
        ),
    )


def _source_control_diff_hunk_results(diff_preview: str) -> tuple[dict[str, Any], ...]:
    sections: list[list[str]] = []
    current: list[str] = []
    for line in diff_preview.splitlines():
        if line.startswith("diff --git "):
            if current:
                sections.append(current)
            current = [line]
        elif current:
            current.append(line)
    if current:
        sections.append(current)

    results: list[dict[str, Any]] = []
    for index, lines in enumerate(sections, start=1):
        header = lines[0] if lines else ""
        target_file = ""
        if " b/" in header:
            target_file = header.rsplit(" b/", maxsplit=1)[-1]
        has_diff_header = header.startswith("diff --git ")
        has_artifact_only_marker = any("artifact-only preview" in line for line in lines)
        results.append(
            {
                "hunk_index": index,
                "target_file": target_file,
                "has_diff_header": has_diff_header,
                "has_artifact_only_marker": has_artifact_only_marker,
                "simulated_apply_status": (
                    "clean_in_preview_space"
                    if has_diff_header and has_artifact_only_marker
                    else "needs_revision_in_preview_space"
                ),
                "worktree_modified": False,
                "source_file_modified": False,
                "git_operations_executed": False,
            }
        )
    return tuple(results)


