def _load_source_control_patch_applier_dry_run_decisions(
    *,
    source_control_patch_applier_dry_run_decision_dirs: Iterable[Path],
    source_control_patch_applier_dry_run_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlPatchApplierDryRunDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_patch_applier_dry_run_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_patch_applier_dry_run_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlPatchApplierDryRunDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(
            _source_control_patch_applier_dry_run_decision_from_payload(payload, path)
        )
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_patch_applier_dry_run_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlPatchApplierDryRunDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    return SourceControlPatchApplierDryRunDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_apply_simulation_result_id=str(
            payload.get("target_apply_simulation_result_id") or ""
        ),
        target_focus_node_id=str(payload.get("target_focus_node_id") or ""),
        dry_run_decision=str(payload.get("dry_run_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_dry_run_state=str(payload.get("approved_dry_run_state") or "unknown"),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_patch_applier_dry_run_block_reason(
    *,
    packet: SourceControlPatchApplierDryRunDecisionPacket,
    apply_result: SourceControlApplySimulationResult | None,
    patch_preview: SourceControlPatchPreview | None,
) -> str | None:
    if apply_result is None:
        return "target A23 source-control apply simulation result was not found"
    if patch_preview is None:
        return "source patch preview for apply simulation result was not found"

    allowed_decisions = {
        "accept_read_only_patch_applier_dry_run",
        "defer_source_control_patch_applier_dry_run",
        "reject_source_control_patch_applier_dry_run",
    }
    if packet.dry_run_decision not in allowed_decisions:
        return f"dry_run_decision {packet.dry_run_decision!r} is not allowed"

    if packet.review_gate != "read_only_patch_applier_dry_run":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'read_only_patch_applier_dry_run'"
        )

    allowed_states = {
        "read_only_patch_applier_dry_run_ready",
        "deferred_by_source_control_patch_applier_dry_run_review",
        "rejected_by_source_control_patch_applier_dry_run_review",
    }
    if packet.approved_dry_run_state not in allowed_states:
        return f"approved_dry_run_state {packet.approved_dry_run_state!r} is not allowed"

    if packet.target_focus_node_id != apply_result.focus_node_id:
        return (
            f"target_focus_node_id {packet.target_focus_node_id!r} does not match "
            f"{apply_result.focus_node_id!r}"
        )
    if (
        packet.target_apply_simulation_result_id
        and packet.target_apply_simulation_result_id != apply_result.result_id
    ):
        return (
            "target_apply_simulation_result_id "
            f"{packet.target_apply_simulation_result_id!r} does not match "
            f"{apply_result.result_id!r}"
        )

    if apply_result.simulation_state != "worktree_apply_simulation_passed":
        return (
            f"apply simulation state {apply_result.simulation_state!r} "
            "is not ready for patch applier dry-run"
        )
    if not apply_result.apply_simulation_executed:
        return "apply simulation was not executed"
    if apply_result.worktree_modified:
        return "apply simulation reports worktree mutation"
    if apply_result.source_files_modified:
        return "apply simulation reports source-file mutation"
    if apply_result.git_operations_executed:
        return "apply simulation reports git operations"
    if apply_result.branch_created:
        return "apply simulation reports branch creation"
    if apply_result.commit_created:
        return "apply simulation reports commit creation"
    if apply_result.push_performed:
        return "apply simulation reports push"
    if apply_result.pull_request_created:
        return "apply simulation reports pull request creation"
    if apply_result.source_registry_mutated:
        return "apply simulation reports source registry mutation"
    if apply_result.formal_construct_status_change != "none":
        return "apply simulation reports formal construct status change"
    if apply_result.reference_status_granted:
        return "apply simulation reports reference status grant"
    if apply_result.open_ended_experiment_allowed:
        return "apply simulation reports open-ended experiment permission"
    if any(bool(item.get("worktree_modified", False)) for item in apply_result.target_file_results):
        return "apply simulation target-file record reports worktree mutation"
    if any(bool(item.get("source_file_modified", False)) for item in apply_result.target_file_results):
        return "apply simulation target-file record reports source-file mutation"
    if any(
        item.get("simulated_apply_status") != "clean_in_preview_space"
        for item in apply_result.diff_hunk_results
    ):
        return "apply simulation contains non-clean diff hunks"

    if patch_preview.preview_id != apply_result.source_patch_preview_id:
        return "source patch preview does not match apply simulation provenance"
    if patch_preview.worktree_modified or patch_preview.source_files_modified:
        return "source patch preview reports worktree or source-file mutation"
    if patch_preview.git_operations_executed:
        return "source patch preview reports git operations"

    if not packet.signed_by:
        return "source-control patch-applier dry-run decision is missing signed_by"
    if not packet.signature_token:
        return "source-control patch-applier dry-run decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_worktree_mutation",
        "allow_patch_application",
        "allow_real_patch_application",
        "allow_source_file_mutation",
        "allow_runtime_source_file_mutation",
        "allow_git_execution",
        "allow_runtime_git_operations",
        "allow_runtime_branch_creation",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"source-control patch-applier dry-run decision attempted to allow {key}"

    if packet.dry_run_decision == "accept_read_only_patch_applier_dry_run":
        if packet.approved_dry_run_state != "read_only_patch_applier_dry_run_ready":
            return (
                "accepted patch-applier dry-run decision must approve "
                "read_only_patch_applier_dry_run_ready"
            )
        if not bool(packet.constraints.get("allow_read_only_patch_applier_dry_run", False)):
            return "accepted patch-applier dry-run decision must allow read-only dry-run"
        if not bool(packet.constraints.get("allow_worktree_read", False)):
            return "accepted patch-applier dry-run decision must allow worktree read"

    return None


def _source_control_patch_applier_dry_run_from_apply_result(
    *,
    apply_result: SourceControlApplySimulationResult,
    patch_preview: SourceControlPatchPreview,
    packet: SourceControlPatchApplierDryRunDecisionPacket,
    worktree_root: Path,
) -> SourceControlPatchApplierDryRunResult:
    result_id = _safe_artifact_id(
        f"{packet.decision_id}_{apply_result.focus_node_id}_patch_applier_dry_run"
    )
    target_file_checks = _source_control_patch_applier_target_file_checks(
        patch_preview.target_files,
        worktree_root=worktree_root,
    )
    diff_hunk_checks = _source_control_patch_applier_diff_hunk_checks(
        apply_result.diff_hunk_results,
        target_file_checks=target_file_checks,
    )
    all_files_ready = bool(target_file_checks) and all(
        item["dry_run_status"] == "worktree_snapshot_ready"
        for item in target_file_checks
    )
    all_hunks_ready = bool(diff_hunk_checks) and all(
        item["dry_run_apply_status"] == "would_apply_in_read_only_dry_run"
        for item in diff_hunk_checks
    )
    dry_run_state = (
        "read_only_patch_applier_dry_run_passed"
        if all_files_ready and all_hunks_ready
        else "read_only_patch_applier_dry_run_needs_revision"
    )
    findings = (
        f"{len(target_file_checks)} target file snapshots were inspected",
        f"{len(diff_hunk_checks)} diff hunks were checked against worktree snapshots",
        "patch applier dry-run did not apply patches",
        "worktree was not modified",
        "git operations remained blocked",
    )
    return SourceControlPatchApplierDryRunResult(
        result_id=result_id,
        focus_node_id=apply_result.focus_node_id,
        source_apply_simulation_result_id=apply_result.result_id,
        source_patch_preview_id=patch_preview.preview_id,
        source_decision_id=packet.decision_id,
        dry_run_state=dry_run_state,
        dry_run_mode="live_worktree_read_only_patch_applier_dry_run_no_mutation",
        worktree_root=str(worktree_root),
        target_file_checks=target_file_checks,
        diff_hunk_checks=diff_hunk_checks,
        findings=findings,
        required_external_actions=(
            "external source-control actor must apply any real patch outside this runtime",
            "external maintainer must review dry-run checksums before source mutation",
            "runtime must not write target files from patch preview artifacts",
            "runtime must not create branches, commits, pushes, or pull requests",
        ),
    )


def _source_control_patch_applier_target_file_checks(
    target_files: tuple[str, ...],
    *,
    worktree_root: Path,
) -> tuple[dict[str, Any], ...]:
    checks: list[dict[str, Any]] = []
    root = worktree_root.resolve()
    for target_file in target_files:
        target_path = Path(target_file)
        is_relative = not target_path.is_absolute()
        has_parent_escape = any(part == ".." for part in target_path.parts)
        resolved_path = (root / target_path).resolve() if is_relative else target_path.resolve()
        path_within_worktree = is_relative and not has_parent_escape and (
            resolved_path == root or root in resolved_path.parents
        )
        exists = path_within_worktree and resolved_path.exists()
        is_file = exists and resolved_path.is_file()
        readable = False
        sha256: str | None = None
        size_bytes: int | None = None
        line_count: int | None = None
        if is_file:
            try:
                content = resolved_path.read_bytes()
                readable = True
                sha256 = hashlib.sha256(content).hexdigest()
                size_bytes = len(content)
                line_count = len(content.splitlines())
            except OSError:
                readable = False
        checks.append(
            {
                "target_file": target_file,
                "resolved_path": str(resolved_path),
                "path_within_worktree": path_within_worktree,
                "exists": exists,
                "is_file": is_file,
                "readable": readable,
                "sha256": sha256,
                "size_bytes": size_bytes,
                "line_count": line_count,
                "worktree_read": readable,
                "dry_run_status": (
                    "worktree_snapshot_ready"
                    if path_within_worktree and is_file and readable
                    else "worktree_snapshot_unavailable"
                ),
                "worktree_modified": False,
                "source_file_modified": False,
                "patch_applied_to_worktree": False,
                "git_operations_executed": False,
            }
        )
    return tuple(checks)


def _source_control_patch_applier_diff_hunk_checks(
    diff_hunk_results: tuple[dict[str, Any], ...],
    *,
    target_file_checks: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    files_by_path = {
        str(item.get("target_file")): item
        for item in target_file_checks
        if isinstance(item.get("target_file"), str)
    }
    checks: list[dict[str, Any]] = []
    for item in diff_hunk_results:
        target_file = str(item.get("target_file") or "")
        file_check = files_by_path.get(target_file)
        snapshot_ready = (
            file_check is not None
            and file_check.get("dry_run_status") == "worktree_snapshot_ready"
        )
        preview_clean = item.get("simulated_apply_status") == "clean_in_preview_space"
        checks.append(
            {
                "hunk_index": item.get("hunk_index"),
                "target_file": target_file,
                "preview_clean": preview_clean,
                "worktree_snapshot_ready": snapshot_ready,
                "dry_run_apply_status": (
                    "would_apply_in_read_only_dry_run"
                    if preview_clean and snapshot_ready
                    else "needs_worktree_attention"
                ),
                "worktree_modified": False,
                "source_file_modified": False,
                "patch_applied_to_worktree": False,
                "git_operations_executed": False,
            }
        )
    return tuple(checks)


def _deferred_source_control_apply_simulation_results(
    apply_results: tuple[SourceControlApplySimulationResult, ...],
    *,
    consumed_apply_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in apply_results:
        if result.result_id in consumed_apply_result_ids:
            continue
        deferred.append(
            {
                "apply_simulation_result_id": result.result_id,
                "focus_node_id": result.focus_node_id,
                "simulation_state": result.simulation_state,
                "deferred_reason": (
                    "no accepted external patch-applier dry-run decision packet"
                ),
                "recommended_next_gate": "read_only_patch_applier_dry_run",
                "patch_applier_dry_run_executed": False,
                "worktree_read": False,
                "worktree_modified": False,
                "patch_applied_to_worktree": False,
                "source_files_modified": False,
                "git_operations_executed": False,
                "source_registry_mutated": False,
                "formal_construct_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_patch_applier_dry_run_memory(
    *,
    apply_simulation_report: SourceControlApplySimulationReport,
    decision_packets: tuple[SourceControlPatchApplierDryRunDecisionPacket, ...],
    dry_run_results: tuple[SourceControlPatchApplierDryRunResult, ...],
    deferred_apply_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    return (
        {
            "memory_id": "a24_source_control_patch_applier_dry_run_summary",
            "retained_learning": (
                f"{len(dry_run_results)} read-only patch applier dry-runs "
                f"were created from {len(decision_packets)} dry-run decisions"
            ),
            "recommended_strategy": (
                "route passing read-only patch applier dry-runs to external "
                "source-control actors; keep real patch application outside runtime"
            ),
            "read_only_patch_applier_dry_run_allowed": True,
            "worktree_read_allowed": True,
            "worktree_mutation_allowed": False,
            "runtime_git_operations_allowed": False,
            "source_registry_mutation_allowed": False,
        },
        {
            "memory_id": "a24_deferred_apply_simulation_summary",
            "retained_learning": (
                f"{len(deferred_apply_results)} of "
                f"{len(apply_simulation_report.apply_simulation_results)} "
                "apply simulations remain deferred without patch-applier decisions"
            ),
            "recommended_strategy": (
                "keep deferred apply simulations outside patch-applier dry-run "
                "until external review is available"
            ),
            "worktree_mutation_allowed": False,
            "runtime_git_operations_allowed": False,
        },
    )


def _source_control_patch_applier_dry_run_review_packet_markdown(
    dry_run_results: tuple[SourceControlPatchApplierDryRunResult, ...],
    deferred_apply_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Patch Applier Dry-Run Review",
        "",
        "Status: A24 read-only patch applier dry-run packet. Runtime inspected target file snapshots but did not apply patches.",
        "",
        "| Focus | Result | State | Worktree Read | Worktree Modified |",
        "|---|---|---|---|---|",
    ]
    for result in dry_run_results:
        lines.append(
            f"| `{result.focus_node_id}` | `{result.result_id}` | "
            f"`{result.dry_run_state}` | `{result.worktree_read}` | "
            f"`{result.worktree_modified}` |"
        )
    lines.extend(["", "## Deferred Apply Simulation Results", ""])
    if not deferred_apply_results:
        lines.append("- none")
    else:
        for item in deferred_apply_results:
            lines.append(
                f"- `{item['focus_node_id']}`: {item['deferred_reason']}"
            )
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- worktree read: allowed for target snapshots only",
            "- worktree mutation: blocked",
            "- source-file patch application: blocked",
            "- runtime source file mutation: blocked",
            "- runtime git execution: blocked",
            "- runtime branch creation: blocked",
            "- runtime commit creation: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- source registry mutation: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_source_control_guarded_patch_application_decisions(
    *,
    source_control_guarded_patch_application_decision_dirs: Iterable[Path],
    source_control_guarded_patch_application_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlGuardedPatchApplicationDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_guarded_patch_application_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_guarded_patch_application_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlGuardedPatchApplicationDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(
            _source_control_guarded_patch_application_decision_from_payload(payload, path)
        )
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_guarded_patch_application_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlGuardedPatchApplicationDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    return SourceControlGuardedPatchApplicationDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_patch_applier_dry_run_result_id=str(
            payload.get("target_patch_applier_dry_run_result_id") or ""
        ),
        target_focus_node_id=str(payload.get("target_focus_node_id") or ""),
        application_decision=str(payload.get("application_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_application_state=str(
            payload.get("approved_application_state") or "unknown"
        ),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_guarded_patch_application_block_reason(
    *,
    packet: SourceControlGuardedPatchApplicationDecisionPacket,
    dry_run_result: SourceControlPatchApplierDryRunResult | None,
) -> str | None:
    if dry_run_result is None:
        return "target A24 patch-applier dry-run result was not found"

    allowed_decisions = {
        "accept_guarded_source_patch_application",
        "defer_source_control_guarded_patch_application",
        "reject_source_control_guarded_patch_application",
    }
    if packet.application_decision not in allowed_decisions:
        return f"application_decision {packet.application_decision!r} is not allowed"

    if packet.review_gate != "guarded_source_patch_application":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'guarded_source_patch_application'"
        )

    allowed_states = {
        "guarded_source_patch_application_ready",
        "deferred_by_source_control_guarded_patch_application_review",
        "rejected_by_source_control_guarded_patch_application_review",
    }
    if packet.approved_application_state not in allowed_states:
        return (
            f"approved_application_state {packet.approved_application_state!r} "
            "is not allowed"
        )

    if packet.target_focus_node_id != dry_run_result.focus_node_id:
        return (
            f"target_focus_node_id {packet.target_focus_node_id!r} does not match "
            f"{dry_run_result.focus_node_id!r}"
        )
    if (
        packet.target_patch_applier_dry_run_result_id
        and packet.target_patch_applier_dry_run_result_id != dry_run_result.result_id
    ):
        return (
            "target_patch_applier_dry_run_result_id "
            f"{packet.target_patch_applier_dry_run_result_id!r} does not match "
            f"{dry_run_result.result_id!r}"
        )

    if dry_run_result.dry_run_state != "read_only_patch_applier_dry_run_passed":
        return (
            f"patch-applier dry-run state {dry_run_result.dry_run_state!r} "
            "is not ready for guarded patch application"
        )
    if not dry_run_result.patch_applier_dry_run_executed:
        return "patch-applier dry-run was not executed"
    if not dry_run_result.worktree_read:
        return "patch-applier dry-run did not read worktree snapshots"
    if dry_run_result.worktree_modified:
        return "patch-applier dry-run reports worktree mutation"
    if dry_run_result.patch_applied_to_worktree:
        return "patch-applier dry-run reports patch application"
    if dry_run_result.source_files_modified:
        return "patch-applier dry-run reports source-file mutation"
    if dry_run_result.git_operations_executed:
        return "patch-applier dry-run reports git operations"
    if dry_run_result.branch_created or dry_run_result.commit_created:
        return "patch-applier dry-run reports branch or commit creation"
    if dry_run_result.push_performed or dry_run_result.pull_request_created:
        return "patch-applier dry-run reports push or pull request creation"
    if dry_run_result.source_registry_mutated:
        return "patch-applier dry-run reports source registry mutation"
    if dry_run_result.formal_construct_status_change != "none":
        return "patch-applier dry-run reports formal construct status change"
    if dry_run_result.reference_status_granted:
        return "patch-applier dry-run reports reference status grant"
    if dry_run_result.open_ended_experiment_allowed:
        return "patch-applier dry-run reports open-ended experiment permission"
    if any(
        item.get("dry_run_status") != "worktree_snapshot_ready"
        for item in dry_run_result.target_file_checks
    ):
        return "patch-applier dry-run target-file checks are not all ready"
    if any(
        item.get("dry_run_apply_status") != "would_apply_in_read_only_dry_run"
        for item in dry_run_result.diff_hunk_checks
    ):
        return "patch-applier dry-run hunk checks are not all ready"

    if not packet.signed_by:
        return "guarded patch-application decision is missing signed_by"
    if not packet.signature_token:
        return "guarded patch-application decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_git_execution",
        "allow_runtime_git_operations",
        "allow_runtime_branch_creation",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"guarded patch-application decision attempted to allow {key}"

    if packet.application_decision == "accept_guarded_source_patch_application":
        if packet.approved_application_state != "guarded_source_patch_application_ready":
            return (
                "accepted guarded patch-application decision must approve "
                "guarded_source_patch_application_ready"
            )
        required_true_constraints = (
            "allow_guarded_source_patch_application",
            "allow_worktree_mutation",
            "allow_patch_application",
            "allow_source_file_mutation",
            "allow_rollback_manifest",
            "allow_post_change_verification",
        )
        for key in required_true_constraints:
            if not bool(packet.constraints.get(key, False)):
                return f"accepted guarded patch-application decision must allow {key}"

    return None


def _source_control_guarded_patch_application_from_dry_run(
    *,
    dry_run_result: SourceControlPatchApplierDryRunResult,
    packet: SourceControlGuardedPatchApplicationDecisionPacket,
    worktree_root: Path,
    output_dir: Path,
    backup_dir: Path,
    date_tag: str,
) -> SourceControlGuardedPatchApplicationResult:
    result_id = _safe_artifact_id(
        f"{packet.decision_id}_{dry_run_result.focus_node_id}_guarded_patch_application"
    )
    applied_files: list[dict[str, Any]] = []
    rollback_entries: list[dict[str, Any]] = []
    post_change_checks: list[dict[str, Any]] = []
    for target_check in dry_run_result.target_file_checks:
        applied = _apply_guarded_patch_marker_to_target_file(
            target_check=target_check,
            packet=packet,
            dry_run_result=dry_run_result,
            backup_dir=backup_dir,
            result_id=result_id,
            date_tag=date_tag,
        )
        applied_files.append(applied)
        rollback_entries.append(
            {
                "target_file": applied["target_file"],
                "resolved_path": applied["resolved_path"],
                "backup_path": applied["backup_path"],
                "before_sha256": applied["before_sha256"],
                "after_sha256": applied["after_sha256"],
                "restore_instruction": "copy backup_path back to resolved_path",
            }
        )
        post_change_checks.append(
            {
                "target_file": applied["target_file"],
                "resolved_path": applied["resolved_path"],
                "after_sha256": applied["after_sha256"],
                "mutation_status": applied["mutation_status"],
                "worktree_modified": applied["worktree_modified"],
                "source_file_modified": applied["source_file_modified"],
                "git_operations_executed": False,
            }
        )
    rollback_manifest_path = (
        output_dir / f"source_control_guarded_patch_application_rollback_{result_id}.json"
    )
    rollback_manifest = {
        "schema": "consciousness_benchmark.source_control_guarded_patch_application_rollback.v1",
        "result_id": result_id,
        "focus_node_id": dry_run_result.focus_node_id,
        "date_tag": date_tag,
        "entries": rollback_entries,
        "git_operations_executed": False,
        "formal_construct_status_change": "none",
    }
    _write_artifact(
        rollback_manifest_path,
        json.dumps(rollback_manifest, indent=2, sort_keys=True) + "\n",
    )
    any_modified = any(bool(item["worktree_modified"]) for item in applied_files)
    application_state = (
        "guarded_source_patch_application_applied"
        if any_modified
        else "guarded_source_patch_application_already_applied"
    )
    findings = (
        f"{len(applied_files)} target files processed with rollback backups",
        f"{sum(1 for item in applied_files if item['worktree_modified'])} target files changed",
        "guarded patch application wrote source files only after signed approval",
        "runtime git operations remained blocked",
        "formal construct status remained unchanged",
    )
    return SourceControlGuardedPatchApplicationResult(
        result_id=result_id,
        focus_node_id=dry_run_result.focus_node_id,
        source_patch_applier_dry_run_result_id=dry_run_result.result_id,
        source_apply_simulation_result_id=dry_run_result.source_apply_simulation_result_id,
        source_patch_preview_id=dry_run_result.source_patch_preview_id,
        source_decision_id=packet.decision_id,
        application_state=application_state,
        application_mode="signed_guarded_source_patch_application_with_rollback_manifest",
        worktree_root=str(worktree_root),
        applied_target_files=tuple(applied_files),
        rollback_manifest_path=str(rollback_manifest_path),
        rollback_available=rollback_manifest_path.exists(),
        post_change_checks=tuple(post_change_checks),
        findings=findings,
        required_external_actions=(
            "run post-application tests before any commit",
            "inspect rollback manifest before external source-control operations",
            "do not create branch, commit, push, or pull request from this runtime",
            "do not infer formal construct status changes from source-file mutation",
        ),
        worktree_modified=any_modified,
        patch_applied_to_worktree=any_modified,
        source_files_modified=any_modified,
    )


def _apply_guarded_patch_marker_to_target_file(
    *,
    target_check: dict[str, Any],
    packet: SourceControlGuardedPatchApplicationDecisionPacket,
    dry_run_result: SourceControlPatchApplierDryRunResult,
    backup_dir: Path,
    result_id: str,
    date_tag: str,
) -> dict[str, Any]:
    target_file = str(target_check.get("target_file") or "")
    resolved_path = Path(str(target_check.get("resolved_path") or ""))
    before_bytes = resolved_path.read_bytes()
    before_sha = hashlib.sha256(before_bytes).hexdigest()
    safe_name = _safe_artifact_id(target_file).replace("/", "_")
    backup_path = backup_dir / f"{result_id}_{safe_name}.before"
    if not backup_path.exists():
        backup_path.write_bytes(before_bytes)
    suffix = resolved_path.suffix.lower()
    original_text = before_bytes.decode("utf-8")
    entry = {
        "result_id": result_id,
        "decision_id": packet.decision_id,
        "focus_node_id": dry_run_result.focus_node_id,
        "source_patch_applier_dry_run_result_id": dry_run_result.result_id,
        "date_tag": date_tag,
    }
    if suffix == ".json":
        new_text = _apply_guarded_patch_marker_to_json(original_text, entry)
    elif suffix == ".md":
        new_text = _apply_guarded_patch_marker_to_markdown(original_text, entry)
    else:
        new_text = _apply_guarded_patch_marker_to_text(original_text, entry)
    if new_text != original_text:
        resolved_path.write_text(new_text, encoding="utf-8")
    after_bytes = resolved_path.read_bytes()
    after_sha = hashlib.sha256(after_bytes).hexdigest()
    worktree_modified = after_sha != before_sha
    return {
        "target_file": target_file,
        "resolved_path": str(resolved_path),
        "backup_path": str(backup_path),
        "before_sha256": before_sha,
        "after_sha256": after_sha,
        "mutation_status": (
            "source_file_updated"
            if worktree_modified
            else "already_contains_guarded_patch_marker"
        ),
        "worktree_modified": worktree_modified,
        "source_file_modified": worktree_modified,
        "patch_applied_to_worktree": worktree_modified,
        "git_operations_executed": False,
    }


def _guarded_patch_application_entry_line(entry: dict[str, str]) -> str:
    return (
        f"{entry['date_tag']} | {entry['focus_node_id']} | "
        f"{entry['result_id']} | {entry['decision_id']}"
    )


def _apply_guarded_patch_marker_to_text(
    text: str,
    entry: dict[str, str],
) -> str:
    if entry["result_id"] in text:
        return text
    line = f"# - {_guarded_patch_application_entry_line(entry)}"
    start = "# BEGIN A25_GUARDED_SOURCE_PATCH_APPLICATION_LEDGER"
    end = "# END A25_GUARDED_SOURCE_PATCH_APPLICATION_LEDGER"
    return _append_or_update_guarded_block(
        text,
        start=start,
        end=end,
        header_lines=(
            "# A25 guarded source patch application ledger",
            "# Runtime-generated marker block. Safe to keep as comments.",
        ),
        entry_line=line,
    )


def _apply_guarded_patch_marker_to_markdown(
    text: str,
    entry: dict[str, str],
) -> str:
    if entry["result_id"] in text:
        return text
    line = f"- {_guarded_patch_application_entry_line(entry)}"
    start = "<!-- BEGIN A25_GUARDED_SOURCE_PATCH_APPLICATION_LEDGER -->"
    end = "<!-- END A25_GUARDED_SOURCE_PATCH_APPLICATION_LEDGER -->"
    return _append_or_update_guarded_block(
        text,
        start=start,
        end=end,
        header_lines=("A25 guarded source patch application ledger:",),
        entry_line=line,
    )


def _append_or_update_guarded_block(
    text: str,
    *,
    start: str,
    end: str,
    header_lines: tuple[str, ...],
    entry_line: str,
) -> str:
    if start in text and end in text:
        before, rest = text.split(start, maxsplit=1)
        block, after = rest.split(end, maxsplit=1)
        block_lines = [line.rstrip() for line in block.strip("\n").splitlines() if line.strip()]
        if entry_line not in block_lines:
            block_lines.append(entry_line)
        new_block = "\n".join((start, *block_lines, end))
        return before.rstrip("\n") + "\n" + new_block + after
    prefix = text if text.endswith("\n") else text + "\n"
    block = "\n".join((start, *header_lines, entry_line, end))
    return prefix + "\n" + block + "\n"


def _apply_guarded_patch_marker_to_json(
    text: str,
    entry: dict[str, str],
) -> str:
    payload = json.loads(text)
    ledger = payload.get("_a25_guarded_source_patch_application_ledger")
    if not isinstance(ledger, dict):
        ledger = {
            "schema": "consciousness_benchmark.a25_guarded_source_patch_application_ledger.v1",
            "applications": [],
        }
    applications = ledger.get("applications")
    if not isinstance(applications, list):
        applications = []
    already_recorded = any(
        isinstance(item, dict) and item.get("result_id") == entry["result_id"]
        for item in applications
    )
    if already_recorded:
        return text
    applications.append(dict(entry))
    ledger["applications"] = applications
    ledger["latest_date_tag"] = entry["date_tag"]
    payload["_a25_guarded_source_patch_application_ledger"] = ledger
    return json.dumps(payload, indent=2, sort_keys=True) + "\n"


def _deferred_source_control_patch_applier_dry_run_results(
    dry_run_results: tuple[SourceControlPatchApplierDryRunResult, ...],
    *,
    consumed_dry_run_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in dry_run_results:
        if result.result_id in consumed_dry_run_result_ids:
            continue
        deferred.append(
            {
                "patch_applier_dry_run_result_id": result.result_id,
                "focus_node_id": result.focus_node_id,
                "dry_run_state": result.dry_run_state,
                "deferred_reason": (
                    "no accepted external guarded patch-application decision packet"
                ),
                "recommended_next_gate": "guarded_source_patch_application",
                "guarded_patch_application_executed": False,
                "worktree_modified": False,
                "patch_applied_to_worktree": False,
                "source_files_modified": False,
                "git_operations_executed": False,
                "source_registry_mutated": False,
                "formal_construct_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_guarded_patch_application_memory(
    *,
    dry_run_report: SourceControlPatchApplierDryRunReport,
    decision_packets: tuple[SourceControlGuardedPatchApplicationDecisionPacket, ...],
    application_results: tuple[SourceControlGuardedPatchApplicationResult, ...],
    deferred_dry_run_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    return (
        {
            "memory_id": "a25_source_control_guarded_patch_application_summary",
            "retained_learning": (
                f"{len(application_results)} guarded source patch applications "
                f"were created from {len(decision_packets)} application decisions"
            ),
            "recommended_strategy": (
                "run tests and external review before any branch, commit, push, "
                "or pull request operation"
            ),
            "guarded_source_patch_application_allowed": True,
            "source_file_mutation_allowed": True,
            "runtime_git_operations_allowed": False,
            "formal_status_transition_allowed": False,
        },
        {
            "memory_id": "a25_deferred_patch_applier_dry_run_summary",
            "retained_learning": (
                f"{len(deferred_dry_run_results)} of "
                f"{len(dry_run_report.patch_applier_dry_run_results)} dry-run results "
                "remain deferred without guarded patch-application decisions"
            ),
            "recommended_strategy": (
                "keep deferred dry-run results outside source mutation until "
                "external guarded patch-application review is available"
            ),
            "runtime_git_operations_allowed": False,
            "formal_status_transition_allowed": False,
        },
    )


def _source_control_guarded_patch_application_review_packet_markdown(
    application_results: tuple[SourceControlGuardedPatchApplicationResult, ...],
    deferred_dry_run_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Guarded Patch Application Review",
        "",
        "Status: A25 guarded source patch application packet. Runtime may mutate signed target files but does not run git.",
        "",
        "| Focus | Result | State | Worktree Modified | Git Ops |",
        "|---|---|---|---|---|",
    ]
    for result in application_results:
        lines.append(
            f"| `{result.focus_node_id}` | `{result.result_id}` | "
            f"`{result.application_state}` | `{result.worktree_modified}` | "
            f"`{result.git_operations_executed}` |"
        )
    lines.extend(["", "## Deferred Patch-Applier Dry-Run Results", ""])
    if not deferred_dry_run_results:
        lines.append("- none")
    else:
        for item in deferred_dry_run_results:
            lines.append(
                f"- `{item['focus_node_id']}`: {item['deferred_reason']}"
            )
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- guarded source file mutation: allowed only by signed decision",
            "- rollback manifest: required",
            "- runtime git execution: blocked",
            "- runtime branch creation: blocked",
            "- runtime commit creation: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- formal construct status changes: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_existing_source_control_guarded_patch_application_results(
    *,
    source_control_guarded_patch_application_result_dirs: Iterable[Path],
    source_control_guarded_patch_application_result_files: Iterable[Path],
) -> tuple[SourceControlGuardedPatchApplicationResult, ...]:
    paths: list[Path] = []
    for result_dir in source_control_guarded_patch_application_result_dirs:
        if result_dir.exists():
            paths.extend(sorted(result_dir.rglob("*.json")))
    for result_file in source_control_guarded_patch_application_result_files:
        if result_file.exists():
            paths.append(result_file)

    results: list[SourceControlGuardedPatchApplicationResult] = []
    seen_paths: set[Path] = set()
    seen_result_ids: set[str] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen_paths:
            continue
        seen_paths.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        payloads: list[dict[str, Any]] = []
        manifest_results = payload.get("guarded_patch_application_results")
        if isinstance(manifest_results, list):
            payloads.extend(item for item in manifest_results if isinstance(item, dict))
        elif isinstance(payload.get("result_id"), str) and isinstance(
            payload.get("application_state"),
            str,
        ):
            payloads.append(payload)
        for result_payload in payloads:
            result = _source_control_guarded_patch_application_result_from_payload(
                result_payload
            )
            if result.result_id in seen_result_ids:
                continue
            results.append(result)
            seen_result_ids.add(result.result_id)
    return tuple(results)


def _source_control_guarded_patch_application_result_from_payload(
    payload: dict[str, Any],
) -> SourceControlGuardedPatchApplicationResult:
    applied_target_files = payload.get("applied_target_files")
    post_change_checks = payload.get("post_change_checks")
    findings = payload.get("findings")
    required_external_actions = payload.get("required_external_actions")
    return SourceControlGuardedPatchApplicationResult(
        result_id=str(payload.get("result_id") or ""),
        focus_node_id=str(payload.get("focus_node_id") or ""),
        source_patch_applier_dry_run_result_id=str(
            payload.get("source_patch_applier_dry_run_result_id") or ""
        ),
        source_apply_simulation_result_id=str(
            payload.get("source_apply_simulation_result_id") or ""
        ),
        source_patch_preview_id=str(payload.get("source_patch_preview_id") or ""),
        source_decision_id=str(payload.get("source_decision_id") or ""),
        application_state=str(payload.get("application_state") or "unknown"),
        application_mode=str(payload.get("application_mode") or "unknown"),
        worktree_root=str(payload.get("worktree_root") or ""),
        applied_target_files=(
            tuple(item for item in applied_target_files if isinstance(item, dict))
            if isinstance(applied_target_files, list)
            else ()
        ),
        rollback_manifest_path=str(payload.get("rollback_manifest_path") or ""),
        rollback_available=bool(payload.get("rollback_available", False)),
        post_change_checks=(
            tuple(item for item in post_change_checks if isinstance(item, dict))
            if isinstance(post_change_checks, list)
            else ()
        ),
        findings=tuple(str(item) for item in findings) if isinstance(findings, list) else (),
        required_external_actions=(
            tuple(str(item) for item in required_external_actions)
            if isinstance(required_external_actions, list)
            else ()
        ),
        guarded_patch_application_executed=bool(
            payload.get("guarded_patch_application_executed", True)
        ),
        worktree_modified=bool(payload.get("worktree_modified", False)),
        patch_applied_to_worktree=bool(payload.get("patch_applied_to_worktree", False)),
        source_files_modified=bool(payload.get("source_files_modified", False)),
        git_operations_executed=bool(payload.get("git_operations_executed", False)),
        branch_created=bool(
            payload.get("branch_created", payload.get("runtime_branch_created", False))
        ),
        commit_created=bool(
            payload.get("commit_created", payload.get("runtime_commit_created", False))
        ),
        push_performed=bool(
            payload.get("push_performed", payload.get("runtime_push_performed", False))
        ),
        pull_request_created=bool(
            payload.get(
                "pull_request_created",
                payload.get("runtime_pull_request_created", False),
            )
        ),
        source_registry_mutated=bool(payload.get("source_registry_mutated", False)),
        formal_construct_status_change=str(
            payload.get("formal_construct_status_change") or "none"
        ),
        reference_status_granted=bool(payload.get("reference_status_granted", False)),
        open_ended_experiment_allowed=bool(
            payload.get("open_ended_experiment_allowed", False)
        ),
    )


def _load_source_control_post_change_verification_decisions(
    *,
    source_control_post_change_verification_decision_dirs: Iterable[Path],
    source_control_post_change_verification_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlPostChangeVerificationDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_post_change_verification_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_post_change_verification_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlPostChangeVerificationDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(
            _source_control_post_change_verification_decision_from_payload(
                payload,
                path,
            )
        )
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_post_change_verification_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlPostChangeVerificationDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    commands = payload.get("verification_commands")
    branch_preparation = payload.get("branch_preparation")
    return SourceControlPostChangeVerificationDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_guarded_patch_application_result_id=str(
            payload.get("target_guarded_patch_application_result_id") or ""
        ),
        target_focus_node_id=str(payload.get("target_focus_node_id") or ""),
        verification_decision=str(payload.get("verification_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_verification_state=str(
            payload.get("approved_verification_state") or "unknown"
        ),
        verification_commands=(
            tuple(item for item in commands if isinstance(item, dict))
            if isinstance(commands, list)
            else ()
        ),
        branch_preparation=(
            branch_preparation if isinstance(branch_preparation, dict) else {}
        ),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_post_change_verification_block_reason(
    *,
    packet: SourceControlPostChangeVerificationDecisionPacket,
    application_result: SourceControlGuardedPatchApplicationResult | None,
) -> str | None:
    if application_result is None:
        return "target A25 guarded patch application result was not found"

    allowed_decisions = {
        "accept_post_change_verification",
        "defer_source_control_post_change_verification",
        "reject_source_control_post_change_verification",
    }
    if packet.verification_decision not in allowed_decisions:
        return f"verification_decision {packet.verification_decision!r} is not allowed"

    if packet.review_gate != "post_change_verification_and_branch_preparation":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'post_change_verification_and_branch_preparation'"
        )

    allowed_states = {
        "post_change_verification_ready",
        "deferred_by_source_control_post_change_verification_review",
        "rejected_by_source_control_post_change_verification_review",
    }
    if packet.approved_verification_state not in allowed_states:
        return (
            f"approved_verification_state {packet.approved_verification_state!r} "
            "is not allowed"
        )

    if packet.target_focus_node_id != application_result.focus_node_id:
        return (
            f"target_focus_node_id {packet.target_focus_node_id!r} does not match "
            f"{application_result.focus_node_id!r}"
        )
    if (
        packet.target_guarded_patch_application_result_id
        and packet.target_guarded_patch_application_result_id
        != application_result.result_id
    ):
        return (
            "target_guarded_patch_application_result_id "
            f"{packet.target_guarded_patch_application_result_id!r} does not match "
            f"{application_result.result_id!r}"
        )

    ready_states = {
        "guarded_source_patch_application_applied",
        "guarded_source_patch_application_already_applied",
    }
    if application_result.application_state not in ready_states:
        return (
            f"guarded application state {application_result.application_state!r} "
            "is not ready for post-change verification"
        )
    if not application_result.guarded_patch_application_executed:
        return "guarded patch application was not executed"
    if not application_result.rollback_available:
        return "guarded patch application lacks rollback availability"
    if application_result.git_operations_executed:
        return "guarded patch application reports git operations"
    if application_result.branch_created or application_result.commit_created:
        return "guarded patch application reports branch or commit creation"
    if application_result.push_performed or application_result.pull_request_created:
        return "guarded patch application reports push or pull request creation"
    if application_result.source_registry_mutated:
        return "guarded patch application reports source registry mutation"
    if application_result.formal_construct_status_change != "none":
        return "guarded patch application reports formal construct status change"
    if application_result.reference_status_granted:
        return "guarded patch application reports reference status grant"
    if application_result.open_ended_experiment_allowed:
        return "guarded patch application reports open-ended experiment permission"
    for item in application_result.applied_target_files:
        if not item.get("backup_path"):
            return "guarded application target file is missing backup_path"
        if not item.get("after_sha256"):
            return "guarded application target file is missing after_sha256"

    if not packet.signed_by:
        return "post-change verification decision is missing signed_by"
    if not packet.signature_token:
        return "post-change verification decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_git_execution",
        "allow_runtime_git_operations",
        "allow_runtime_branch_creation",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"post-change verification decision attempted to allow {key}"

    if packet.verification_decision == "accept_post_change_verification":
        if packet.approved_verification_state != "post_change_verification_ready":
            return (
                "accepted post-change verification decision must approve "
                "post_change_verification_ready"
            )
        required_true_constraints = (
            "allow_post_change_verification",
            "allow_verification_command_execution",
            "allow_branch_preparation_packet",
        )
        for key in required_true_constraints:
            if not bool(packet.constraints.get(key, False)):
                return f"accepted post-change verification decision must allow {key}"
        if not packet.verification_commands:
            return "accepted post-change verification decision has no commands"
        for command in packet.verification_commands:
            command_block = _verification_command_block_reason(command)
            if command_block is not None:
                return command_block
        branch_block = _branch_preparation_block_reason(packet.branch_preparation)
        if branch_block is not None:
            return branch_block

    return None


def _verification_command_block_reason(command: dict[str, Any]) -> str | None:
    argv = command.get("argv")
    if not isinstance(argv, list) or not argv:
        return "verification command argv must be a non-empty list"
    if not all(isinstance(item, str) and item for item in argv):
        return "verification command argv entries must be non-empty strings"
    executable = Path(argv[0]).name.lower()
    if executable not in {"python", "python.exe", Path(sys.executable).name.lower()}:
        return "verification command must run through the current Python runtime"
    if len(argv) < 3 or argv[1] != "-m":
        return "verification command must use python -m"
    if argv[2] not in {"pytest", "py_compile"}:
        return f"verification module {argv[2]!r} is not allowlisted"
    forbidden_tokens = {
        "git",
        "gh",
        "push",
        "commit",
        "branch",
        "checkout",
        "reset",
        "curl",
        "wget",
        "invoke-webrequest",
        "start-process",
    }
    lowered = {item.lower() for item in argv}
    if lowered & forbidden_tokens:
        return "verification command contains a forbidden source-control or network token"
    timeout = _int_from_any(command.get("timeout_seconds"))
    if timeout is not None and timeout < 1:
        return "verification command timeout_seconds must be positive"
    return None


def _branch_preparation_block_reason(branch_preparation: dict[str, Any]) -> str | None:
    branch_name = str(branch_preparation.get("branch_name") or "")
    if not branch_name.startswith("codex/"):
        return "branch preparation branch_name must start with codex/"
    forbidden_true_flags = (
        "allow_branch_creation",
        "allow_commit_creation",
        "allow_push",
        "allow_pull_request_creation",
    )
    for key in forbidden_true_flags:
        if bool(branch_preparation.get(key, False)):
            return f"branch preparation attempted to allow {key}"
    return None


def _source_control_post_change_verification_from_application_result(
    *,
    application_result: SourceControlGuardedPatchApplicationResult,
    packet: SourceControlPostChangeVerificationDecisionPacket,
    worktree_root: Path,
    output_dir: Path,
    command_output_dir: Path,
    timeout_seconds: int,
) -> SourceControlPostChangeVerificationResult:
    result_id = _safe_artifact_id(
        f"{packet.decision_id}_{application_result.focus_node_id}_post_change_verification"
    )
    command_results = _source_control_execute_verification_commands(
        packet.verification_commands,
        worktree_root=worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        timeout_seconds=timeout_seconds,
    )
    verification_passed = all(bool(item.get("passed")) for item in command_results)
    verification_state = (
        "post_change_verification_passed"
        if verification_passed
        else "post_change_verification_failed"
    )
    branch_packet = _source_control_branch_preparation_packet(
        packet=packet,
        application_result=application_result,
        result_id=result_id,
        command_results=command_results,
        verification_passed=verification_passed,
        output_dir=output_dir,
    )
    findings = (
        f"{len(command_results)} approved verification commands executed",
        (
            "all approved verification commands passed"
            if verification_passed
            else "one or more approved verification commands failed"
        ),
        "branch preparation packet was written without creating a branch",
        "runtime git operations remained blocked",
        "formal construct status remained unchanged",
    )
    return SourceControlPostChangeVerificationResult(
        result_id=result_id,
        focus_node_id=application_result.focus_node_id,
        source_guarded_patch_application_result_id=application_result.result_id,
        source_decision_id=packet.decision_id,
        verification_state=verification_state,
        verification_mode="medium_risk_local_python_verification_no_git",
        command_results=tuple(command_results),
        branch_preparation_packet=branch_packet,
        findings=findings,
        required_external_actions=(
            "inspect verification outputs before any source-control operation",
            "create branch and commit only outside this runtime after explicit approval",
            "do not push or open pull requests from the medium-risk verifier",
            "do not infer formal construct status changes from passing tests",
        ),
    )


def _source_control_execute_verification_commands(
    commands: tuple[dict[str, Any], ...],
    *,
    worktree_root: Path,
    output_dir: Path,
    result_id: str,
    timeout_seconds: int,
) -> tuple[dict[str, Any], ...]:
    output_dir.mkdir(parents=True, exist_ok=True)
    results: list[dict[str, Any]] = []
    max_timeout = max(1, timeout_seconds)
    for index, command in enumerate(commands, start=1):
        command_id = _safe_artifact_id(str(command.get("command_id") or f"command_{index}"))
        raw_argv = tuple(str(item) for item in command.get("argv", ()))
        argv = list(raw_argv)
        if argv and Path(argv[0]).name.lower() in {
            "python",
            "python.exe",
            Path(sys.executable).name.lower(),
        }:
            argv[0] = sys.executable
        command_timeout = _int_from_any(command.get("timeout_seconds")) or max_timeout
        command_timeout = max(1, min(command_timeout, max_timeout))
        stdout_path = output_dir / f"{result_id}_{command_id}_stdout.txt"
        stderr_path = output_dir / f"{result_id}_{command_id}_stderr.txt"
        started = time.time()
        timeout_expired = False
        try:
            completed = subprocess.run(
                argv,
                cwd=worktree_root,
                capture_output=True,
                text=True,
                timeout=command_timeout,
                check=False,
                env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"},
            )
            exit_code: int | None = completed.returncode
            stdout = completed.stdout
            stderr = completed.stderr
        except subprocess.TimeoutExpired as exc:
            timeout_expired = True
            exit_code = None
            stdout = _subprocess_output_to_text(exc.stdout)
            stderr = _subprocess_output_to_text(exc.stderr)
        duration_seconds = round(time.time() - started, 3)
        _write_artifact(stdout_path, stdout)
        _write_artifact(stderr_path, stderr)
        results.append(
            {
                "command_id": command_id,
                "argv": raw_argv,
                "normalized_argv": tuple(argv),
                "cwd": str(worktree_root),
                "timeout_seconds": command_timeout,
                "duration_seconds": duration_seconds,
                "exit_code": exit_code,
                "passed": exit_code == 0 and not timeout_expired,
                "timeout_expired": timeout_expired,
                "stdout_path": str(stdout_path),
                "stderr_path": str(stderr_path),
                "stdout_excerpt": stdout[:4000],
                "stderr_excerpt": stderr[:4000],
                "git_operations_executed": False,
                "source_files_modified_by_verification": False,
            }
        )
    return tuple(results)


def _subprocess_output_to_text(output: str | bytes | None) -> str:
    if output is None:
        return ""
    if isinstance(output, bytes):
        return output.decode("utf-8", errors="replace")
    return output


def _source_control_branch_preparation_packet(
    *,
    packet: SourceControlPostChangeVerificationDecisionPacket,
    application_result: SourceControlGuardedPatchApplicationResult,
    result_id: str,
    command_results: tuple[dict[str, Any], ...],
    verification_passed: bool,
    output_dir: Path,
) -> dict[str, Any]:
    branch_preparation = packet.branch_preparation
    branch_name = str(
        branch_preparation.get("branch_name")
        or "codex/a26-medium-risk-post-change-verification"
    )
    base_branch = str(branch_preparation.get("base_branch") or "")
    purpose = str(
        branch_preparation.get("purpose")
        or "Prepare a reviewed branch after medium-risk post-change verification."
    )
    return {
        "schema": "consciousness_benchmark.source_control_branch_preparation_packet.v1",
        "packet_id": f"{result_id}_branch_preparation",
        "branch_name": branch_name,
        "base_branch": base_branch,
        "purpose": purpose,
        "source_post_change_verification_result_id": result_id,
        "source_guarded_patch_application_result_id": application_result.result_id,
        "verification_passed": verification_passed,
        "verification_command_ids": [
            str(item.get("command_id") or "") for item in command_results
        ],
        "recommended_output_dir": str(output_dir),
        "allowed_git_operations": {
            "branch_creation": False,
            "commit_creation": False,
            "push": False,
            "pull_request_creation": False,
        },
        "branch_created": False,
        "commit_created": False,
        "push_performed": False,
        "pull_request_created": False,
        "requires_external_operator": True,
    }


def _deferred_source_control_guarded_patch_application_results(
    application_results: tuple[SourceControlGuardedPatchApplicationResult, ...],
    *,
    consumed_application_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in application_results:
        if result.result_id in consumed_application_result_ids:
            continue
        deferred.append(
            {
                "guarded_patch_application_result_id": result.result_id,
                "focus_node_id": result.focus_node_id,
                "application_state": result.application_state,
                "deferred_reason": (
                    "no accepted external post-change verification decision packet"
                ),
                "recommended_next_gate": "post_change_verification_and_branch_preparation",
                "post_change_verification_executed": False,
                "verification_commands_executed": False,
                "branch_preparation_written": False,
                "git_operations_executed": False,
                "source_registry_mutated": False,
                "formal_construct_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_post_change_verification_memory(
    *,
    guarded_report: SourceControlGuardedPatchApplicationReport,
    decision_packets: tuple[SourceControlPostChangeVerificationDecisionPacket, ...],
    verification_results: tuple[SourceControlPostChangeVerificationResult, ...],
    deferred_application_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    passed = sum(
        1
        for result in verification_results
        if result.verification_state == "post_change_verification_passed"
    )
    return (
        {
            "memory_id": "a26_medium_risk_post_change_verification_summary",
            "retained_learning": (
                f"{passed} of {len(verification_results)} post-change verification "
                "results passed after guarded source patch application"
            ),
            "recommended_strategy": (
                "allow local verification and branch preparation packets, but keep "
                "actual branch, commit, push, and PR operations outside this runtime"
            ),
            "medium_risk_open_state": True,
            "verification_command_execution_allowed": True,
            "branch_preparation_packet_allowed": True,
            "runtime_git_operations_allowed": False,
            "formal_status_transition_allowed": False,
        },
        {
            "memory_id": "a26_deferred_guarded_application_summary",
            "retained_learning": (
                f"{len(deferred_application_results)} of "
                f"{len(guarded_report.guarded_patch_application_results)} guarded "
                "application results remain without post-change verification decisions"
            ),
            "decision_packets_seen": len(decision_packets),
            "recommended_strategy": (
                "keep unverified guarded applications outside source-control branch "
                "preparation until explicit verification decisions are available"
            ),
            "runtime_git_operations_allowed": False,
            "formal_status_transition_allowed": False,
        },
    )


def _source_control_post_change_verification_review_packet_markdown(
    verification_results: tuple[SourceControlPostChangeVerificationResult, ...],
    deferred_application_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Post-Change Verification Review",
        "",
        "Status: A26 medium-risk verification packet. Runtime may execute approved local Python verification commands but does not run git.",
        "",
        "| Focus | Result | State | Commands | Git Ops |",
        "|---|---|---|---:|---|",
    ]
    for result in verification_results:
        lines.append(
            f"| `{result.focus_node_id}` | `{result.result_id}` | "
            f"`{result.verification_state}` | {len(result.command_results)} | "
            f"`{result.git_operations_executed}` |"
        )
    lines.extend(["", "## Deferred Guarded Patch Applications", ""])
    if not deferred_application_results:
        lines.append("- none")
    else:
        for item in deferred_application_results:
            lines.append(
                f"- `{item['focus_node_id']}`: {item['deferred_reason']}"
            )
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- verification command execution: approved local Python commands only",
            "- source file mutation during verification: blocked",
            "- runtime git execution: blocked",
            "- runtime branch creation: blocked",
            "- runtime commit creation: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- formal construct status changes: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_existing_source_control_post_change_verification_results(
    *,
    source_control_post_change_verification_result_dirs: Iterable[Path],
    source_control_post_change_verification_result_files: Iterable[Path],
) -> tuple[SourceControlPostChangeVerificationResult, ...]:
    paths: list[Path] = []
    for result_dir in source_control_post_change_verification_result_dirs:
        if result_dir.exists():
            paths.extend(sorted(result_dir.rglob("*.json")))
    for result_file in source_control_post_change_verification_result_files:
        if result_file.exists():
            paths.append(result_file)

    results: list[SourceControlPostChangeVerificationResult] = []
    seen_paths: set[Path] = set()
    seen_result_ids: set[str] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen_paths:
            continue
        seen_paths.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        payloads: list[dict[str, Any]] = []
        manifest_results = payload.get("post_change_verification_results")
        if isinstance(manifest_results, list):
            payloads.extend(item for item in manifest_results if isinstance(item, dict))
        elif isinstance(payload.get("result_id"), str) and isinstance(
            payload.get("verification_state"),
            str,
        ):
            payloads.append(payload)
        for result_payload in payloads:
            result = _source_control_post_change_verification_result_from_payload(
                result_payload
            )
            if result.result_id in seen_result_ids:
                continue
            results.append(result)
            seen_result_ids.add(result.result_id)
    return tuple(results)


def _source_control_post_change_verification_result_from_payload(
    payload: dict[str, Any],
) -> SourceControlPostChangeVerificationResult:
    command_results = payload.get("command_results")
    findings = payload.get("findings")
    required_external_actions = payload.get("required_external_actions")
    branch_preparation_packet = payload.get("branch_preparation_packet")
    return SourceControlPostChangeVerificationResult(
        result_id=str(payload.get("result_id") or ""),
        focus_node_id=str(payload.get("focus_node_id") or ""),
        source_guarded_patch_application_result_id=str(
            payload.get("source_guarded_patch_application_result_id") or ""
        ),
        source_decision_id=str(payload.get("source_decision_id") or ""),
        verification_state=str(payload.get("verification_state") or "unknown"),
        verification_mode=str(payload.get("verification_mode") or "unknown"),
        command_results=(
            tuple(item for item in command_results if isinstance(item, dict))
            if isinstance(command_results, list)
            else ()
        ),
        branch_preparation_packet=(
            branch_preparation_packet
            if isinstance(branch_preparation_packet, dict)
            else {}
        ),
        findings=tuple(str(item) for item in findings) if isinstance(findings, list) else (),
        required_external_actions=(
            tuple(str(item) for item in required_external_actions)
            if isinstance(required_external_actions, list)
            else ()
        ),
        post_change_verification_executed=bool(
            payload.get("post_change_verification_executed", True)
        ),
        verification_commands_executed=bool(
            payload.get("verification_commands_executed", True)
        ),
        branch_preparation_written=bool(
            payload.get("branch_preparation_written", True)
        ),
        worktree_modified_by_verification=bool(
            payload.get("worktree_modified_by_verification", False)
        ),
        source_files_modified_by_verification=bool(
            payload.get("source_files_modified_by_verification", False)
        ),
        git_operations_executed=bool(payload.get("git_operations_executed", False)),
        branch_created=bool(
            payload.get("branch_created", payload.get("runtime_branch_created", False))
        ),
        commit_created=bool(
            payload.get("commit_created", payload.get("runtime_commit_created", False))
        ),
        push_performed=bool(
            payload.get("push_performed", payload.get("runtime_push_performed", False))
        ),
        pull_request_created=bool(
            payload.get(
                "pull_request_created",
                payload.get("runtime_pull_request_created", False),
            )
        ),
        source_registry_mutated=bool(payload.get("source_registry_mutated", False)),
        formal_construct_status_change=str(
            payload.get("formal_construct_status_change") or "none"
        ),
        reference_status_granted=bool(payload.get("reference_status_granted", False)),
        open_ended_experiment_allowed=bool(
            payload.get("open_ended_experiment_allowed", False)
        ),
    )


def _load_source_control_read_only_git_inspection_decisions(
    *,
    source_control_read_only_git_inspection_decision_dirs: Iterable[Path],
    source_control_read_only_git_inspection_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlReadOnlyGitInspectionDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_read_only_git_inspection_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_read_only_git_inspection_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlReadOnlyGitInspectionDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(
            _source_control_read_only_git_inspection_decision_from_payload(
                payload,
                path,
            )
        )
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_read_only_git_inspection_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlReadOnlyGitInspectionDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    commands = payload.get("inspection_commands")
    commit_preparation = payload.get("commit_preparation")
    target_result_ids = payload.get("target_post_change_verification_result_ids")
    target_focus_ids = payload.get("target_focus_node_ids")
    return SourceControlReadOnlyGitInspectionDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_post_change_verification_result_ids=(
            tuple(str(item) for item in target_result_ids)
            if isinstance(target_result_ids, list)
            else ()
        ),
        target_focus_node_ids=(
            tuple(str(item) for item in target_focus_ids)
            if isinstance(target_focus_ids, list)
            else ()
        ),
        inspection_decision=str(payload.get("inspection_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_inspection_state=str(
            payload.get("approved_inspection_state") or "unknown"
        ),
        inspection_commands=(
            tuple(item for item in commands if isinstance(item, dict))
            if isinstance(commands, list)
            else ()
        ),
        commit_preparation=(
            commit_preparation if isinstance(commit_preparation, dict) else {}
        ),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_read_only_git_inspection_block_reason(
    *,
    packet: SourceControlReadOnlyGitInspectionDecisionPacket,
    verification_results: tuple[SourceControlPostChangeVerificationResult, ...],
) -> str | None:
    allowed_decisions = {
        "accept_read_only_git_inspection",
        "defer_source_control_read_only_git_inspection",
        "reject_source_control_read_only_git_inspection",
    }
    if packet.inspection_decision not in allowed_decisions:
        return f"inspection_decision {packet.inspection_decision!r} is not allowed"

    if packet.review_gate != "read_only_git_inspection_and_commit_preparation":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'read_only_git_inspection_and_commit_preparation'"
        )

    allowed_states = {
        "read_only_git_inspection_ready",
        "deferred_by_source_control_read_only_git_inspection_review",
        "rejected_by_source_control_read_only_git_inspection_review",
    }
    if packet.approved_inspection_state not in allowed_states:
        return (
            f"approved_inspection_state {packet.approved_inspection_state!r} "
            "is not allowed"
        )

    if not packet.target_post_change_verification_result_ids:
        return "read-only git inspection decision has no target verification results"
    found_result_ids = {result.result_id for result in verification_results}
    missing_result_ids = [
        result_id
        for result_id in packet.target_post_change_verification_result_ids
        if result_id not in found_result_ids
    ]
    if missing_result_ids:
        return (
            "target A26 post-change verification results were not found: "
            + ", ".join(missing_result_ids)
        )

    focus_ids = {result.focus_node_id for result in verification_results}
    if set(packet.target_focus_node_ids) != focus_ids:
        return "target_focus_node_ids do not match target verification result focus ids"

    for result in verification_results:
        if result.verification_state != "post_change_verification_passed":
            return (
                f"post-change verification result {result.result_id!r} is not passed"
            )
        if not result.post_change_verification_executed:
            return f"post-change verification {result.result_id!r} was not executed"
        if not result.verification_commands_executed:
            return f"verification commands for {result.result_id!r} were not executed"
        if not result.branch_preparation_written:
            return f"branch preparation for {result.result_id!r} was not written"
        if result.worktree_modified_by_verification:
            return f"verification {result.result_id!r} reports worktree mutation"
        if result.source_files_modified_by_verification:
            return f"verification {result.result_id!r} reports source-file mutation"
        if result.git_operations_executed:
            return f"verification {result.result_id!r} reports git operations"
        if result.branch_created or result.commit_created:
            return f"verification {result.result_id!r} reports branch or commit creation"
        if result.push_performed or result.pull_request_created:
            return f"verification {result.result_id!r} reports push or pull request"
        if result.source_registry_mutated:
            return f"verification {result.result_id!r} reports source registry mutation"
        if result.formal_construct_status_change != "none":
            return f"verification {result.result_id!r} reports formal status change"
        if result.reference_status_granted:
            return f"verification {result.result_id!r} reports reference status grant"
        if result.open_ended_experiment_allowed:
            return f"verification {result.result_id!r} reports open-ended experiment"

    if not packet.signed_by:
        return "read-only git inspection decision is missing signed_by"
    if not packet.signature_token:
        return "read-only git inspection decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_git_write_operations",
        "allow_runtime_branch_creation",
        "allow_runtime_file_staging",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_file_mutation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"read-only git inspection decision attempted to allow {key}"

    if packet.inspection_decision == "accept_read_only_git_inspection":
        if packet.approved_inspection_state != "read_only_git_inspection_ready":
            return (
                "accepted read-only git inspection decision must approve "
                "read_only_git_inspection_ready"
            )
        required_true_constraints = (
            "allow_read_only_git_inspection",
            "allow_read_only_git_operations",
            "allow_git_status",
            "allow_git_diff_check",
            "allow_commit_preparation_packet",
        )
        for key in required_true_constraints:
            if not bool(packet.constraints.get(key, False)):
                return f"accepted read-only git inspection decision must allow {key}"
        if not packet.inspection_commands:
            return "accepted read-only git inspection decision has no commands"
        for command in packet.inspection_commands:
            command_block = _read_only_git_inspection_command_block_reason(command)
            if command_block is not None:
                return command_block
        commit_block = _commit_preparation_block_reason(packet.commit_preparation)
        if commit_block is not None:
            return commit_block

    return None


def _read_only_git_inspection_command_block_reason(command: dict[str, Any]) -> str | None:
    argv = command.get("argv")
    if not isinstance(argv, list) or not argv:
        return "read-only git inspection command argv must be a non-empty list"
    if not all(isinstance(item, str) and item for item in argv):
        return "read-only git inspection command argv entries must be non-empty strings"
    executable = Path(argv[0]).name.lower()
    if executable not in {"git", "git.exe"}:
        return "read-only git inspection command must use git"
    normalized = ("git", *argv[1:])
    allowed_commands = {
        ("git", "status", "--short", "--branch"),
        ("git", "branch", "--show-current"),
        ("git", "diff", "--check"),
        ("git", "diff", "--name-only"),
        ("git", "ls-files", "--others", "--exclude-standard"),
        ("git", "rev-parse", "--show-toplevel"),
        ("git", "rev-parse", "--abbrev-ref", "HEAD"),
    }
    if normalized not in allowed_commands:
        return f"git inspection command {normalized!r} is not allowlisted"
    timeout = _int_from_any(command.get("timeout_seconds"))
    if timeout is not None and timeout < 1:
        return "read-only git inspection command timeout_seconds must be positive"
    return None


def _commit_preparation_block_reason(commit_preparation: dict[str, Any]) -> str | None:
    branch_name = str(commit_preparation.get("branch_name") or "")
    if branch_name and not branch_name.startswith("codex/"):
        return "commit preparation branch_name must start with codex/"
    commit_message = str(commit_preparation.get("commit_message") or "")
    if not commit_message.strip():
        return "commit preparation requires a non-empty commit_message"
    forbidden_true_flags = (
        "allow_branch_creation",
        "allow_file_staging",
        "allow_commit_creation",
        "allow_push",
        "allow_pull_request_creation",
    )
    for key in forbidden_true_flags:
        if bool(commit_preparation.get(key, False)):
            return f"commit preparation attempted to allow {key}"
    return None


def _source_control_read_only_git_inspection_from_verification_results(
    *,
    packet: SourceControlReadOnlyGitInspectionDecisionPacket,
    verification_results: tuple[SourceControlPostChangeVerificationResult, ...],
    worktree_root: Path,
    output_dir: Path,
    command_output_dir: Path,
    timeout_seconds: int,
) -> SourceControlReadOnlyGitInspectionResult:
    result_id = _safe_artifact_id(f"{packet.decision_id}_read_only_git_inspection")
    command_results = _source_control_execute_read_only_git_inspection_commands(
        packet.inspection_commands,
        worktree_root=worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        timeout_seconds=timeout_seconds,
    )
    all_commands_passed = all(bool(item.get("passed")) for item in command_results)
    diff_check_passed = _read_only_git_command_passed(command_results, ("git", "diff", "--check"))
    status_output = _read_only_git_command_stdout(
        command_results,
        ("git", "status", "--short", "--branch"),
    )
    changed_paths_output = _read_only_git_command_stdout(
        command_results,
        ("git", "diff", "--name-only"),
    )
    untracked_output = _read_only_git_command_stdout(
        command_results,
        ("git", "ls-files", "--others", "--exclude-standard"),
    )
    branch_output = _read_only_git_command_stdout(
        command_results,
        ("git", "branch", "--show-current"),
    ) or _read_only_git_command_stdout(
        command_results,
        ("git", "rev-parse", "--abbrev-ref", "HEAD"),
    )
    worktree_dirty = any(
        line.strip() and not line.startswith("##")
        for line in status_output.splitlines()
    )
    commit_ready = all_commands_passed and diff_check_passed and worktree_dirty
    inspection_state = (
        "read_only_git_inspection_passed"
        if all_commands_passed and diff_check_passed
        else "read_only_git_inspection_failed"
    )
    commit_packet = _source_control_commit_preparation_packet(
        packet=packet,
        result_id=result_id,
        verification_results=verification_results,
        current_branch=branch_output.strip(),
        status_output=status_output,
        changed_paths=tuple(
            line.strip() for line in changed_paths_output.splitlines() if line.strip()
        ),
        untracked_paths=tuple(
            line.strip() for line in untracked_output.splitlines() if line.strip()
        ),
        commit_ready=commit_ready,
        output_dir=output_dir,
    )
    findings = (
        f"{len(command_results)} read-only git inspection commands executed",
        (
            "all read-only git inspection commands passed"
            if all_commands_passed
            else "one or more read-only git inspection commands failed"
        ),
        (
            "git diff --check passed"
            if diff_check_passed
            else "git diff --check did not pass"
        ),
        (
            "worktree has commit-preparation material"
            if worktree_dirty
            else "worktree has no commit-preparation material"
        ),
        "no git write operations were executed",
    )
    return SourceControlReadOnlyGitInspectionResult(
        result_id=result_id,
        source_decision_id=packet.decision_id,
        target_post_change_verification_result_ids=tuple(
            result.result_id for result in verification_results
        ),
        target_focus_node_ids=tuple(result.focus_node_id for result in verification_results),
        inspection_state=inspection_state,
        inspection_mode="read_only_git_status_diff_commit_preparation_no_index_mutation",
        command_results=tuple(command_results),
        commit_preparation_packet=commit_packet,
        findings=findings,
        required_external_actions=(
            "inspect read-only git command outputs before any staging operation",
            "stage files only after an explicit runtime file-staging authority decision",
            "create commits only after an explicit runtime commit authority decision",
            "do not push or open pull requests from the read-only git inspector",
            "do not infer formal construct status changes from git readiness",
        ),
    )


def _source_control_execute_read_only_git_inspection_commands(
    commands: tuple[dict[str, Any], ...],
    *,
    worktree_root: Path,
    output_dir: Path,
    result_id: str,
    timeout_seconds: int,
) -> tuple[dict[str, Any], ...]:
    output_dir.mkdir(parents=True, exist_ok=True)
    results: list[dict[str, Any]] = []
    max_timeout = max(1, timeout_seconds)
    for index, command in enumerate(commands, start=1):
        command_id = _safe_artifact_id(str(command.get("command_id") or f"git_command_{index}"))
        argv = tuple(str(item) for item in command.get("argv", ()))
        command_timeout = _int_from_any(command.get("timeout_seconds")) or max_timeout
        command_timeout = max(1, min(command_timeout, max_timeout))
        stdout_path = output_dir / f"{result_id}_{command_id}_stdout.txt"
        stderr_path = output_dir / f"{result_id}_{command_id}_stderr.txt"
        started = time.time()
        timeout_expired = False
        try:
            completed = subprocess.run(
                list(argv),
                cwd=worktree_root,
                capture_output=True,
                text=True,
                timeout=command_timeout,
                check=False,
                env={**os.environ, "GIT_OPTIONAL_LOCKS": "0"},
            )
            exit_code: int | None = completed.returncode
            stdout = completed.stdout
            stderr = completed.stderr
        except subprocess.TimeoutExpired as exc:
            timeout_expired = True
            exit_code = None
            stdout = _subprocess_output_to_text(exc.stdout)
            stderr = _subprocess_output_to_text(exc.stderr)
        duration_seconds = round(time.time() - started, 3)
        _write_artifact(stdout_path, stdout)
        _write_artifact(stderr_path, stderr)
        results.append(
            {
                "command_id": command_id,
                "argv": argv,
                "cwd": str(worktree_root),
                "timeout_seconds": command_timeout,
                "duration_seconds": duration_seconds,
                "exit_code": exit_code,
                "passed": exit_code == 0 and not timeout_expired,
                "timeout_expired": timeout_expired,
                "stdout_path": str(stdout_path),
                "stderr_path": str(stderr_path),
                "stdout_excerpt": stdout[:4000],
                "stderr_excerpt": stderr[:4000],
                "read_only_git_operation": True,
                "git_write_operation": False,
                "worktree_modified_by_inspection": False,
                "index_modified_by_inspection": False,
            }
        )
    return tuple(results)


def _read_only_git_command_key(command_result: dict[str, Any]) -> tuple[str, ...]:
    argv = command_result.get("argv")
    if not isinstance(argv, (list, tuple)):
        return ()
    clean = tuple(str(item) for item in argv)
    if not clean:
        return ()
    return ("git", *clean[1:]) if Path(clean[0]).name.lower() in {"git", "git.exe"} else clean


def _read_only_git_command_passed(
    command_results: tuple[dict[str, Any], ...],
    command_key: tuple[str, ...],
) -> bool:
    return any(
        _read_only_git_command_key(result) == command_key and bool(result.get("passed"))
        for result in command_results
    )


def _read_only_git_command_stdout(
    command_results: tuple[dict[str, Any], ...],
    command_key: tuple[str, ...],
) -> str:
    for result in command_results:
        if _read_only_git_command_key(result) == command_key:
            path = Path(str(result.get("stdout_path") or ""))
            if path.exists():
                return path.read_text(encoding="utf-8")
            return str(result.get("stdout_excerpt") or "")
    return ""


def _source_control_commit_preparation_packet(
    *,
    packet: SourceControlReadOnlyGitInspectionDecisionPacket,
    result_id: str,
    verification_results: tuple[SourceControlPostChangeVerificationResult, ...],
    current_branch: str,
    status_output: str,
    changed_paths: tuple[str, ...],
    untracked_paths: tuple[str, ...],
    commit_ready: bool,
    output_dir: Path,
) -> dict[str, Any]:
    commit_preparation = packet.commit_preparation
    branch_name = str(commit_preparation.get("branch_name") or current_branch)
    commit_message = str(commit_preparation.get("commit_message") or "")
    status_lines = tuple(line for line in status_output.splitlines() if line.strip())
    return {
        "schema": "consciousness_benchmark.source_control_commit_preparation_packet.v1",
        "packet_id": f"{result_id}_commit_preparation",
        "source_read_only_git_inspection_result_id": result_id,
        "target_post_change_verification_result_ids": [
            result.result_id for result in verification_results
        ],
        "target_focus_node_ids": [result.focus_node_id for result in verification_results],
        "current_branch": current_branch,
        "branch_name": branch_name,
        "commit_message": commit_message,
        "commit_ready": commit_ready,
        "tracked_changed_paths": list(changed_paths),
        "untracked_paths": list(untracked_paths),
        "status_line_count": len(status_lines),
        "status_excerpt": "\n".join(status_lines[:80]),
        "recommended_output_dir": str(output_dir),
        "allowed_git_operations": {
            "read_only_status": True,
            "read_only_diff_check": True,
            "branch_creation": False,
            "file_staging": False,
            "commit_creation": False,
            "push": False,
            "pull_request_creation": False,
        },
        "branch_created": False,
        "files_staged": False,
        "commit_created": False,
        "push_performed": False,
        "pull_request_created": False,
        "requires_external_operator": True,
        "next_required_gate": "runtime_file_staging_and_commit_authority",
    }


def _deferred_source_control_post_change_verification_results(
    verification_results: tuple[SourceControlPostChangeVerificationResult, ...],
    *,
    consumed_verification_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in verification_results:
        if result.result_id in consumed_verification_result_ids:
            continue
        deferred.append(
            {
                "post_change_verification_result_id": result.result_id,
                "focus_node_id": result.focus_node_id,
                "verification_state": result.verification_state,
                "deferred_reason": (
                    "no accepted external read-only git inspection decision packet"
                ),
                "recommended_next_gate": "read_only_git_inspection_and_commit_preparation",
                "read_only_git_inspection_executed": False,
                "git_write_operations_executed": False,
                "files_staged": False,
                "commit_created": False,
                "branch_created": False,
                "push_performed": False,
                "pull_request_created": False,
                "source_registry_mutated": False,
                "formal_construct_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_read_only_git_inspection_memory(
    *,
    verification_report: SourceControlPostChangeVerificationReport,
    decision_packets: tuple[SourceControlReadOnlyGitInspectionDecisionPacket, ...],
    inspection_results: tuple[SourceControlReadOnlyGitInspectionResult, ...],
    deferred_verification_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    passed = sum(
        1
        for result in inspection_results
        if result.inspection_state == "read_only_git_inspection_passed"
    )
    return (
        {
            "memory_id": "a27_read_only_git_inspection_summary",
            "retained_learning": (
                f"{passed} of {len(inspection_results)} read-only git inspections "
                "passed after post-change verification"
            ),
            "recommended_strategy": (
                "allow read-only git inspection and commit readiness packets, but "
                "keep file staging, branch creation, commit creation, push, and PR "
                "operations behind a separate authority gate"
            ),
            "read_only_git_operations_allowed": True,
            "git_write_operations_allowed": False,
            "commit_preparation_packet_allowed": True,
            "formal_status_transition_allowed": False,
        },
        {
            "memory_id": "a27_deferred_post_change_verification_summary",
            "retained_learning": (
                f"{len(deferred_verification_results)} of "
                f"{len(verification_report.post_change_verification_results)} "
                "post-change verification results remain without read-only git "
                "inspection decisions"
            ),
            "decision_packets_seen": len(decision_packets),
            "recommended_strategy": (
                "keep uninspected verification results outside commit preparation "
                "until explicit read-only git inspection decisions are available"
            ),
            "git_write_operations_allowed": False,
            "formal_status_transition_allowed": False,
        },
    )


def _source_control_read_only_git_inspection_review_packet_markdown(
    inspection_results: tuple[SourceControlReadOnlyGitInspectionResult, ...],
    deferred_verification_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Read-Only Git Inspection Review",
        "",
        "Status: A27 read-only git inspection packet. Runtime may execute exact allowlisted git inspection commands but does not write to git state.",
        "",
        "| Result | State | Commands | Commit Ready | Git Write Ops |",
        "|---|---|---:|---|---|",
    ]
    for result in inspection_results:
        commit_ready = result.commit_preparation_packet.get("commit_ready", False)
        lines.append(
            f"| `{result.result_id}` | `{result.inspection_state}` | "
            f"{len(result.command_results)} | `{commit_ready}` | "
            f"`{result.git_write_operations_executed}` |"
        )
    lines.extend(["", "## Deferred Post-Change Verification Results", ""])
    if not deferred_verification_results:
        lines.append("- none")
    else:
        for item in deferred_verification_results:
            lines.append(
                f"- `{item['focus_node_id']}`: {item['deferred_reason']}"
            )
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- read-only git inspection: exact allowlisted commands only",
            "- file staging: blocked",
            "- runtime branch creation: blocked",
            "- runtime commit creation: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- source registry mutation: blocked",
            "- formal construct status changes: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_existing_source_control_read_only_git_inspection_results(
    *,
    source_control_read_only_git_inspection_result_dirs: Iterable[Path],
    source_control_read_only_git_inspection_result_files: Iterable[Path],
) -> tuple[SourceControlReadOnlyGitInspectionResult, ...]:
    paths: list[Path] = []
    for result_dir in source_control_read_only_git_inspection_result_dirs:
        if result_dir.exists():
            paths.extend(sorted(result_dir.rglob("*.json")))
    for result_file in source_control_read_only_git_inspection_result_files:
        if result_file.exists():
            paths.append(result_file)

    results: list[SourceControlReadOnlyGitInspectionResult] = []
    seen_paths: set[Path] = set()
    seen_result_ids: set[str] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen_paths:
            continue
        seen_paths.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        candidate_payloads: list[dict[str, Any]] = []
        if isinstance(payload, dict):
            nested = payload.get("read_only_git_inspection_results")
            if isinstance(nested, list):
                candidate_payloads.extend(item for item in nested if isinstance(item, dict))
            elif "inspection_state" in payload and "result_id" in payload:
                candidate_payloads.append(payload)
        elif isinstance(payload, list):
            candidate_payloads.extend(item for item in payload if isinstance(item, dict))
        for candidate in candidate_payloads:
            result = _source_control_read_only_git_inspection_result_from_payload(candidate)
            if result.result_id in seen_result_ids:
                continue
            results.append(result)
            seen_result_ids.add(result.result_id)
    return tuple(results)


def _source_control_read_only_git_inspection_result_from_payload(
    payload: dict[str, Any],
) -> SourceControlReadOnlyGitInspectionResult:
    return SourceControlReadOnlyGitInspectionResult(
        result_id=str(payload.get("result_id") or "unknown_read_only_git_inspection"),
        source_decision_id=str(payload.get("source_decision_id") or "unknown"),
        target_post_change_verification_result_ids=tuple(
            str(item)
            for item in payload.get("target_post_change_verification_result_ids", [])
            if isinstance(item, str)
        ),
        target_focus_node_ids=tuple(
            str(item)
            for item in payload.get("target_focus_node_ids", [])
            if isinstance(item, str)
        ),
        inspection_state=str(payload.get("inspection_state") or "unknown"),
        inspection_mode=str(payload.get("inspection_mode") or "unknown"),
        command_results=tuple(
            item
            for item in payload.get("command_results", [])
            if isinstance(item, dict)
        ),
        commit_preparation_packet=(
            payload.get("commit_preparation_packet")
            if isinstance(payload.get("commit_preparation_packet"), dict)
            else {}
        ),
        findings=tuple(
            str(item) for item in payload.get("findings", []) if isinstance(item, str)
        ),
        required_external_actions=tuple(
            str(item)
            for item in payload.get("required_external_actions", [])
            if isinstance(item, str)
        ),
        read_only_git_inspection_executed=bool(
            payload.get("read_only_git_inspection_executed", True)
        ),
        read_only_git_operations_executed=bool(
            payload.get("read_only_git_operations_executed", True)
        ),
        git_operations_executed=bool(
            payload.get("git_operations_executed", payload.get("runtime_git_operations_executed", True))
        ),
        git_write_operations_executed=bool(
            payload.get("git_write_operations_executed", False)
        ),
        worktree_modified_by_inspection=bool(
            payload.get("worktree_modified_by_inspection", False)
        ),
        source_files_modified_by_inspection=bool(
            payload.get("source_files_modified_by_inspection", False)
        ),
        index_modified_by_inspection=bool(
            payload.get("index_modified_by_inspection", False)
        ),
        branch_created=bool(payload.get("branch_created", payload.get("runtime_branch_created", False))),
        files_staged=bool(payload.get("files_staged", payload.get("runtime_files_staged", False))),
        commit_created=bool(payload.get("commit_created", payload.get("runtime_commit_created", False))),
        push_performed=bool(payload.get("push_performed", payload.get("runtime_push_performed", False))),
        pull_request_created=bool(
            payload.get("pull_request_created", payload.get("runtime_pull_request_created", False))
        ),
        source_registry_mutated=bool(payload.get("source_registry_mutated", False)),
        formal_construct_status_change=str(
            payload.get("formal_construct_status_change") or "none"
        ),
        reference_status_granted=bool(payload.get("reference_status_granted", False)),
        open_ended_experiment_allowed=bool(
            payload.get("open_ended_experiment_allowed", False)
        ),
    )


def _load_source_control_staging_commit_preflight_decisions(
    *,
    source_control_staging_commit_preflight_decision_dirs: Iterable[Path],
    source_control_staging_commit_preflight_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlStagingCommitPreflightDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_staging_commit_preflight_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_staging_commit_preflight_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlStagingCommitPreflightDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(
            _source_control_staging_commit_preflight_decision_from_payload(
                payload,
                path,
            )
        )
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_staging_commit_preflight_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlStagingCommitPreflightDecisionPacket:
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    target_result_ids = payload.get("target_read_only_git_inspection_result_ids")
    target_focus_ids = payload.get("target_focus_node_ids")
    stage_paths = payload.get("stage_paths")
    commit_plan = payload.get("commit_plan")
    return SourceControlStagingCommitPreflightDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_read_only_git_inspection_result_ids=(
            tuple(str(item) for item in target_result_ids)
            if isinstance(target_result_ids, list)
            else ()
        ),
        target_focus_node_ids=(
            tuple(str(item) for item in target_focus_ids)
            if isinstance(target_focus_ids, list)
            else ()
        ),
        preflight_decision=str(payload.get("preflight_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_preflight_state=str(
            payload.get("approved_preflight_state") or "unknown"
        ),
        stage_paths=(
            tuple(str(item) for item in stage_paths)
            if isinstance(stage_paths, list)
            else ()
        ),
        commit_plan=commit_plan if isinstance(commit_plan, dict) else {},
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=(
            str(payload["signed_by"])
            if isinstance(payload.get("signed_by"), str)
            else None
        ),
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_staging_commit_preflight_block_reason(
    *,
    packet: SourceControlStagingCommitPreflightDecisionPacket,
    inspection_results: tuple[SourceControlReadOnlyGitInspectionResult, ...],
    worktree_root: Path,
) -> str | None:
    allowed_decisions = {
        "accept_staging_commit_preflight",
        "defer_staging_commit_preflight",
        "reject_staging_commit_preflight",
    }
    if packet.preflight_decision not in allowed_decisions:
        return f"preflight_decision {packet.preflight_decision!r} is not allowed"
    if packet.review_gate != "staging_commit_authority_preflight":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'staging_commit_authority_preflight'"
        )
    allowed_states = {
        "staging_commit_preflight_ready",
        "deferred_by_staging_commit_preflight_review",
        "rejected_by_staging_commit_preflight_review",
    }
    if packet.approved_preflight_state not in allowed_states:
        return (
            f"approved_preflight_state {packet.approved_preflight_state!r} "
            "is not allowed"
        )
    if not packet.target_read_only_git_inspection_result_ids:
        return "staging commit preflight decision has no target inspection results"
    found_result_ids = {result.result_id for result in inspection_results}
    missing_result_ids = [
        result_id
        for result_id in packet.target_read_only_git_inspection_result_ids
        if result_id not in found_result_ids
    ]
    if missing_result_ids:
        return (
            "target A27 read-only git inspection results were not found: "
            + ", ".join(missing_result_ids)
        )
    focus_ids = set().union(*(set(result.target_focus_node_ids) for result in inspection_results))
    if set(packet.target_focus_node_ids) != focus_ids:
        return "target_focus_node_ids do not match target inspection focus ids"
    for result in inspection_results:
        if result.inspection_state != "read_only_git_inspection_passed":
            return f"read-only git inspection result {result.result_id!r} is not passed"
        if not result.read_only_git_inspection_executed:
            return f"read-only git inspection {result.result_id!r} was not executed"
        if result.git_write_operations_executed:
            return f"read-only git inspection {result.result_id!r} reports git writes"
        if result.index_modified_by_inspection or result.files_staged:
            return f"read-only git inspection {result.result_id!r} reports index mutation"
        if result.branch_created or result.commit_created:
            return f"read-only git inspection {result.result_id!r} reports branch or commit creation"
        if result.push_performed or result.pull_request_created:
            return f"read-only git inspection {result.result_id!r} reports push or pull request"
        if result.source_registry_mutated:
            return f"read-only git inspection {result.result_id!r} reports registry mutation"
        if result.formal_construct_status_change != "none":
            return f"read-only git inspection {result.result_id!r} reports formal status change"
        if result.reference_status_granted:
            return f"read-only git inspection {result.result_id!r} reports reference status grant"
        if result.open_ended_experiment_allowed:
            return f"read-only git inspection {result.result_id!r} reports open-ended experiment"
        if not bool(result.commit_preparation_packet.get("commit_ready", False)):
            return f"read-only git inspection {result.result_id!r} is not commit-ready"
    if not packet.signed_by:
        return "staging commit preflight decision is missing signed_by"
    if not packet.signature_token:
        return "staging commit preflight decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_git_write_operations",
        "allow_runtime_branch_creation",
        "allow_runtime_file_staging",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_file_mutation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"staging commit preflight decision attempted to allow {key}"

    if packet.preflight_decision == "accept_staging_commit_preflight":
        if packet.approved_preflight_state != "staging_commit_preflight_ready":
            return (
                "accepted staging commit preflight decision must approve "
                "staging_commit_preflight_ready"
            )
        required_true_constraints = (
            "allow_staging_commit_preflight",
            "allow_stage_path_boundary_check",
            "allow_commit_command_plan",
            "allow_staging_plan_packet",
        )
        for key in required_true_constraints:
            if not bool(packet.constraints.get(key, False)):
                return f"accepted staging commit preflight decision must allow {key}"
        if not packet.stage_paths:
            return "accepted staging commit preflight decision has no stage paths"
        for path_text in packet.stage_paths:
            check = _stage_path_boundary_check(path_text, worktree_root)
            if not check["passed"]:
                return str(check["reason"])
        commit_block = _staging_commit_plan_block_reason(packet.commit_plan)
        if commit_block is not None:
            return commit_block
    return None


def _stage_path_boundary_check(path_text: str, worktree_root: Path) -> dict[str, Any]:
    reason = "ok"
    path = Path(path_text)
    if not path_text.strip():
        reason = "stage path is empty"
    elif path.is_absolute():
        reason = "stage path must be relative"
    elif any(part == ".." for part in path.parts):
        reason = "stage path must not contain parent traversal"
    elif path.parts and path.parts[0] == ".git":
        reason = "stage path must not target .git"
    else:
        resolved = (worktree_root / path).resolve()
        try:
            resolved.relative_to(worktree_root)
        except ValueError:
            reason = "stage path resolves outside worktree"
        else:
            if not resolved.exists():
                reason = "stage path does not exist"
            elif not resolved.is_file():
                reason = "stage path must be a file"
    resolved_text = ""
    try:
        resolved_text = str((worktree_root / path).resolve())
    except OSError:
        resolved_text = str(worktree_root / path)
    return {
        "path": path_text,
        "resolved_path": resolved_text,
        "passed": reason == "ok",
        "reason": reason,
    }


def _staging_commit_plan_block_reason(commit_plan: dict[str, Any]) -> str | None:
    branch_name = str(commit_plan.get("branch_name") or "")
    if branch_name and not branch_name.startswith("codex/"):
        return "commit plan branch_name must start with codex/"
    commit_message = str(commit_plan.get("commit_message") or "")
    if not commit_message.strip():
        return "commit plan requires a non-empty commit_message"
    forbidden_true_flags = (
        "allow_branch_creation",
        "allow_file_staging",
        "allow_commit_creation",
        "allow_push",
        "allow_pull_request_creation",
    )
    for key in forbidden_true_flags:
        if bool(commit_plan.get(key, False)):
            return f"commit plan attempted to allow {key}"
    return None


def _source_control_staging_commit_preflight_from_inspection_results(
    *,
    packet: SourceControlStagingCommitPreflightDecisionPacket,
    inspection_results: tuple[SourceControlReadOnlyGitInspectionResult, ...],
    worktree_root: Path,
    output_dir: Path,
) -> SourceControlStagingCommitPreflightResult:
    result_id = _safe_artifact_id(f"{packet.decision_id}_staging_commit_preflight")
    path_checks = tuple(
        _stage_path_boundary_check(path_text, worktree_root)
        for path_text in packet.stage_paths
    )
    all_paths_passed = all(bool(item.get("passed")) for item in path_checks)
    upstream_commit_ready = all(
        bool(result.commit_preparation_packet.get("commit_ready", False))
        for result in inspection_results
    )
    preflight_ready = all_paths_passed and upstream_commit_ready
    commit_message = str(packet.commit_plan.get("commit_message") or "")
    branch_name = str(packet.commit_plan.get("branch_name") or "")
    command_plan = {
        "schema": "consciousness_benchmark.source_control_staging_commit_command_plan.v1",
        "plan_id": f"{result_id}_command_plan",
        "source_preflight_decision_id": packet.decision_id,
        "stage_paths": list(packet.stage_paths),
        "planned_commands": [
            {
                "command_id": "git_add_stage_paths",
                "argv": ["git", "add", "--", *packet.stage_paths],
                "execution_allowed_in_a28": False,
            },
            {
                "command_id": "git_commit_with_message",
                "argv": ["git", "commit", "-m", commit_message],
                "execution_allowed_in_a28": False,
            },
        ],
        "branch_name": branch_name,
        "commit_message": commit_message,
        "preflight_ready": preflight_ready,
        "requires_external_operator": True,
        "next_required_gate": "runtime_staging_and_commit_execution_authority",
        "git_write_operations_executed": False,
        "files_staged": False,
        "commit_created": False,
        "push_performed": False,
        "pull_request_created": False,
    }
    preflight_packet = {
        "schema": "consciousness_benchmark.source_control_staging_commit_preflight_packet.v1",
        "packet_id": f"{result_id}_preflight_packet",
        "source_preflight_decision_id": packet.decision_id,
        "target_read_only_git_inspection_result_ids": [
            result.result_id for result in inspection_results
        ],
        "target_focus_node_ids": list(packet.target_focus_node_ids),
        "stage_paths": list(packet.stage_paths),
        "path_checks": list(path_checks),
        "path_checks_passed": all_paths_passed,
        "upstream_commit_ready": upstream_commit_ready,
        "staging_commit_preflight_ready": preflight_ready,
        "branch_name": branch_name,
        "commit_message": commit_message,
        "recommended_output_dir": str(output_dir),
        "allowed_git_operations": {
            "stage_path_boundary_check": True,
            "staging_command_plan": True,
            "commit_command_plan": True,
            "branch_creation": False,
            "file_staging": False,
            "commit_creation": False,
            "push": False,
            "pull_request_creation": False,
        },
        "branch_created": False,
        "files_staged": False,
        "commit_created": False,
        "push_performed": False,
        "pull_request_created": False,
        "requires_external_operator": True,
        "next_required_gate": "runtime_staging_and_commit_execution_authority",
    }
    preflight_state = (
        "staging_commit_preflight_passed"
        if preflight_ready
        else "staging_commit_preflight_failed"
    )
    findings = (
        f"{len(path_checks)} stage path boundary checks executed",
        (
            "all stage paths passed boundary checks"
            if all_paths_passed
            else "one or more stage paths failed boundary checks"
        ),
        (
            "upstream A27 commit readiness confirmed"
            if upstream_commit_ready
            else "upstream A27 commit readiness was not confirmed"
        ),
        "staging and commit commands were planned but not executed",
        "no git write operations were executed",
    )
    return SourceControlStagingCommitPreflightResult(
        result_id=result_id,
        source_decision_id=packet.decision_id,
        target_read_only_git_inspection_result_ids=tuple(
            result.result_id for result in inspection_results
        ),
        target_focus_node_ids=packet.target_focus_node_ids,
        preflight_state=preflight_state,
        preflight_mode="stage_path_and_commit_command_preflight_no_index_mutation",
        path_checks=path_checks,
        staging_commit_command_plan=command_plan,
        staging_commit_preflight_packet=preflight_packet,
        findings=findings,
        required_external_actions=(
            "review stage path boundary checks before executing git add",
            "execute staging only after explicit runtime staging authority",
            "execute commit only after explicit runtime commit authority",
            "keep push and pull request creation behind separate higher-risk gates",
            "do not infer formal construct status changes from commit preflight readiness",
        ),
    )


def _deferred_source_control_read_only_git_inspection_results(
    inspection_results: tuple[SourceControlReadOnlyGitInspectionResult, ...],
    *,
    consumed_inspection_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in inspection_results:
        if result.result_id in consumed_inspection_result_ids:
            continue
        deferred.append(
            {
                "read_only_git_inspection_result_id": result.result_id,
                "target_focus_node_ids": list(result.target_focus_node_ids),
                "inspection_state": result.inspection_state,
                "deferred_reason": (
                    "no accepted external staging commit preflight decision packet"
                ),
                "recommended_next_gate": "staging_commit_authority_preflight",
                "staging_commit_preflight_executed": False,
                "git_write_operations_executed": False,
                "files_staged": False,
                "commit_created": False,
                "branch_created": False,
                "push_performed": False,
                "pull_request_created": False,
                "source_registry_mutated": False,
                "formal_construct_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_staging_commit_preflight_memory(
    *,
    read_only_git_report: SourceControlReadOnlyGitInspectionReport,
    decision_packets: tuple[SourceControlStagingCommitPreflightDecisionPacket, ...],
    preflight_results: tuple[SourceControlStagingCommitPreflightResult, ...],
    deferred_inspection_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    passed = sum(
        1
        for result in preflight_results
        if result.preflight_state == "staging_commit_preflight_passed"
    )
    return (
        {
            "memory_id": "a28_staging_commit_preflight_summary",
            "retained_learning": (
                f"{passed} of {len(preflight_results)} staging commit preflights "
                "passed after read-only git inspection"
            ),
            "recommended_strategy": (
                "allow stage path and command-plan validation, but keep actual "
                "index mutation and commit creation behind a separate execution "
                "authority gate"
            ),
            "stage_path_boundary_checks_allowed": True,
            "staging_plan_allowed": True,
            "commit_command_plan_allowed": True,
            "git_write_operations_allowed": False,
            "formal_status_transition_allowed": False,
        },
        {
            "memory_id": "a28_deferred_read_only_git_inspection_summary",
            "retained_learning": (
                f"{len(deferred_inspection_results)} of "
                f"{len(read_only_git_report.read_only_git_inspection_results)} "
                "read-only git inspection results remain without staging commit "
                "preflight decisions"
            ),
            "decision_packets_seen": len(decision_packets),
            "recommended_strategy": (
                "keep unpreflighted inspection results outside staging and commit "
                "execution until explicit preflight decisions are available"
            ),
            "git_write_operations_allowed": False,
            "formal_status_transition_allowed": False,
        },
    )


def _source_control_staging_commit_preflight_review_packet_markdown(
    preflight_results: tuple[SourceControlStagingCommitPreflightResult, ...],
    deferred_inspection_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Staging And Commit Preflight Review",
        "",
        "Status: A28 staging and commit preflight packet. Runtime validates paths and writes command plans but does not mutate git state.",
        "",
        "| Result | State | Paths | Plan Ready | Git Write Ops |",
        "|---|---|---:|---|---|",
    ]
    for result in preflight_results:
        plan_ready = result.staging_commit_preflight_packet.get(
            "staging_commit_preflight_ready",
            False,
        )
        lines.append(
            f"| `{result.result_id}` | `{result.preflight_state}` | "
            f"{len(result.path_checks)} | `{plan_ready}` | "
            f"`{result.git_write_operations_executed}` |"
        )
    lines.extend(["", "## Deferred Read-Only Git Inspection Results", ""])
    if not deferred_inspection_results:
        lines.append("- none")
    else:
        for item in deferred_inspection_results:
            focus = ", ".join(item["target_focus_node_ids"])
            lines.append(f"- `{focus}`: {item['deferred_reason']}")
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- stage path boundary validation: allowed",
            "- command plan writing: allowed",
            "- file staging: blocked",
            "- runtime branch creation: blocked",
            "- runtime commit creation: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- source registry mutation: blocked",
            "- formal construct status changes: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_existing_source_control_staging_commit_preflight_results(
    *,
    source_control_staging_commit_preflight_result_dirs: Iterable[Path],
    source_control_staging_commit_preflight_result_files: Iterable[Path],
) -> tuple[SourceControlStagingCommitPreflightResult, ...]:
    paths: list[Path] = []
    for result_dir in source_control_staging_commit_preflight_result_dirs:
        if result_dir.exists():
            paths.extend(sorted(result_dir.rglob("*.json")))
    for result_file in source_control_staging_commit_preflight_result_files:
        if result_file.exists():
            paths.append(result_file)

    results: list[SourceControlStagingCommitPreflightResult] = []
    seen_paths: set[Path] = set()
    seen_result_ids: set[str] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen_paths:
            continue
        seen_paths.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        candidate_payloads: list[dict[str, Any]] = []
        if isinstance(payload, dict):
            nested = payload.get("staging_commit_preflight_results")
            if isinstance(nested, list):
                candidate_payloads.extend(item for item in nested if isinstance(item, dict))
            elif "preflight_state" in payload and "result_id" in payload:
                candidate_payloads.append(payload)
        elif isinstance(payload, list):
            candidate_payloads.extend(item for item in payload if isinstance(item, dict))
        for candidate in candidate_payloads:
            result = _source_control_staging_commit_preflight_result_from_payload(candidate)
            if result.result_id in seen_result_ids:
                continue
            results.append(result)
            seen_result_ids.add(result.result_id)
    return tuple(results)


def _source_control_staging_commit_preflight_result_from_payload(
    payload: dict[str, Any],
) -> SourceControlStagingCommitPreflightResult:
    return SourceControlStagingCommitPreflightResult(
        result_id=str(payload.get("result_id") or "unknown_staging_commit_preflight"),
        source_decision_id=str(payload.get("source_decision_id") or "unknown"),
        target_read_only_git_inspection_result_ids=tuple(
            str(item)
            for item in payload.get("target_read_only_git_inspection_result_ids", [])
            if isinstance(item, str)
        ),
        target_focus_node_ids=tuple(
            str(item) for item in payload.get("target_focus_node_ids", []) if isinstance(item, str)
        ),
        preflight_state=str(payload.get("preflight_state") or "unknown"),
        preflight_mode=str(payload.get("preflight_mode") or "unknown"),
        path_checks=tuple(
            item for item in payload.get("path_checks", []) if isinstance(item, dict)
        ),
        staging_commit_command_plan=(
            payload.get("staging_commit_command_plan")
            if isinstance(payload.get("staging_commit_command_plan"), dict)
            else {}
        ),
        staging_commit_preflight_packet=(
            payload.get("staging_commit_preflight_packet")
            if isinstance(payload.get("staging_commit_preflight_packet"), dict)
            else {}
        ),
        findings=tuple(
            str(item) for item in payload.get("findings", []) if isinstance(item, str)
        ),
        required_external_actions=tuple(
            str(item)
            for item in payload.get("required_external_actions", [])
            if isinstance(item, str)
        ),
        stage_path_boundary_checks_executed=bool(
            payload.get("stage_path_boundary_checks_executed", True)
        ),
        staging_plan_written=bool(payload.get("staging_plan_written", True)),
        commit_command_plan_written=bool(payload.get("commit_command_plan_written", True)),
        git_operations_executed=bool(
            payload.get("git_operations_executed", payload.get("runtime_git_operations_executed", False))
        ),
        git_write_operations_executed=bool(
            payload.get("git_write_operations_executed", False)
        ),
        worktree_modified_by_preflight=bool(
            payload.get("worktree_modified_by_preflight", False)
        ),
        source_files_modified_by_preflight=bool(
            payload.get("source_files_modified_by_preflight", False)
        ),
        index_modified_by_preflight=bool(payload.get("index_modified_by_preflight", False)),
        branch_created=bool(payload.get("branch_created", payload.get("runtime_branch_created", False))),
        files_staged=bool(payload.get("files_staged", payload.get("runtime_files_staged", False))),
        commit_created=bool(payload.get("commit_created", payload.get("runtime_commit_created", False))),
        push_performed=bool(payload.get("push_performed", payload.get("runtime_push_performed", False))),
        pull_request_created=bool(
            payload.get("pull_request_created", payload.get("runtime_pull_request_created", False))
        ),
        source_registry_mutated=bool(payload.get("source_registry_mutated", False)),
        formal_construct_status_change=str(
            payload.get("formal_construct_status_change") or "none"
        ),
        reference_status_granted=bool(payload.get("reference_status_granted", False)),
        open_ended_experiment_allowed=bool(payload.get("open_ended_experiment_allowed", False)),
    )


def _load_source_control_staging_commit_execution_decisions(
    *,
    source_control_staging_commit_execution_decision_dirs: Iterable[Path],
    source_control_staging_commit_execution_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlStagingCommitExecutionDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_staging_commit_execution_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_staging_commit_execution_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlStagingCommitExecutionDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(_source_control_staging_commit_execution_decision_from_payload(payload, path))
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_staging_commit_execution_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlStagingCommitExecutionDecisionPacket:
    target_result_ids = payload.get("target_staging_commit_preflight_result_ids")
    target_focus_ids = payload.get("target_focus_node_ids")
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    commit_author = payload.get("commit_author")
    return SourceControlStagingCommitExecutionDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_staging_commit_preflight_result_ids=(
            tuple(str(item) for item in target_result_ids)
            if isinstance(target_result_ids, list)
            else ()
        ),
        target_focus_node_ids=(
            tuple(str(item) for item in target_focus_ids)
            if isinstance(target_focus_ids, list)
            else ()
        ),
        execution_decision=str(payload.get("execution_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_execution_state=str(payload.get("approved_execution_state") or "unknown"),
        execution_mode=str(payload.get("execution_mode") or "unknown"),
        commit_author=commit_author if isinstance(commit_author, dict) else {},
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=str(payload["signed_by"]) if isinstance(payload.get("signed_by"), str) else None,
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_staging_commit_execution_block_reason(
    *,
    packet: SourceControlStagingCommitExecutionDecisionPacket,
    preflight_results: tuple[SourceControlStagingCommitPreflightResult, ...],
) -> str | None:
    allowed_decisions = {
        "accept_isolated_staging_commit_execution",
        "defer_isolated_staging_commit_execution",
        "reject_isolated_staging_commit_execution",
    }
    if packet.execution_decision not in allowed_decisions:
        return f"execution_decision {packet.execution_decision!r} is not allowed"
    if packet.review_gate != "isolated_staging_commit_execution":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'isolated_staging_commit_execution'"
        )
    allowed_states = {
        "isolated_staging_commit_execution_ready",
        "deferred_by_isolated_staging_commit_execution_review",
        "rejected_by_isolated_staging_commit_execution_review",
    }
    if packet.approved_execution_state not in allowed_states:
        return (
            f"approved_execution_state {packet.approved_execution_state!r} "
            "is not allowed"
        )
    if not packet.target_staging_commit_preflight_result_ids:
        return "staging commit execution decision has no target preflight results"
    found_result_ids = {result.result_id for result in preflight_results}
    missing_result_ids = [
        result_id
        for result_id in packet.target_staging_commit_preflight_result_ids
        if result_id not in found_result_ids
    ]
    if missing_result_ids:
        return (
            "target A28 staging commit preflight results were not found: "
            + ", ".join(missing_result_ids)
        )
    focus_ids = set().union(*(set(result.target_focus_node_ids) for result in preflight_results))
    if set(packet.target_focus_node_ids) != focus_ids:
        return "target_focus_node_ids do not match target preflight focus ids"
    if not packet.signed_by:
        return "staging commit execution decision is missing signed_by"
    if not packet.signature_token:
        return "staging commit execution decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_project_git_index_mutation",
        "allow_project_branch_creation",
        "allow_project_commit_creation",
        "allow_project_worktree_mutation",
        "allow_runtime_branch_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"staging commit execution decision attempted to allow {key}"

    if packet.execution_decision != "accept_isolated_staging_commit_execution":
        return None
    if packet.approved_execution_state != "isolated_staging_commit_execution_ready":
        return (
            "accepted staging commit execution decision must approve "
            "isolated_staging_commit_execution_ready"
        )
    if packet.execution_mode != "isolated_git_worktree":
        return "accepted staging commit execution decision must use isolated_git_worktree"
    required_true_constraints = (
        "allow_isolated_git_worktree",
        "allow_copy_approved_stage_paths",
        "allow_isolated_git_add",
        "allow_isolated_git_commit",
    )
    for key in required_true_constraints:
        if not bool(packet.constraints.get(key, False)):
            return f"accepted staging commit execution decision must allow {key}"
    author_name = str(packet.commit_author.get("name") or "").strip()
    author_email = str(packet.commit_author.get("email") or "").strip()
    if not author_name:
        return "accepted staging commit execution decision requires commit_author.name"
    if "@" not in author_email:
        return "accepted staging commit execution decision requires commit_author.email"

    for result in preflight_results:
        if result.preflight_state != "staging_commit_preflight_passed":
            return f"staging commit preflight result {result.result_id!r} is not passed"
        preflight_packet = result.staging_commit_preflight_packet
        if not bool(preflight_packet.get("staging_commit_preflight_ready", False)):
            return f"staging commit preflight result {result.result_id!r} is not ready"
        if not all(bool(item.get("passed")) for item in result.path_checks):
            return f"staging commit preflight result {result.result_id!r} has path failures"
        stage_paths = preflight_packet.get("stage_paths")
        if not isinstance(stage_paths, list) or not stage_paths:
            return f"staging commit preflight result {result.result_id!r} has no stage paths"
        commit_message = str(preflight_packet.get("commit_message") or "")
        if not commit_message.strip():
            return f"staging commit preflight result {result.result_id!r} lacks commit message"
        if result.git_write_operations_executed:
            return f"staging commit preflight result {result.result_id!r} reports git writes"
        if result.worktree_modified_by_preflight or result.source_files_modified_by_preflight:
            return f"staging commit preflight result {result.result_id!r} reports file mutation"
        if result.index_modified_by_preflight or result.files_staged:
            return f"staging commit preflight result {result.result_id!r} reports index mutation"
        if result.branch_created or result.commit_created:
            return f"staging commit preflight result {result.result_id!r} reports branch or commit"
        if result.push_performed or result.pull_request_created:
            return f"staging commit preflight result {result.result_id!r} reports push or PR"
        if result.source_registry_mutated:
            return f"staging commit preflight result {result.result_id!r} reports registry mutation"
        if result.formal_construct_status_change != "none":
            return f"staging commit preflight result {result.result_id!r} reports status change"
        if result.reference_status_granted:
            return f"staging commit preflight result {result.result_id!r} reports reference status"
        if result.open_ended_experiment_allowed:
            return f"staging commit preflight result {result.result_id!r} reports open experiment"
    return None


def _source_control_staging_commit_execution_from_preflight_results(
    *,
    packet: SourceControlStagingCommitExecutionDecisionPacket,
    preflight_results: tuple[SourceControlStagingCommitPreflightResult, ...],
    source_worktree_root: Path,
    execution_dir: Path,
    timeout_seconds: int,
) -> SourceControlStagingCommitExecutionResult:
    result_id = _safe_artifact_id(f"{packet.decision_id}_staging_commit_execution")
    stage_paths = tuple(
        dict.fromkeys(
            path
            for result in preflight_results
            for path in result.staging_commit_preflight_packet.get("stage_paths", [])
            if isinstance(path, str)
        )
    )
    commit_messages = tuple(
        dict.fromkeys(
            str(result.staging_commit_preflight_packet.get("commit_message") or "").strip()
            for result in preflight_results
            if str(result.staging_commit_preflight_packet.get("commit_message") or "").strip()
        )
    )
    commit_message = commit_messages[0] if commit_messages else "Isolated staging commit"
    repo_base = execution_dir / "iso_repos"
    repo_base.mkdir(parents=True, exist_ok=True)
    isolated_worktree_root = _unique_isolated_git_worktree_root(
        repo_base,
        _short_artifact_stem(result_id, prefix_chars=8),
    )
    isolated_worktree_root.mkdir(parents=True, exist_ok=True)
    command_output_dir = execution_dir / "cmd"

    current_path_checks = tuple(
        _stage_path_boundary_check(path_text, source_worktree_root) for path_text in stage_paths
    )
    if not all(bool(item.get("passed")) for item in current_path_checks):
        failed = tuple(str(item.get("reason")) for item in current_path_checks if not item.get("passed"))
        return SourceControlStagingCommitExecutionResult(
            result_id=result_id,
            source_decision_id=packet.decision_id,
            target_staging_commit_preflight_result_ids=tuple(
                result.result_id for result in preflight_results
            ),
            target_focus_node_ids=packet.target_focus_node_ids,
            execution_state="isolated_staging_commit_failed",
            execution_mode=packet.execution_mode,
            isolated_worktree_root=str(isolated_worktree_root),
            copied_paths=(),
            command_results=(),
            isolated_commit_hash=None,
            findings=(
                "current stage path boundary recheck failed before isolated git execution",
                *failed,
            ),
            required_external_actions=(
                "refresh A28 staging commit preflight path checks",
                "do not mutate the project git index",
            ),
            isolated_git_repository_created=False,
            isolated_files_staged=False,
            isolated_commit_created=False,
            git_operations_executed=False,
            git_write_operations_executed=False,
        )

    copied_paths = _copy_stage_paths_to_isolated_repo(
        stage_paths=stage_paths,
        source_worktree_root=source_worktree_root,
        isolated_worktree_root=isolated_worktree_root,
    )
    command_results: list[dict[str, Any]] = []
    command_timeout = max(1, timeout_seconds)
    init_result = _execute_isolated_git_command(
        ("git", "-c", "core.longpaths=true", "init"),
        cwd=isolated_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_init_isolated_repository",
        timeout_seconds=command_timeout,
        git_write_operation=True,
    )
    command_results.append(init_result)
    add_result: dict[str, Any] | None = None
    commit_result: dict[str, Any] | None = None
    rev_parse_result: dict[str, Any] | None = None
    isolated_commit_hash: str | None = None
    if init_result.get("passed") and copied_paths:
        add_result = _execute_isolated_git_command(
            ("git", "-c", "core.longpaths=true", "add", "--", *copied_paths),
            cwd=isolated_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_add_approved_stage_paths",
            timeout_seconds=command_timeout,
            git_write_operation=True,
        )
        command_results.append(add_result)
    if add_result is not None and add_result.get("passed"):
        commit_result = _execute_isolated_git_command(
            (
                "git",
                "-c",
                "core.longpaths=true",
                "-c",
                f"user.name={packet.commit_author.get('name')}",
                "-c",
                f"user.email={packet.commit_author.get('email')}",
                "commit",
                "-m",
                commit_message,
            ),
            cwd=isolated_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_commit_isolated_snapshot",
            timeout_seconds=command_timeout,
            git_write_operation=True,
        )
        command_results.append(commit_result)
    if commit_result is not None and commit_result.get("passed"):
        rev_parse_result = _execute_isolated_git_command(
            ("git", "-c", "core.longpaths=true", "rev-parse", "HEAD"),
            cwd=isolated_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_rev_parse_isolated_head",
            timeout_seconds=command_timeout,
            git_write_operation=False,
        )
        command_results.append(rev_parse_result)
        stdout_path = Path(str(rev_parse_result.get("stdout_path") or ""))
        stdout = stdout_path.read_text(encoding="utf-8").strip() if stdout_path.exists() else ""
        isolated_commit_hash = stdout.splitlines()[0].strip() if stdout else None

    isolated_files_staged = add_result is not None and bool(add_result.get("passed"))
    isolated_commit_created = (
        commit_result is not None and bool(commit_result.get("passed")) and bool(isolated_commit_hash)
    )
    execution_state = (
        "isolated_staging_commit_executed"
        if isolated_files_staged and isolated_commit_created
        else "isolated_staging_commit_failed"
    )
    return SourceControlStagingCommitExecutionResult(
        result_id=result_id,
        source_decision_id=packet.decision_id,
        target_staging_commit_preflight_result_ids=tuple(
            result.result_id for result in preflight_results
        ),
        target_focus_node_ids=packet.target_focus_node_ids,
        execution_state=execution_state,
        execution_mode=packet.execution_mode,
        isolated_worktree_root=str(isolated_worktree_root),
        copied_paths=copied_paths,
        command_results=tuple(command_results),
        isolated_commit_hash=isolated_commit_hash,
        findings=(
            "created an isolated git repository under the output directory",
            f"copied {len(copied_paths)} approved A28 stage paths into the isolated repository",
            "executed git add and git commit in the isolated repository",
            "project git index and project commit history were not mutated",
            "push, pull request creation, registry mutation, and formal status changes stayed blocked",
        ),
        required_external_actions=(
            "review the isolated commit before any project git staging",
            "require a higher authority gate before mutating the project git index",
            "require a separate higher-risk gate before push or pull request creation",
            "do not infer formal construct status changes from isolated commit success",
        ),
        isolated_git_repository_created=bool(init_result.get("passed")),
        isolated_files_staged=isolated_files_staged,
        isolated_commit_created=isolated_commit_created,
    )


def _unique_isolated_git_worktree_root(repo_base: Path, result_id: str) -> Path:
    candidate = repo_base / result_id
    suffix = 0
    while candidate.exists():
        suffix += 1
        candidate = repo_base / f"{result_id}_{suffix:02d}"
    return candidate


def _copy_stage_paths_to_isolated_repo(
    *,
    stage_paths: tuple[str, ...],
    source_worktree_root: Path,
    isolated_worktree_root: Path,
) -> tuple[str, ...]:
    copied_paths: list[str] = []
    for path_text in stage_paths:
        source_path = (source_worktree_root / Path(path_text)).resolve()
        destination_path = isolated_worktree_root / Path(path_text)
        destination_path.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source_path, destination_path)
        copied_paths.append(path_text)
    return tuple(copied_paths)


def _execute_isolated_git_command(
    argv: tuple[str, ...],
    *,
    cwd: Path,
    output_dir: Path,
    result_id: str,
    command_id: str,
    timeout_seconds: int,
    git_write_operation: bool,
) -> dict[str, Any]:
    output_dir.mkdir(parents=True, exist_ok=True)
    safe_command_id = _safe_artifact_id(command_id)
    file_stem = f"{_short_artifact_stem(result_id, prefix_chars=8)}_{safe_command_id}"
    stdout_path = output_dir / f"{file_stem}_stdout.txt"
    stderr_path = output_dir / f"{file_stem}_stderr.txt"
    started = time.time()
    timeout_expired = False
    try:
        completed = subprocess.run(
            list(argv),
            cwd=cwd,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=max(1, timeout_seconds),
            check=False,
            env={**os.environ, "GIT_TERMINAL_PROMPT": "0"},
        )
        exit_code: int | None = completed.returncode
        stdout = completed.stdout or ""
        stderr = completed.stderr or ""
    except subprocess.TimeoutExpired as exc:
        timeout_expired = True
        exit_code = None
        stdout = _subprocess_output_to_text(exc.stdout)
        stderr = _subprocess_output_to_text(exc.stderr)
    duration_seconds = round(time.time() - started, 3)
    _write_artifact(stdout_path, stdout)
    _write_artifact(stderr_path, stderr)
    return {
        "command_id": safe_command_id,
        "argv": argv,
        "cwd": str(cwd),
        "timeout_seconds": max(1, timeout_seconds),
        "duration_seconds": duration_seconds,
        "exit_code": exit_code,
        "passed": exit_code == 0 and not timeout_expired,
        "timeout_expired": timeout_expired,
        "stdout_path": str(stdout_path),
        "stderr_path": str(stderr_path),
        "stdout_excerpt": stdout[:4000],
        "stderr_excerpt": stderr[:4000],
        "isolated_git_operation": True,
        "git_write_operation": git_write_operation,
        "project_worktree_modified": False,
        "project_index_modified": False,
        "project_commit_created": False,
    }


def _deferred_source_control_staging_commit_preflight_results(
    preflight_results: tuple[SourceControlStagingCommitPreflightResult, ...],
    *,
    consumed_preflight_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in preflight_results:
        if result.result_id in consumed_preflight_result_ids:
            continue
        deferred.append(
            {
                "staging_commit_preflight_result_id": result.result_id,
                "target_focus_node_ids": list(result.target_focus_node_ids),
                "preflight_state": result.preflight_state,
                "deferred_reason": (
                    "no accepted external isolated staging commit execution decision packet"
                ),
                "recommended_next_gate": "isolated_staging_commit_execution",
                "isolated_staging_commit_executed": False,
                "isolated_files_staged": False,
                "isolated_commit_created": False,
                "project_files_staged": False,
                "project_commit_created": False,
                "push_performed": False,
                "pull_request_created": False,
                "source_registry_mutated": False,
                "formal_construct_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_staging_commit_execution_memory(
    *,
    preflight_report: SourceControlStagingCommitPreflightReport,
    decision_packets: tuple[SourceControlStagingCommitExecutionDecisionPacket, ...],
    execution_results: tuple[SourceControlStagingCommitExecutionResult, ...],
    deferred_preflight_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    executed = sum(
        1
        for result in execution_results
        if result.execution_state == "isolated_staging_commit_executed"
    )
    return (
        {
            "memory_id": "a29_isolated_staging_commit_execution_summary",
            "retained_learning": (
                f"{executed} of {len(execution_results)} isolated staging commit "
                "executions created isolated commits after A28 preflight"
            ),
            "recommended_strategy": (
                "permit git add and commit only inside newly created isolated "
                "repositories until a separate project-index authority gate exists"
            ),
            "isolated_git_write_operations_allowed": True,
            "project_git_index_mutation_allowed": False,
            "project_commit_creation_allowed": False,
            "push_allowed": False,
            "formal_status_transition_allowed": False,
        },
        {
            "memory_id": "a29_deferred_staging_commit_preflight_summary",
            "retained_learning": (
                f"{len(deferred_preflight_results)} of "
                f"{len(preflight_report.staging_commit_preflight_results)} "
                "fresh A28 preflight results remain without isolated execution decisions"
            ),
            "decision_packets_seen": len(decision_packets),
            "recommended_strategy": (
                "keep preflight results outside isolated commit execution until "
                "explicit signed A29 execution decisions are available"
            ),
            "isolated_git_write_operations_allowed": False,
            "project_git_index_mutation_allowed": False,
        },
    )


def _source_control_staging_commit_execution_review_packet_markdown(
    execution_results: tuple[SourceControlStagingCommitExecutionResult, ...],
    deferred_preflight_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Staging And Commit Execution Review",
        "",
        "Status: A29 isolated staging and commit execution packet. Runtime executes git writes only inside isolated repositories under the output directory.",
        "",
        "| Result | State | Copied Paths | Isolated Commit | Project Commit |",
        "|---|---|---:|---|---|",
    ]
    for result in execution_results:
        lines.append(
            f"| `{result.result_id}` | `{result.execution_state}` | "
            f"{len(result.copied_paths)} | `{result.isolated_commit_created}` | "
            f"`{result.project_commit_created}` |"
        )
    lines.extend(["", "## Deferred Staging Commit Preflight Results", ""])
    if not deferred_preflight_results:
        lines.append("- none")
    else:
        for item in deferred_preflight_results:
            focus = ", ".join(item["target_focus_node_ids"])
            lines.append(f"- `{focus}`: {item['deferred_reason']}")
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- isolated git repository creation: allowed",
            "- isolated file staging: allowed",
            "- isolated commit creation: allowed",
            "- project git index mutation: blocked",
            "- project commit creation: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- source registry mutation: blocked",
            "- formal construct status changes: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_existing_source_control_staging_commit_execution_results(
    *,
    source_control_staging_commit_execution_result_dirs: Iterable[Path],
    source_control_staging_commit_execution_result_files: Iterable[Path],
) -> tuple[SourceControlStagingCommitExecutionResult, ...]:
    paths: list[Path] = []
    for result_dir in source_control_staging_commit_execution_result_dirs:
        if result_dir.exists():
            paths.extend(sorted(result_dir.rglob("*.json")))
    for result_file in source_control_staging_commit_execution_result_files:
        if result_file.exists():
            paths.append(result_file)

    results: list[SourceControlStagingCommitExecutionResult] = []
    seen_ids: set[str] = set()
    for path in paths:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        candidates: list[dict[str, Any]] = []
        nested = payload.get("staging_commit_execution_results")
        if isinstance(nested, list):
            candidates.extend(item for item in nested if isinstance(item, dict))
        else:
            candidates.append(payload)
        for candidate in candidates:
            result = _source_control_staging_commit_execution_result_from_payload(
                candidate
            )
            if result.result_id in seen_ids:
                continue
            seen_ids.add(result.result_id)
            results.append(result)
    return tuple(results)


def _source_control_staging_commit_execution_result_from_payload(
    payload: dict[str, Any],
) -> SourceControlStagingCommitExecutionResult:
    return SourceControlStagingCommitExecutionResult(
        result_id=str(payload.get("result_id") or "unknown_staging_commit_execution"),
        source_decision_id=str(payload.get("source_decision_id") or "unknown"),
        target_staging_commit_preflight_result_ids=tuple(
            str(item)
            for item in payload.get("target_staging_commit_preflight_result_ids", [])
            if isinstance(item, str)
        ),
        target_focus_node_ids=tuple(
            str(item)
            for item in payload.get("target_focus_node_ids", [])
            if isinstance(item, str)
        ),
        execution_state=str(payload.get("execution_state") or "unknown"),
        execution_mode=str(payload.get("execution_mode") or "unknown"),
        isolated_worktree_root=str(payload.get("isolated_worktree_root") or ""),
        copied_paths=tuple(
            str(item)
            for item in payload.get("copied_paths", [])
            if isinstance(item, str)
        ),
        command_results=tuple(
            item for item in payload.get("command_results", []) if isinstance(item, dict)
        ),
        isolated_commit_hash=(
            str(payload["isolated_commit_hash"])
            if isinstance(payload.get("isolated_commit_hash"), str)
            else None
        ),
        findings=tuple(
            str(item) for item in payload.get("findings", []) if isinstance(item, str)
        ),
        required_external_actions=tuple(
            str(item)
            for item in payload.get("required_external_actions", [])
            if isinstance(item, str)
        ),
        isolated_git_repository_created=bool(
            payload.get("isolated_git_repository_created", False)
        ),
        isolated_files_staged=bool(payload.get("isolated_files_staged", False)),
        isolated_commit_created=bool(payload.get("isolated_commit_created", False)),
        git_operations_executed=bool(
            payload.get("git_operations_executed", payload.get("runtime_git_operations_executed", False))
        ),
        git_write_operations_executed=bool(
            payload.get("git_write_operations_executed", False)
        ),
        project_worktree_modified_by_execution=bool(
            payload.get("project_worktree_modified_by_execution", False)
        ),
        project_index_modified_by_execution=bool(
            payload.get("project_index_modified_by_execution", False)
        ),
        project_files_staged=bool(
            payload.get("project_files_staged", payload.get("runtime_files_staged", False))
        ),
        project_commit_created=bool(
            payload.get("project_commit_created", payload.get("runtime_commit_created", False))
        ),
        push_performed=bool(payload.get("push_performed", payload.get("runtime_push_performed", False))),
        pull_request_created=bool(
            payload.get("pull_request_created", payload.get("runtime_pull_request_created", False))
        ),
        source_registry_mutated=bool(payload.get("source_registry_mutated", False)),
        formal_construct_status_change=str(
            payload.get("formal_construct_status_change") or "none"
        ),
        reference_status_granted=bool(payload.get("reference_status_granted", False)),
        open_ended_experiment_allowed=bool(payload.get("open_ended_experiment_allowed", False)),
    )


def _load_source_control_project_index_staging_decisions(
    *,
    source_control_project_index_staging_decision_dirs: Iterable[Path],
    source_control_project_index_staging_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlProjectIndexStagingDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_project_index_staging_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_project_index_staging_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlProjectIndexStagingDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(_source_control_project_index_staging_decision_from_payload(payload, path))
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_project_index_staging_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlProjectIndexStagingDecisionPacket:
    target_result_ids = payload.get("target_staging_commit_execution_result_ids")
    target_focus_ids = payload.get("target_focus_node_ids")
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    return SourceControlProjectIndexStagingDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_staging_commit_execution_result_ids=(
            tuple(str(item) for item in target_result_ids)
            if isinstance(target_result_ids, list)
            else ()
        ),
        target_focus_node_ids=(
            tuple(str(item) for item in target_focus_ids)
            if isinstance(target_focus_ids, list)
            else ()
        ),
        index_staging_decision=str(payload.get("index_staging_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_index_state=str(payload.get("approved_index_state") or "unknown"),
        execution_mode=str(payload.get("execution_mode") or "unknown"),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=str(payload["signed_by"]) if isinstance(payload.get("signed_by"), str) else None,
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_project_index_staging_block_reason(
    *,
    packet: SourceControlProjectIndexStagingDecisionPacket,
    staging_commit_execution_results: tuple[SourceControlStagingCommitExecutionResult, ...],
) -> str | None:
    allowed_decisions = {
        "accept_project_index_staging_with_rollback",
        "defer_project_index_staging_with_rollback",
        "reject_project_index_staging_with_rollback",
    }
    if packet.index_staging_decision not in allowed_decisions:
        return f"index_staging_decision {packet.index_staging_decision!r} is not allowed"
    if packet.review_gate != "project_index_staging_with_rollback":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'project_index_staging_with_rollback'"
        )
    allowed_states = {
        "project_index_staging_rollback_ready",
        "deferred_by_project_index_staging_review",
        "rejected_by_project_index_staging_review",
    }
    if packet.approved_index_state not in allowed_states:
        return f"approved_index_state {packet.approved_index_state!r} is not allowed"
    if not packet.target_staging_commit_execution_result_ids:
        return "project-index staging decision has no target A29 execution results"
    found_result_ids = {result.result_id for result in staging_commit_execution_results}
    missing_result_ids = [
        result_id
        for result_id in packet.target_staging_commit_execution_result_ids
        if result_id not in found_result_ids
    ]
    if missing_result_ids:
        return (
            "target A29 staging commit execution results were not found: "
            + ", ".join(missing_result_ids)
        )
    focus_ids = set().union(
        *(set(result.target_focus_node_ids) for result in staging_commit_execution_results)
    )
    if set(packet.target_focus_node_ids) != focus_ids:
        return "target_focus_node_ids do not match target A29 execution focus ids"
    if not packet.signed_by:
        return "project-index staging decision is missing signed_by"
    if not packet.signature_token:
        return "project-index staging decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_project_branch_creation",
        "allow_project_commit_creation",
        "allow_project_worktree_mutation",
        "allow_runtime_branch_creation",
        "allow_runtime_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"project-index staging decision attempted to allow {key}"

    if packet.index_staging_decision != "accept_project_index_staging_with_rollback":
        return None
    if packet.approved_index_state != "project_index_staging_rollback_ready":
        return (
            "accepted project-index staging decision must approve "
            "project_index_staging_rollback_ready"
        )
    if packet.execution_mode != "project_git_index_transient_staging":
        return (
            "accepted project-index staging decision must use "
            "project_git_index_transient_staging"
        )
    required_true_constraints = (
        "allow_project_git_index_mutation",
        "allow_project_file_staging_temporarily",
        "allow_project_git_add",
        "require_clean_project_index_before_start",
        "require_project_git_restore_staged",
        "require_rollback_verification",
    )
    for key in required_true_constraints:
        if not bool(packet.constraints.get(key, False)):
            return f"accepted project-index staging decision must allow {key}"

    for result in staging_commit_execution_results:
        if result.execution_state != "isolated_staging_commit_executed":
            return f"A29 execution result {result.result_id!r} is not executed"
        if result.execution_mode != "isolated_git_worktree":
            return f"A29 execution result {result.result_id!r} did not use isolated_git_worktree"
        if not result.isolated_git_repository_created:
            return f"A29 execution result {result.result_id!r} lacks isolated repository"
        if not result.isolated_files_staged:
            return f"A29 execution result {result.result_id!r} lacks isolated staging"
        if not result.isolated_commit_created or not result.isolated_commit_hash:
            return f"A29 execution result {result.result_id!r} lacks isolated commit"
        if not result.copied_paths:
            return f"A29 execution result {result.result_id!r} has no copied paths"
        if result.project_index_modified_by_execution or result.project_files_staged:
            return f"A29 execution result {result.result_id!r} reports project index mutation"
        if result.project_commit_created or result.push_performed or result.pull_request_created:
            return f"A29 execution result {result.result_id!r} reports project git publication"
        if result.source_registry_mutated:
            return f"A29 execution result {result.result_id!r} reports registry mutation"
        if result.formal_construct_status_change != "none":
            return f"A29 execution result {result.result_id!r} reports status change"
        if result.reference_status_granted:
            return f"A29 execution result {result.result_id!r} reports reference status"
        if result.open_ended_experiment_allowed:
            return f"A29 execution result {result.result_id!r} reports open experiment"
        if not all(bool(item.get("passed")) for item in result.command_results):
            return f"A29 execution result {result.result_id!r} has command failures"
    return None


def _source_control_project_index_staging_from_execution_results(
    *,
    packet: SourceControlProjectIndexStagingDecisionPacket,
    staging_commit_execution_results: tuple[SourceControlStagingCommitExecutionResult, ...],
    project_worktree_root: Path,
    staging_dir: Path,
    timeout_seconds: int,
) -> SourceControlProjectIndexStagingResult:
    result_id = _safe_artifact_id(f"{packet.decision_id}_project_index_staging")
    stage_paths = tuple(
        dict.fromkeys(
            path
            for result in staging_commit_execution_results
            for path in result.copied_paths
            if isinstance(path, str)
        )
    )
    command_output_dir = staging_dir / "cmd"
    command_timeout = max(1, timeout_seconds)
    current_path_checks = tuple(
        _stage_path_boundary_check(path_text, project_worktree_root) for path_text in stage_paths
    )
    if not all(bool(item.get("passed")) for item in current_path_checks):
        failed = tuple(str(item.get("reason")) for item in current_path_checks if not item.get("passed"))
        return SourceControlProjectIndexStagingResult(
            result_id=result_id,
            source_decision_id=packet.decision_id,
            target_staging_commit_execution_result_ids=tuple(
                result.result_id for result in staging_commit_execution_results
            ),
            target_focus_node_ids=packet.target_focus_node_ids,
            index_staging_state="project_index_staging_failed",
            execution_mode=packet.execution_mode,
            stage_paths=stage_paths,
            command_results=(),
            pre_existing_staged_paths=(),
            staged_paths_after_add=(),
            staged_paths_after_rollback=(),
            findings=(
                "current stage path boundary recheck failed before project-index staging",
                *failed,
            ),
            required_external_actions=(
                "refresh A28 and A29 staging evidence before project-index staging",
                "do not create a project commit",
            ),
            project_index_modified_by_execution=False,
        )

    pre_index_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "diff", "--cached", "--name-only"),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_pre_staging_index_snapshot",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results: list[dict[str, Any]] = [pre_index_result]
    pre_existing_staged_paths = _git_name_only_paths_from_command(pre_index_result)
    if not pre_index_result.get("passed") or pre_existing_staged_paths:
        return SourceControlProjectIndexStagingResult(
            result_id=result_id,
            source_decision_id=packet.decision_id,
            target_staging_commit_execution_result_ids=tuple(
                result.result_id for result in staging_commit_execution_results
            ),
            target_focus_node_ids=packet.target_focus_node_ids,
            index_staging_state="project_index_staging_blocked_dirty_index",
            execution_mode=packet.execution_mode,
            stage_paths=stage_paths,
            command_results=tuple(command_results),
            pre_existing_staged_paths=pre_existing_staged_paths,
            staged_paths_after_add=(),
            staged_paths_after_rollback=pre_existing_staged_paths,
            findings=(
                "project index was not clean before staging",
                "project git add was not executed",
            ),
            required_external_actions=(
                "clear or review pre-existing staged paths before project-index staging",
                "rerun the A30 gate after the project index is clean",
            ),
            project_index_modified_by_execution=False,
        )

    add_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "add", "--", *stage_paths),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_add_project_approved_stage_paths",
        timeout_seconds=command_timeout,
        git_write_operation=True,
        modifies_project_index=True,
    )
    command_results.append(add_result)

    staged_snapshot_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "diff", "--cached", "--name-only"),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_post_add_index_snapshot",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results.append(staged_snapshot_result)
    staged_paths_after_add = _git_name_only_paths_from_command(staged_snapshot_result)

    if _project_git_head_exists(project_worktree_root, timeout_seconds=command_timeout):
        rollback_argv = (
            "git",
            "-c",
            "core.longpaths=true",
            "restore",
            "--staged",
            "--",
            *stage_paths,
        )
        rollback_command_id = "git_restore_staged_project_paths"
    else:
        rollback_argv = (
            "git",
            "-c",
            "core.longpaths=true",
            "rm",
            "--cached",
            "-q",
            "--",
            *stage_paths,
        )
        rollback_command_id = "git_rm_cached_unborn_index_paths"
    restore_result = _execute_project_git_command(
        rollback_argv,
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id=rollback_command_id,
        timeout_seconds=command_timeout,
        git_write_operation=True,
        modifies_project_index=True,
    )
    command_results.append(restore_result)

    post_rollback_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "diff", "--cached", "--name-only"),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_post_rollback_index_snapshot",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results.append(post_rollback_result)
    staged_paths_after_rollback = _git_name_only_paths_from_command(post_rollback_result)

    project_git_add_executed = bool(add_result.get("passed"))
    project_git_restore_staged_executed = bool(restore_result.get("passed"))
    project_index_transiently_modified = project_git_add_executed and bool(staged_paths_after_add)
    rollback_verified = (
        project_git_restore_staged_executed
        and bool(post_rollback_result.get("passed"))
        and not staged_paths_after_rollback
    )
    index_staging_state = (
        "project_index_staging_rollback_verified"
        if project_index_transiently_modified and rollback_verified
        else "project_index_staging_failed"
    )
    return SourceControlProjectIndexStagingResult(
        result_id=result_id,
        source_decision_id=packet.decision_id,
        target_staging_commit_execution_result_ids=tuple(
            result.result_id for result in staging_commit_execution_results
        ),
        target_focus_node_ids=packet.target_focus_node_ids,
        index_staging_state=index_staging_state,
        execution_mode=packet.execution_mode,
        stage_paths=stage_paths,
        command_results=tuple(command_results),
        pre_existing_staged_paths=pre_existing_staged_paths,
        staged_paths_after_add=staged_paths_after_add,
        staged_paths_after_rollback=staged_paths_after_rollback,
        findings=(
            "verified clean project index before staging",
            f"executed project git add for {len(stage_paths)} A29-proven paths",
            f"observed {len(staged_paths_after_add)} staged paths after project git add",
            "executed project index rollback for approved paths",
            "verified final project index is clean after rollback",
            "project commit, push, pull request, registry mutation, and formal status changes stayed blocked",
        ),
        required_external_actions=(
            "review A30 rollback evidence before considering persistent project staging",
            "require a separate gate before leaving files staged in the project index",
            "require a separate higher-risk gate before project commit creation",
            "do not infer formal construct status changes from project-index staging success",
        ),
        project_git_add_executed=project_git_add_executed,
        project_git_restore_staged_executed=project_git_restore_staged_executed,
        project_index_transiently_modified=project_index_transiently_modified,
        project_index_rollback_verified=rollback_verified,
        project_index_modified_by_execution=project_git_add_executed
        or project_git_restore_staged_executed,
        project_files_staged=bool(staged_paths_after_rollback),
    )


def _execute_project_git_command(
    argv: tuple[str, ...],
    *,
    cwd: Path,
    output_dir: Path,
    result_id: str,
    command_id: str,
    timeout_seconds: int,
    git_write_operation: bool,
    modifies_project_index: bool,
    env_overrides: dict[str, str] | None = None,
) -> dict[str, Any]:
    output_dir.mkdir(parents=True, exist_ok=True)
    safe_command_id = _safe_artifact_id(command_id)
    file_stem = f"{_short_artifact_stem(result_id, prefix_chars=8)}_{safe_command_id}"
    stdout_path = output_dir / f"{file_stem}_stdout.txt"
    stderr_path = output_dir / f"{file_stem}_stderr.txt"
    started = time.time()
    timeout_expired = False
    try:
        completed = subprocess.run(
            list(argv),
            cwd=cwd,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=max(1, timeout_seconds),
            check=False,
            env={**os.environ, "GIT_TERMINAL_PROMPT": "0", **(env_overrides or {})},
        )
        exit_code: int | None = completed.returncode
        stdout = completed.stdout or ""
        stderr = completed.stderr or ""
    except subprocess.TimeoutExpired as exc:
        timeout_expired = True
        exit_code = None
        stdout = _subprocess_output_to_text(exc.stdout)
        stderr = _subprocess_output_to_text(exc.stderr)
    duration_seconds = round(time.time() - started, 3)
    _write_artifact(stdout_path, stdout)
    _write_artifact(stderr_path, stderr)
    return {
        "command_id": safe_command_id,
        "argv": argv,
        "cwd": str(cwd),
        "timeout_seconds": max(1, timeout_seconds),
        "duration_seconds": duration_seconds,
        "exit_code": exit_code,
        "passed": exit_code == 0 and not timeout_expired,
        "timeout_expired": timeout_expired,
        "stdout_path": str(stdout_path),
        "stderr_path": str(stderr_path),
        "stdout_excerpt": stdout[:4000],
        "stderr_excerpt": stderr[:4000],
        "isolated_git_operation": False,
        "project_git_operation": True,
        "git_write_operation": git_write_operation,
        "project_worktree_modified": False,
        "project_index_modified": modifies_project_index,
        "project_commit_created": False,
    }


def _project_git_head_exists(cwd: Path, *, timeout_seconds: int) -> bool:
    try:
        completed = subprocess.run(
            ["git", "rev-parse", "--verify", "HEAD"],
            cwd=cwd,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=max(1, timeout_seconds),
            check=False,
            env={**os.environ, "GIT_TERMINAL_PROMPT": "0"},
        )
    except subprocess.TimeoutExpired:
        return False
    return completed.returncode == 0


def _git_name_only_paths_from_command(command_result: dict[str, Any]) -> tuple[str, ...]:
    stdout_path = Path(str(command_result.get("stdout_path") or ""))
    if stdout_path.exists():
        try:
            stdout = stdout_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            stdout = ""
    else:
        stdout = str(command_result.get("stdout_excerpt") or "")
    return tuple(
        line.strip().replace("\\", "/")
        for line in stdout.splitlines()
        if line.strip()
    )


def _deferred_source_control_staging_commit_execution_results(
    execution_results: tuple[SourceControlStagingCommitExecutionResult, ...],
    *,
    consumed_execution_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in execution_results:
        if result.result_id in consumed_execution_result_ids:
            continue
        deferred.append(
            {
                "staging_commit_execution_result_id": result.result_id,
                "target_focus_node_ids": list(result.target_focus_node_ids),
                "execution_state": result.execution_state,
                "deferred_reason": (
                    "no accepted external project-index staging decision packet"
                ),
                "recommended_next_gate": "project_index_staging_with_rollback",
                "project_index_staging_executed": False,
                "project_git_add_executed": False,
                "project_index_rollback_verified": False,
                "project_commit_created": False,
                "push_performed": False,
                "pull_request_created": False,
                "source_registry_mutated": False,
                "formal_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_project_index_staging_memory(
    *,
    execution_report: SourceControlStagingCommitExecutionReport,
    decision_packets: tuple[SourceControlProjectIndexStagingDecisionPacket, ...],
    index_staging_results: tuple[SourceControlProjectIndexStagingResult, ...],
    deferred_execution_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    verified = sum(
        1
        for result in index_staging_results
        if result.index_staging_state == "project_index_staging_rollback_verified"
    )
    return (
        {
            "memory_id": "a30_project_index_staging_rollback_summary",
            "retained_learning": (
                f"{verified} of {len(index_staging_results)} project-index staging "
                "executions performed git add and verified rollback"
            ),
            "recommended_strategy": (
                "permit project git add only when the index starts clean and "
                "restore --staged rollback is verified before returning control"
            ),
            "project_git_index_mutation_allowed": True,
            "project_git_index_persistent_staging_allowed": False,
            "project_commit_creation_allowed": False,
            "push_allowed": False,
            "formal_status_transition_allowed": False,
        },
        {
            "memory_id": "a30_deferred_isolated_execution_summary",
            "retained_learning": (
                f"{len(deferred_execution_results)} of "
                f"{len(execution_report.staging_commit_execution_results)} "
                "fresh A29 isolated execution results remain without A30 decisions"
            ),
            "decision_packets_seen": len(decision_packets),
            "recommended_strategy": (
                "keep A29 execution results outside project-index staging until "
                "explicit signed A30 project-index decisions are available"
            ),
            "project_git_index_mutation_allowed": False,
            "project_commit_creation_allowed": False,
        },
    )


def _source_control_project_index_staging_review_packet_markdown(
    index_staging_results: tuple[SourceControlProjectIndexStagingResult, ...],
    deferred_execution_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Project Index Staging Review",
        "",
        "Status: A30 project-index staging packet. Runtime executes project git add only with mandatory restore-staged rollback verification.",
        "",
        "| Result | State | Paths | Add | Restore | Rollback | Commit |",
        "|---|---|---:|---|---|---|---|",
    ]
    for result in index_staging_results:
        lines.append(
            f"| `{result.result_id}` | `{result.index_staging_state}` | "
            f"{len(result.stage_paths)} | `{result.project_git_add_executed}` | "
            f"`{result.project_git_restore_staged_executed}` | "
            f"`{result.project_index_rollback_verified}` | "
            f"`{result.project_commit_created}` |"
        )
    lines.extend(["", "## Deferred Staging Commit Execution Results", ""])
    if not deferred_execution_results:
        lines.append("- none")
    else:
        for item in deferred_execution_results:
            focus = ", ".join(item["target_focus_node_ids"])
            lines.append(f"- `{focus}`: {item['deferred_reason']}")
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- project git add: allowed only after clean-index verification",
            "- project restore --staged: required",
            "- persistent project staging: blocked",
            "- project commit creation: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- source registry mutation: blocked",
            "- formal construct status changes: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_existing_source_control_project_index_staging_results(
    *,
    source_control_project_index_staging_result_dirs: Iterable[Path],
    source_control_project_index_staging_result_files: Iterable[Path],
) -> tuple[SourceControlProjectIndexStagingResult, ...]:
    paths: list[Path] = []
    for result_dir in source_control_project_index_staging_result_dirs:
        if result_dir.exists():
            paths.extend(sorted(result_dir.rglob("*.json")))
    for result_file in source_control_project_index_staging_result_files:
        if result_file.exists():
            paths.append(result_file)

    results: list[SourceControlProjectIndexStagingResult] = []
    seen_ids: set[str] = set()
    for path in paths:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        candidates: list[dict[str, Any]] = []
        nested = payload.get("project_index_staging_results")
        if isinstance(nested, list):
            candidates.extend(item for item in nested if isinstance(item, dict))
        else:
            candidates.append(payload)
        for candidate in candidates:
            result = _source_control_project_index_staging_result_from_payload(candidate)
            if result.result_id in seen_ids:
                continue
            seen_ids.add(result.result_id)
            results.append(result)
    return tuple(results)


def _source_control_project_index_staging_result_from_payload(
    payload: dict[str, Any],
) -> SourceControlProjectIndexStagingResult:
    return SourceControlProjectIndexStagingResult(
        result_id=str(payload.get("result_id") or "unknown_project_index_staging"),
        source_decision_id=str(payload.get("source_decision_id") or "unknown"),
        target_staging_commit_execution_result_ids=tuple(
            str(item)
            for item in payload.get("target_staging_commit_execution_result_ids", [])
            if isinstance(item, str)
        ),
        target_focus_node_ids=tuple(
            str(item)
            for item in payload.get("target_focus_node_ids", [])
            if isinstance(item, str)
        ),
        index_staging_state=str(payload.get("index_staging_state") or "unknown"),
        execution_mode=str(payload.get("execution_mode") or "unknown"),
        stage_paths=tuple(
            str(item) for item in payload.get("stage_paths", []) if isinstance(item, str)
        ),
        command_results=tuple(
            item for item in payload.get("command_results", []) if isinstance(item, dict)
        ),
        pre_existing_staged_paths=tuple(
            str(item)
            for item in payload.get("pre_existing_staged_paths", [])
            if isinstance(item, str)
        ),
        staged_paths_after_add=tuple(
            str(item)
            for item in payload.get("staged_paths_after_add", [])
            if isinstance(item, str)
        ),
        staged_paths_after_rollback=tuple(
            str(item)
            for item in payload.get("staged_paths_after_rollback", [])
            if isinstance(item, str)
        ),
        findings=tuple(
            str(item) for item in payload.get("findings", []) if isinstance(item, str)
        ),
        required_external_actions=tuple(
            str(item)
            for item in payload.get("required_external_actions", [])
            if isinstance(item, str)
        ),
        project_git_add_executed=bool(payload.get("project_git_add_executed", False)),
        project_git_restore_staged_executed=bool(
            payload.get("project_git_restore_staged_executed", False)
        ),
        project_index_transiently_modified=bool(
            payload.get("project_index_transiently_modified", False)
        ),
        project_index_rollback_verified=bool(
            payload.get("project_index_rollback_verified", False)
        ),
        project_index_modified_by_execution=bool(
            payload.get("project_index_modified_by_execution", False)
        ),
        project_files_staged=bool(
            payload.get("project_files_staged", payload.get("runtime_files_staged", False))
        ),
        project_commit_created=bool(
            payload.get("project_commit_created", payload.get("runtime_commit_created", False))
        ),
        push_performed=bool(payload.get("push_performed", payload.get("runtime_push_performed", False))),
        pull_request_created=bool(
            payload.get("pull_request_created", payload.get("runtime_pull_request_created", False))
        ),
        source_registry_mutated=bool(payload.get("source_registry_mutated", False)),
        formal_construct_status_change=str(
            payload.get("formal_construct_status_change") or "none"
        ),
        reference_status_granted=bool(payload.get("reference_status_granted", False)),
        open_ended_experiment_allowed=bool(payload.get("open_ended_experiment_allowed", False)),
    )


def _load_source_control_commit_object_decisions(
    *,
    source_control_commit_object_decision_dirs: Iterable[Path],
    source_control_commit_object_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlCommitObjectDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_commit_object_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_commit_object_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlCommitObjectDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(_source_control_commit_object_decision_from_payload(payload, path))
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_commit_object_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlCommitObjectDecisionPacket:
    target_result_ids = payload.get("target_project_index_staging_result_ids")
    target_focus_ids = payload.get("target_focus_node_ids")
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    commit_author = payload.get("commit_author")
    return SourceControlCommitObjectDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_project_index_staging_result_ids=(
            tuple(str(item) for item in target_result_ids)
            if isinstance(target_result_ids, list)
            else ()
        ),
        target_focus_node_ids=(
            tuple(str(item) for item in target_focus_ids)
            if isinstance(target_focus_ids, list)
            else ()
        ),
        commit_object_decision=str(payload.get("commit_object_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_commit_object_state=str(
            payload.get("approved_commit_object_state") or "unknown"
        ),
        execution_mode=str(payload.get("execution_mode") or "unknown"),
        commit_author=commit_author if isinstance(commit_author, dict) else {},
        commit_message=str(payload.get("commit_message") or "").strip(),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=str(payload["signed_by"]) if isinstance(payload.get("signed_by"), str) else None,
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_commit_object_block_reason(
    *,
    packet: SourceControlCommitObjectDecisionPacket,
    project_index_staging_results: tuple[SourceControlProjectIndexStagingResult, ...],
) -> str | None:
    allowed_decisions = {
        "accept_project_commit_object_with_index_rollback",
        "defer_project_commit_object_with_index_rollback",
        "reject_project_commit_object_with_index_rollback",
    }
    if packet.commit_object_decision not in allowed_decisions:
        return f"commit_object_decision {packet.commit_object_decision!r} is not allowed"
    if packet.review_gate != "project_commit_object_with_index_rollback":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'project_commit_object_with_index_rollback'"
        )
    allowed_states = {
        "project_commit_object_rollback_ready",
        "deferred_by_project_commit_object_review",
        "rejected_by_project_commit_object_review",
    }
    if packet.approved_commit_object_state not in allowed_states:
        return (
            f"approved_commit_object_state {packet.approved_commit_object_state!r} "
            "is not allowed"
        )
    if not packet.target_project_index_staging_result_ids:
        return "commit-object decision has no target A30 project-index staging results"
    found_result_ids = {result.result_id for result in project_index_staging_results}
    missing_result_ids = [
        result_id
        for result_id in packet.target_project_index_staging_result_ids
        if result_id not in found_result_ids
    ]
    if missing_result_ids:
        return (
            "target A30 project-index staging results were not found: "
            + ", ".join(missing_result_ids)
        )
    focus_ids = set().union(
        *(set(result.target_focus_node_ids) for result in project_index_staging_results)
    )
    if set(packet.target_focus_node_ids) != focus_ids:
        return "target_focus_node_ids do not match target A30 staging focus ids"
    if not packet.signed_by:
        return "commit-object decision is missing signed_by"
    if not packet.signature_token:
        return "commit-object decision is missing signature_token"

    forbidden_true_constraints = (
        "allow_project_ref_update",
        "allow_project_branch_creation",
        "allow_project_commit_creation",
        "allow_runtime_branch_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"commit-object decision attempted to allow {key}"

    if packet.commit_object_decision != "accept_project_commit_object_with_index_rollback":
        return None
    if packet.approved_commit_object_state != "project_commit_object_rollback_ready":
        return (
            "accepted commit-object decision must approve "
            "project_commit_object_rollback_ready"
        )
    if packet.execution_mode != "project_git_commit_object_with_index_rollback":
        return (
            "accepted commit-object decision must use "
            "project_git_commit_object_with_index_rollback"
        )
    required_true_constraints = (
        "allow_project_git_index_mutation",
        "allow_project_file_staging_temporarily",
        "allow_project_git_add",
        "allow_project_git_write_tree",
        "allow_project_git_commit_tree",
        "require_clean_project_index_before_start",
        "require_project_index_rollback",
        "require_commit_object_verification",
        "forbid_ref_update",
    )
    for key in required_true_constraints:
        if not bool(packet.constraints.get(key, False)):
            return f"accepted commit-object decision must allow {key}"
    author_name = str(packet.commit_author.get("name") or "").strip()
    author_email = str(packet.commit_author.get("email") or "").strip()
    if not author_name:
        return "accepted commit-object decision requires commit_author.name"
    if "@" not in author_email:
        return "accepted commit-object decision requires commit_author.email"
    if not packet.commit_message:
        return "accepted commit-object decision requires commit_message"

    for result in project_index_staging_results:
        if result.index_staging_state != "project_index_staging_rollback_verified":
            return f"A30 result {result.result_id!r} is not rollback verified"
        if result.execution_mode != "project_git_index_transient_staging":
            return f"A30 result {result.result_id!r} did not use project index staging"
        if not result.project_git_add_executed:
            return f"A30 result {result.result_id!r} did not execute project git add"
        if not result.project_git_restore_staged_executed:
            return f"A30 result {result.result_id!r} did not execute index rollback"
        if not result.project_index_rollback_verified:
            return f"A30 result {result.result_id!r} did not verify rollback"
        if not result.stage_paths:
            return f"A30 result {result.result_id!r} has no stage paths"
        if result.project_files_staged:
            return f"A30 result {result.result_id!r} left project files staged"
        if result.project_commit_created or result.push_performed or result.pull_request_created:
            return f"A30 result {result.result_id!r} reports project git publication"
        if result.source_registry_mutated:
            return f"A30 result {result.result_id!r} reports registry mutation"
        if result.formal_construct_status_change != "none":
            return f"A30 result {result.result_id!r} reports status change"
        if result.reference_status_granted:
            return f"A30 result {result.result_id!r} reports reference status"
        if result.open_ended_experiment_allowed:
            return f"A30 result {result.result_id!r} reports open experiment"
        if not all(bool(item.get("passed")) for item in result.command_results):
            return f"A30 result {result.result_id!r} has command failures"
    return None


def _source_control_commit_object_from_index_staging_results(
    *,
    packet: SourceControlCommitObjectDecisionPacket,
    project_index_staging_results: tuple[SourceControlProjectIndexStagingResult, ...],
    project_worktree_root: Path,
    commit_dir: Path,
    timeout_seconds: int,
) -> SourceControlCommitObjectResult:
    result_id = _safe_artifact_id(f"{packet.decision_id}_commit_object")
    stage_paths = tuple(
        dict.fromkeys(
            path
            for result in project_index_staging_results
            for path in result.stage_paths
            if isinstance(path, str)
        )
    )
    command_output_dir = commit_dir / "cmd"
    command_timeout = max(1, timeout_seconds)
    current_path_checks = tuple(
        _stage_path_boundary_check(path_text, project_worktree_root) for path_text in stage_paths
    )
    if not all(bool(item.get("passed")) for item in current_path_checks):
        failed = tuple(str(item.get("reason")) for item in current_path_checks if not item.get("passed"))
        return SourceControlCommitObjectResult(
            result_id=result_id,
            source_decision_id=packet.decision_id,
            target_project_index_staging_result_ids=tuple(
                result.result_id for result in project_index_staging_results
            ),
            target_focus_node_ids=packet.target_focus_node_ids,
            commit_object_state="project_commit_object_failed",
            execution_mode=packet.execution_mode,
            stage_paths=stage_paths,
            command_results=(),
            pre_existing_staged_paths=(),
            staged_paths_after_add=(),
            staged_paths_after_rollback=(),
            tree_hash=None,
            commit_object_hash=None,
            findings=(
                "current stage path boundary recheck failed before commit-object execution",
                *failed,
            ),
            required_external_actions=(
                "refresh A28 through A30 staging evidence before commit-object execution",
                "do not update project refs",
            ),
            project_index_modified_by_execution=False,
        )

    pre_index_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "diff", "--cached", "--name-only"),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_pre_commit_object_index_snapshot",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results: list[dict[str, Any]] = [pre_index_result]
    pre_existing_staged_paths = _git_name_only_paths_from_command(pre_index_result)
    if not pre_index_result.get("passed") or pre_existing_staged_paths:
        return SourceControlCommitObjectResult(
            result_id=result_id,
            source_decision_id=packet.decision_id,
            target_project_index_staging_result_ids=tuple(
                result.result_id for result in project_index_staging_results
            ),
            target_focus_node_ids=packet.target_focus_node_ids,
            commit_object_state="project_commit_object_blocked_dirty_index",
            execution_mode=packet.execution_mode,
            stage_paths=stage_paths,
            command_results=tuple(command_results),
            pre_existing_staged_paths=pre_existing_staged_paths,
            staged_paths_after_add=(),
            staged_paths_after_rollback=pre_existing_staged_paths,
            tree_hash=None,
            commit_object_hash=None,
            findings=(
                "project index was not clean before commit-object execution",
                "project git add and commit-tree were not executed",
            ),
            required_external_actions=(
                "clear or review pre-existing staged paths before commit-object execution",
                "rerun the A31 gate after the project index is clean",
            ),
            project_index_modified_by_execution=False,
        )

    add_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "add", "--", *stage_paths),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_add_project_paths_for_commit_object",
        timeout_seconds=command_timeout,
        git_write_operation=True,
        modifies_project_index=True,
    )
    command_results.append(add_result)

    staged_snapshot_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "diff", "--cached", "--name-only"),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_commit_object_post_add_index_snapshot",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results.append(staged_snapshot_result)
    staged_paths_after_add = _git_name_only_paths_from_command(staged_snapshot_result)

    write_tree_result: dict[str, Any] | None = None
    commit_tree_result: dict[str, Any] | None = None
    verify_object_result: dict[str, Any] | None = None
    tree_hash: str | None = None
    commit_object_hash: str | None = None
    if add_result.get("passed") and staged_paths_after_add:
        write_tree_result = _execute_project_git_command(
            ("git", "-c", "core.longpaths=true", "write-tree"),
            cwd=project_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_write_tree_for_commit_object",
            timeout_seconds=command_timeout,
            git_write_operation=True,
            modifies_project_index=False,
        )
        command_results.append(write_tree_result)
        tree_hash = _first_stdout_line_from_command(write_tree_result)

    if write_tree_result is not None and write_tree_result.get("passed") and tree_hash:
        commit_tree_argv = ["git", "-c", "core.longpaths=true", "commit-tree", tree_hash]
        if _project_git_head_exists(project_worktree_root, timeout_seconds=command_timeout):
            commit_tree_argv.extend(["-p", "HEAD"])
        commit_tree_argv.extend(["-m", packet.commit_message])
        author_name = str(packet.commit_author.get("name") or "").strip()
        author_email = str(packet.commit_author.get("email") or "").strip()
        commit_tree_result = _execute_project_git_command(
            tuple(commit_tree_argv),
            cwd=project_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_commit_tree_project_object",
            timeout_seconds=command_timeout,
            git_write_operation=True,
            modifies_project_index=False,
            env_overrides={
                "GIT_AUTHOR_NAME": author_name,
                "GIT_AUTHOR_EMAIL": author_email,
                "GIT_COMMITTER_NAME": author_name,
                "GIT_COMMITTER_EMAIL": author_email,
            },
        )
        command_results.append(commit_tree_result)
        commit_object_hash = _first_stdout_line_from_command(commit_tree_result)

    if commit_tree_result is not None and commit_tree_result.get("passed") and commit_object_hash:
        verify_object_result = _execute_project_git_command(
            ("git", "-c", "core.longpaths=true", "cat-file", "-t", commit_object_hash),
            cwd=project_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_verify_project_commit_object",
            timeout_seconds=command_timeout,
            git_write_operation=False,
            modifies_project_index=False,
        )
        command_results.append(verify_object_result)

    if _project_git_head_exists(project_worktree_root, timeout_seconds=command_timeout):
        rollback_argv = (
            "git",
            "-c",
            "core.longpaths=true",
            "restore",
            "--staged",
            "--",
            *stage_paths,
        )
        rollback_command_id = "git_restore_staged_after_commit_object"
    else:
        rollback_argv = (
            "git",
            "-c",
            "core.longpaths=true",
            "rm",
            "--cached",
            "-q",
            "--",
            *stage_paths,
        )
        rollback_command_id = "git_rm_cached_after_commit_object"
    restore_result = _execute_project_git_command(
        rollback_argv,
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id=rollback_command_id,
        timeout_seconds=command_timeout,
        git_write_operation=True,
        modifies_project_index=True,
    )
    command_results.append(restore_result)

    post_rollback_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "diff", "--cached", "--name-only"),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_commit_object_post_rollback_index_snapshot",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results.append(post_rollback_result)
    staged_paths_after_rollback = _git_name_only_paths_from_command(post_rollback_result)

    object_type = (
        _first_stdout_line_from_command(verify_object_result)
        if verify_object_result is not None
        else None
    )
    project_git_add_executed = bool(add_result.get("passed"))
    write_tree_executed = write_tree_result is not None and bool(write_tree_result.get("passed"))
    commit_tree_executed = commit_tree_result is not None and bool(commit_tree_result.get("passed"))
    commit_object_verified = (
        verify_object_result is not None
        and bool(verify_object_result.get("passed"))
        and object_type == "commit"
    )
    restore_executed = bool(restore_result.get("passed"))
    index_transiently_modified = project_git_add_executed and bool(staged_paths_after_add)
    rollback_verified = (
        restore_executed
        and bool(post_rollback_result.get("passed"))
        and not staged_paths_after_rollback
    )
    commit_object_state = (
        "commit_object_created_rollback_verified"
        if (
            index_transiently_modified
            and write_tree_executed
            and commit_tree_executed
            and commit_object_hash
            and commit_object_verified
            and rollback_verified
        )
        else "project_commit_object_failed"
    )
    return SourceControlCommitObjectResult(
        result_id=result_id,
        source_decision_id=packet.decision_id,
        target_project_index_staging_result_ids=tuple(
            result.result_id for result in project_index_staging_results
        ),
        target_focus_node_ids=packet.target_focus_node_ids,
        commit_object_state=commit_object_state,
        execution_mode=packet.execution_mode,
        stage_paths=stage_paths,
        command_results=tuple(command_results),
        pre_existing_staged_paths=pre_existing_staged_paths,
        staged_paths_after_add=staged_paths_after_add,
        staged_paths_after_rollback=staged_paths_after_rollback,
        tree_hash=tree_hash,
        commit_object_hash=commit_object_hash,
        findings=(
            "verified clean project index before commit-object execution",
            f"executed project git add for {len(stage_paths)} A30-proven paths",
            "executed git write-tree against the staged project index",
            "executed git commit-tree to create a commit object without updating refs",
            "verified the new object is a commit object",
            "rolled back the project index and verified final staged paths are empty",
            "branch refs, project commit history, push, pull request, registry mutation, and formal status changes stayed blocked",
        ),
        required_external_actions=(
            "review the commit object before any ref update or branch commit",
            "require a separate gate before updating branch refs",
            "require a separate higher-risk gate before push or pull request creation",
            "do not infer formal construct status changes from commit-object success",
        ),
        project_git_add_executed=project_git_add_executed,
        project_git_write_tree_executed=write_tree_executed,
        project_git_commit_tree_executed=commit_tree_executed,
        project_commit_object_created=bool(commit_object_hash),
        project_commit_object_verified=commit_object_verified,
        project_git_restore_staged_executed=restore_executed,
        project_index_transiently_modified=index_transiently_modified,
        project_index_rollback_verified=rollback_verified,
        project_index_modified_by_execution=project_git_add_executed or restore_executed,
        project_files_staged=bool(staged_paths_after_rollback),
    )


def _first_stdout_line_from_command(command_result: dict[str, Any] | None) -> str | None:
    if command_result is None:
        return None
    stdout_path = Path(str(command_result.get("stdout_path") or ""))
    if stdout_path.exists():
        try:
            stdout = stdout_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            stdout = ""
    else:
        stdout = str(command_result.get("stdout_excerpt") or "")
    for line in stdout.splitlines():
        text = line.strip()
        if text:
            return text
    return None


def _deferred_source_control_project_index_staging_results(
    index_staging_results: tuple[SourceControlProjectIndexStagingResult, ...],
    *,
    consumed_index_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in index_staging_results:
        if result.result_id in consumed_index_result_ids:
            continue
        deferred.append(
            {
                "project_index_staging_result_id": result.result_id,
                "target_focus_node_ids": list(result.target_focus_node_ids),
                "index_staging_state": result.index_staging_state,
                "deferred_reason": (
                    "no accepted external project commit-object decision packet"
                ),
                "recommended_next_gate": "project_commit_object_with_index_rollback",
                "project_commit_object_created": False,
                "project_ref_updated": False,
                "project_commit_created": False,
                "push_performed": False,
                "pull_request_created": False,
                "source_registry_mutated": False,
                "formal_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_commit_object_memory(
    *,
    project_index_staging_report: SourceControlProjectIndexStagingReport,
    decision_packets: tuple[SourceControlCommitObjectDecisionPacket, ...],
    commit_object_results: tuple[SourceControlCommitObjectResult, ...],
    deferred_index_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    verified = sum(
        1
        for result in commit_object_results
        if result.commit_object_state == "commit_object_created_rollback_verified"
    )
    return (
        {
            "memory_id": "a31_project_commit_object_summary",
            "retained_learning": (
                f"{verified} of {len(commit_object_results)} project commit-object "
                "executions created commit objects and verified index rollback"
            ),
            "recommended_strategy": (
                "permit git commit-tree only after A30 rollback proof, and keep "
                "branch ref updates behind a separate authority gate"
            ),
            "project_commit_object_creation_allowed": True,
            "project_ref_update_allowed": False,
            "project_commit_creation_allowed": False,
            "push_allowed": False,
            "formal_status_transition_allowed": False,
        },
        {
            "memory_id": "a31_deferred_project_index_staging_summary",
            "retained_learning": (
                f"{len(deferred_index_results)} of "
                f"{len(project_index_staging_report.project_index_staging_results)} "
                "fresh A30 results remain without A31 commit-object decisions"
            ),
            "decision_packets_seen": len(decision_packets),
            "recommended_strategy": (
                "keep A30 project-index staging results outside commit-object "
                "execution until explicit signed A31 decisions are available"
            ),
            "project_commit_object_creation_allowed": False,
            "project_ref_update_allowed": False,
        },
    )


def _source_control_commit_object_review_packet_markdown(
    commit_object_results: tuple[SourceControlCommitObjectResult, ...],
    deferred_index_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Commit Object Review",
        "",
        "Status: A31 commit-object packet. Runtime creates project commit objects with `git commit-tree` while keeping branch refs and final index state unchanged.",
        "",
        "| Result | State | Paths | Commit Object | Rollback | Ref Updated |",
        "|---|---|---:|---|---|---|",
    ]
    for result in commit_object_results:
        lines.append(
            f"| `{result.result_id}` | `{result.commit_object_state}` | "
            f"{len(result.stage_paths)} | `{result.project_commit_object_verified}` | "
            f"`{result.project_index_rollback_verified}` | "
            f"`{result.project_ref_updated}` |"
        )
    lines.extend(["", "## Deferred Project Index Staging Results", ""])
    if not deferred_index_results:
        lines.append("- none")
    else:
        for item in deferred_index_results:
            focus = ", ".join(item["target_focus_node_ids"])
            lines.append(f"- `{focus}`: {item['deferred_reason']}")
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- project git add: allowed only after A30 evidence",
            "- project write-tree and commit-tree: allowed",
            "- final project index mutation: blocked by rollback verification",
            "- branch/ref update: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- source registry mutation: blocked",
            "- formal construct status changes: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_existing_source_control_commit_object_results(
    *,
    source_control_commit_object_result_dirs: Iterable[Path],
    source_control_commit_object_result_files: Iterable[Path],
) -> tuple[SourceControlCommitObjectResult, ...]:
    paths: list[Path] = []
    for result_dir in source_control_commit_object_result_dirs:
        if result_dir.exists():
            paths.extend(sorted(result_dir.rglob("*.json")))
    for result_file in source_control_commit_object_result_files:
        if result_file.exists():
            paths.append(result_file)

    results: list[SourceControlCommitObjectResult] = []
    seen_ids: set[str] = set()
    for path in paths:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        candidates: list[dict[str, Any]] = []
        nested = payload.get("commit_object_results")
        if isinstance(nested, list):
            candidates.extend(item for item in nested if isinstance(item, dict))
        else:
            candidates.append(payload)
        for candidate in candidates:
            result = _source_control_commit_object_result_from_payload(candidate)
            if result.result_id in seen_ids:
                continue
            seen_ids.add(result.result_id)
            results.append(result)
    return tuple(results)


