def _load_source_control_ref_update_decisions(
    *,
    source_control_ref_update_decision_dirs: Iterable[Path],
    source_control_ref_update_decision_files: Iterable[Path],
    max_decisions: int,
) -> tuple[SourceControlRefUpdateDecisionPacket, ...]:
    if max_decisions < 1:
        return ()

    paths: list[Path] = []
    for decision_dir in source_control_ref_update_decision_dirs:
        if decision_dir.exists():
            paths.extend(sorted(decision_dir.rglob("*.json")))
    for decision_file in source_control_ref_update_decision_files:
        if decision_file.exists():
            paths.append(decision_file)

    packets: list[SourceControlRefUpdateDecisionPacket] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        packets.append(_source_control_ref_update_decision_from_payload(payload, path))
        if len(packets) >= max_decisions:
            break
    return tuple(packets)


def _source_control_ref_update_decision_from_payload(
    payload: dict[str, Any],
    path: Path,
) -> SourceControlRefUpdateDecisionPacket:
    target_result_ids = payload.get("target_commit_object_result_ids")
    target_focus_ids = payload.get("target_focus_node_ids")
    rationale = payload.get("rationale")
    constraints = payload.get("constraints")
    return SourceControlRefUpdateDecisionPacket(
        decision_id=str(payload.get("decision_id") or path.stem),
        target_commit_object_result_ids=(
            tuple(str(item) for item in target_result_ids)
            if isinstance(target_result_ids, list)
            else ()
        ),
        target_focus_node_ids=(
            tuple(str(item) for item in target_focus_ids)
            if isinstance(target_focus_ids, list)
            else ()
        ),
        ref_update_decision=str(payload.get("ref_update_decision") or "unknown"),
        review_gate=str(payload.get("review_gate") or "unknown"),
        approved_ref_update_state=str(
            payload.get("approved_ref_update_state") or "unknown"
        ),
        execution_mode=str(payload.get("execution_mode") or "unknown"),
        temporary_ref_name=str(payload.get("temporary_ref_name") or "").strip(),
        rationale=tuple(str(item) for item in rationale) if isinstance(rationale, list) else (),
        constraints=constraints if isinstance(constraints, dict) else {},
        source_path=str(path),
        signed_by=str(payload["signed_by"]) if isinstance(payload.get("signed_by"), str) else None,
        signature_token=(
            str(payload["signature_token"])
            if isinstance(payload.get("signature_token"), str)
            else None
        ),
    )


def _source_control_ref_update_block_reason(
    *,
    packet: SourceControlRefUpdateDecisionPacket,
    commit_object_results: tuple[SourceControlCommitObjectResult, ...],
) -> str | None:
    allowed_decisions = {
        "accept_temporary_ref_update_with_delete_rollback",
        "defer_temporary_ref_update_with_delete_rollback",
        "reject_temporary_ref_update_with_delete_rollback",
    }
    if packet.ref_update_decision not in allowed_decisions:
        return f"ref_update_decision {packet.ref_update_decision!r} is not allowed"
    if packet.review_gate != "project_temporary_ref_update_with_delete_rollback":
        return (
            f"review_gate {packet.review_gate!r} does not match "
            "'project_temporary_ref_update_with_delete_rollback'"
        )
    allowed_states = {
        "temporary_ref_update_rollback_ready",
        "deferred_by_temporary_ref_update_review",
        "rejected_by_temporary_ref_update_review",
    }
    if packet.approved_ref_update_state not in allowed_states:
        return (
            f"approved_ref_update_state {packet.approved_ref_update_state!r} "
            "is not allowed"
        )
    if not packet.target_commit_object_result_ids:
        return "ref-update decision has no target A31 commit-object results"
    found_result_ids = {result.result_id for result in commit_object_results}
    missing_result_ids = [
        result_id
        for result_id in packet.target_commit_object_result_ids
        if result_id not in found_result_ids
    ]
    if missing_result_ids:
        return (
            "target A31 commit-object results were not found: "
            + ", ".join(missing_result_ids)
        )
    if len(commit_object_results) != 1:
        return "temporary ref update requires exactly one target commit object result"
    focus_ids = set().union(
        *(set(result.target_focus_node_ids) for result in commit_object_results)
    )
    if set(packet.target_focus_node_ids) != focus_ids:
        return "target_focus_node_ids do not match target A31 commit-object focus ids"
    if not packet.signed_by:
        return "ref-update decision is missing signed_by"
    if not packet.signature_token:
        return "ref-update decision is missing signature_token"
    if not _is_safe_temporary_project_ref(packet.temporary_ref_name):
        return "temporary_ref_name must stay under refs/codex/experiments/"

    forbidden_true_constraints = (
        "allow_head_update",
        "allow_branch_ref_update",
        "allow_tag_ref_update",
        "allow_current_branch_update",
        "allow_persistent_ref_update",
        "allow_project_branch_creation",
        "allow_project_commit_creation",
        "allow_runtime_push",
        "allow_runtime_pull_request_creation",
        "allow_source_registry_mutation",
        "allow_formal_status_change",
        "allow_reference_status",
        "allow_open_ended_experiment",
    )
    for key in forbidden_true_constraints:
        if bool(packet.constraints.get(key, False)):
            return f"ref-update decision attempted to allow {key}"

    if packet.ref_update_decision != "accept_temporary_ref_update_with_delete_rollback":
        return None
    if packet.approved_ref_update_state != "temporary_ref_update_rollback_ready":
        return (
            "accepted ref-update decision must approve "
            "temporary_ref_update_rollback_ready"
        )
    if packet.execution_mode != "project_temporary_ref_update_with_delete_rollback":
        return (
            "accepted ref-update decision must use "
            "project_temporary_ref_update_with_delete_rollback"
        )
    required_true_constraints = (
        "allow_temporary_ref_update",
        "allow_project_ref_update_temporarily",
        "require_commit_object_verification",
        "require_temporary_ref_namespace",
        "require_temporary_ref_absent_before_update",
        "require_ref_delete_rollback",
        "require_final_ref_absent",
        "forbid_head_update",
        "forbid_branch_ref_update",
        "forbid_tag_ref_update",
        "forbid_push",
    )
    for key in required_true_constraints:
        if not bool(packet.constraints.get(key, False)):
            return f"accepted ref-update decision must allow {key}"

    for result in commit_object_results:
        if result.commit_object_state != "commit_object_created_rollback_verified":
            return f"A31 result {result.result_id!r} is not rollback verified"
        if result.execution_mode != "project_git_commit_object_with_index_rollback":
            return f"A31 result {result.result_id!r} did not use commit-object execution"
        if not result.commit_object_hash:
            return f"A31 result {result.result_id!r} has no commit object hash"
        if not result.project_commit_object_created:
            return f"A31 result {result.result_id!r} did not create a commit object"
        if not result.project_commit_object_verified:
            return f"A31 result {result.result_id!r} did not verify a commit object"
        if not result.project_index_rollback_verified:
            return f"A31 result {result.result_id!r} did not verify index rollback"
        if result.project_files_staged:
            return f"A31 result {result.result_id!r} left project files staged"
        if result.project_ref_updated or result.project_commit_created:
            return f"A31 result {result.result_id!r} reports project ref movement"
        if result.push_performed or result.pull_request_created:
            return f"A31 result {result.result_id!r} reports project publication"
        if result.source_registry_mutated:
            return f"A31 result {result.result_id!r} reports registry mutation"
        if result.formal_construct_status_change != "none":
            return f"A31 result {result.result_id!r} reports status change"
        if result.reference_status_granted:
            return f"A31 result {result.result_id!r} reports reference status"
        if result.open_ended_experiment_allowed:
            return f"A31 result {result.result_id!r} reports open experiment"
        if not all(bool(item.get("passed")) for item in result.command_results):
            return f"A31 result {result.result_id!r} has command failures"
    return None


def _is_safe_temporary_project_ref(ref_name: str) -> bool:
    if not ref_name.startswith("refs/codex/experiments/"):
        return False
    if ref_name.endswith("/") or "\\" in ref_name or "@{" in ref_name:
        return False
    if any(ord(char) < 32 or char.isspace() for char in ref_name):
        return False
    parts = ref_name.split("/")
    if any(part in {"", ".", ".."} for part in parts):
        return False
    forbidden_prefixes = ("refs/heads/", "refs/tags/", "HEAD")
    return not any(ref_name.startswith(prefix) for prefix in forbidden_prefixes)


def _refs_from_for_each_ref_command(command_result: dict[str, Any]) -> tuple[str, ...]:
    stdout_path = Path(str(command_result.get("stdout_path") or ""))
    if stdout_path.exists():
        try:
            stdout = stdout_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            stdout = ""
    else:
        stdout = str(command_result.get("stdout_excerpt") or "")
    return tuple(line.strip() for line in stdout.splitlines() if line.strip())


def _source_control_ref_update_from_commit_object_results(
    *,
    packet: SourceControlRefUpdateDecisionPacket,
    commit_object_results: tuple[SourceControlCommitObjectResult, ...],
    project_worktree_root: Path,
    ref_update_dir: Path,
    timeout_seconds: int,
) -> SourceControlRefUpdateResult:
    result_id = _safe_artifact_id(f"{packet.decision_id}_temporary_ref_update")
    command_output_dir = ref_update_dir / "cmd"
    command_timeout = max(1, timeout_seconds)
    target_result = commit_object_results[0]
    commit_object_hash = target_result.commit_object_hash
    temporary_ref = packet.temporary_ref_name
    command_results: list[dict[str, Any]] = []

    verify_object_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "cat-file", "-t", str(commit_object_hash)),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_verify_commit_object_before_ref_update",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results.append(verify_object_result)

    check_ref_format_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "check-ref-format", temporary_ref),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_check_temporary_ref_format",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results.append(check_ref_format_result)

    pre_ref_result = _execute_project_git_command(
        ("git", "-c", "core.longpaths=true", "for-each-ref", "--format=%(refname)", temporary_ref),
        cwd=project_worktree_root,
        output_dir=command_output_dir,
        result_id=result_id,
        command_id="git_pre_temporary_ref_snapshot",
        timeout_seconds=command_timeout,
        git_write_operation=False,
        modifies_project_index=False,
    )
    command_results.append(pre_ref_result)
    refs_before_update = _refs_from_for_each_ref_command(pre_ref_result)
    pre_existing_exact_ref = temporary_ref in refs_before_update

    object_type = _first_stdout_line_from_command(verify_object_result)
    object_verified = bool(verify_object_result.get("passed")) and object_type == "commit"
    safe_to_update = (
        object_verified
        and bool(check_ref_format_result.get("passed"))
        and bool(pre_ref_result.get("passed"))
        and not pre_existing_exact_ref
        and _is_safe_temporary_project_ref(temporary_ref)
    )

    update_result: dict[str, Any] | None = None
    verify_ref_result: dict[str, Any] | None = None
    delete_result: dict[str, Any] | None = None
    post_delete_result: dict[str, Any] | None = None
    final_index_result: dict[str, Any] | None = None
    ref_value_after_update: str | None = None
    refs_after_delete: tuple[str, ...] = ()
    if safe_to_update:
        update_result = _execute_project_git_command(
            ("git", "-c", "core.longpaths=true", "update-ref", temporary_ref, str(commit_object_hash)),
            cwd=project_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_update_temporary_ref",
            timeout_seconds=command_timeout,
            git_write_operation=True,
            modifies_project_index=False,
        )
        command_results.append(update_result)

        verify_ref_result = _execute_project_git_command(
            ("git", "-c", "core.longpaths=true", "rev-parse", "--verify", temporary_ref),
            cwd=project_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_verify_temporary_ref",
            timeout_seconds=command_timeout,
            git_write_operation=False,
            modifies_project_index=False,
        )
        command_results.append(verify_ref_result)
        ref_value_after_update = _first_stdout_line_from_command(verify_ref_result)

        delete_result = _execute_project_git_command(
            ("git", "-c", "core.longpaths=true", "update-ref", "-d", temporary_ref),
            cwd=project_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_delete_temporary_ref",
            timeout_seconds=command_timeout,
            git_write_operation=True,
            modifies_project_index=False,
        )
        command_results.append(delete_result)

        post_delete_result = _execute_project_git_command(
            ("git", "-c", "core.longpaths=true", "for-each-ref", "--format=%(refname)", temporary_ref),
            cwd=project_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_post_delete_temporary_ref_snapshot",
            timeout_seconds=command_timeout,
            git_write_operation=False,
            modifies_project_index=False,
        )
        command_results.append(post_delete_result)
        refs_after_delete = _refs_from_for_each_ref_command(post_delete_result)

        final_index_result = _execute_project_git_command(
            ("git", "-c", "core.longpaths=true", "diff", "--cached", "--name-only"),
            cwd=project_worktree_root,
            output_dir=command_output_dir,
            result_id=result_id,
            command_id="git_ref_update_final_index_snapshot",
            timeout_seconds=command_timeout,
            git_write_operation=False,
            modifies_project_index=False,
        )
        command_results.append(final_index_result)

    final_staged_paths = (
        _git_name_only_paths_from_command(final_index_result)
        if final_index_result is not None
        else ()
    )
    update_executed = update_result is not None and bool(update_result.get("passed"))
    ref_verified = (
        verify_ref_result is not None
        and bool(verify_ref_result.get("passed"))
        and ref_value_after_update == commit_object_hash
    )
    delete_executed = delete_result is not None and bool(delete_result.get("passed"))
    rollback_verified = (
        delete_executed
        and post_delete_result is not None
        and bool(post_delete_result.get("passed"))
        and temporary_ref not in refs_after_delete
        and not final_staged_paths
    )
    ref_update_state = (
        "temporary_ref_update_rollback_verified"
        if update_executed and ref_verified and rollback_verified
        else (
            "temporary_ref_update_blocked_preexisting_ref"
            if pre_existing_exact_ref
            else "temporary_ref_update_failed"
        )
    )
    findings = [
        "verified A31 commit object before temporary ref update",
        f"validated temporary ref namespace `{temporary_ref}`",
    ]
    if pre_existing_exact_ref:
        findings.append("temporary ref already existed before update; update was blocked")
    elif safe_to_update:
        findings.extend(
            [
                "updated temporary project ref to the A31 commit object",
                "verified temporary project ref resolved to the expected commit object",
                "deleted temporary project ref and verified final absence",
                "HEAD, branch refs, tag refs, project commits, push, pull request, registry mutation, and formal status changes stayed blocked",
            ]
        )
    else:
        findings.append("temporary ref update was not safe to execute")
    return SourceControlRefUpdateResult(
        result_id=result_id,
        source_decision_id=packet.decision_id,
        target_commit_object_result_ids=tuple(
            result.result_id for result in commit_object_results
        ),
        target_focus_node_ids=packet.target_focus_node_ids,
        ref_update_state=ref_update_state,
        execution_mode=packet.execution_mode,
        temporary_ref_name=temporary_ref,
        commit_object_hash=commit_object_hash,
        command_results=tuple(command_results),
        ref_value_after_update=ref_value_after_update,
        refs_after_delete=refs_after_delete,
        final_staged_paths=final_staged_paths,
        findings=tuple(findings),
        required_external_actions=(
            "review temporary ref rollback evidence before branch ref updates",
            "require a separate gate before moving HEAD or branch refs",
            "require a separate higher-risk gate before push or pull request creation",
            "do not infer formal construct status changes from temporary ref update success",
        ),
        project_commit_object_verified=object_verified,
        project_temporary_ref_update_executed=update_executed,
        project_temporary_ref_verified=ref_verified,
        project_temporary_ref_delete_executed=delete_executed,
        project_temporary_ref_rollback_verified=rollback_verified,
        project_ref_updated_temporarily=update_executed,
        project_ref_left_behind=temporary_ref in refs_after_delete,
        project_files_staged=bool(final_staged_paths),
    )


def _deferred_source_control_commit_object_results(
    commit_object_results: tuple[SourceControlCommitObjectResult, ...],
    *,
    consumed_commit_result_ids: set[str],
) -> tuple[dict[str, Any], ...]:
    deferred: list[dict[str, Any]] = []
    for result in commit_object_results:
        if result.result_id in consumed_commit_result_ids:
            continue
        deferred.append(
            {
                "commit_object_result_id": result.result_id,
                "target_focus_node_ids": list(result.target_focus_node_ids),
                "commit_object_state": result.commit_object_state,
                "commit_object_hash": result.commit_object_hash,
                "deferred_reason": (
                    "no accepted external temporary ref-update decision packet"
                ),
                "recommended_next_gate": "project_temporary_ref_update_with_delete_rollback",
                "project_ref_updated_temporarily": False,
                "project_temporary_ref_rollback_verified": False,
                "project_head_updated": False,
                "project_branch_ref_updated": False,
                "project_commit_created": False,
                "push_performed": False,
                "pull_request_created": False,
                "source_registry_mutated": False,
                "formal_status_change": "none",
            }
        )
    return tuple(deferred)


def _source_control_ref_update_memory(
    *,
    commit_object_report: SourceControlCommitObjectReport,
    decision_packets: tuple[SourceControlRefUpdateDecisionPacket, ...],
    ref_update_results: tuple[SourceControlRefUpdateResult, ...],
    deferred_commit_results: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    verified = sum(
        1
        for result in ref_update_results
        if result.ref_update_state == "temporary_ref_update_rollback_verified"
    )
    return (
        {
            "memory_id": "a32_project_temporary_ref_update_summary",
            "retained_learning": (
                f"{verified} of {len(ref_update_results)} temporary ref updates "
                "updated a scoped project ref and verified delete rollback"
            ),
            "recommended_strategy": (
                "permit temporary refs only under refs/codex/experiments/ after "
                "A31 commit-object proof, and keep HEAD and branch refs behind a "
                "separate authority gate"
            ),
            "temporary_ref_update_allowed": True,
            "head_update_allowed": False,
            "branch_ref_update_allowed": False,
            "push_allowed": False,
            "formal_status_transition_allowed": False,
        },
        {
            "memory_id": "a32_deferred_commit_object_summary",
            "retained_learning": (
                f"{len(deferred_commit_results)} of "
                f"{len(commit_object_report.commit_object_results)} fresh A31 "
                "results remain without A32 temporary ref-update decisions"
            ),
            "decision_packets_seen": len(decision_packets),
            "recommended_strategy": (
                "keep A31 commit objects outside ref updates until explicit signed "
                "A32 decisions are available"
            ),
            "temporary_ref_update_allowed": False,
            "head_update_allowed": False,
            "branch_ref_update_allowed": False,
        },
    )


def _source_control_ref_update_review_packet_markdown(
    ref_update_results: tuple[SourceControlRefUpdateResult, ...],
    deferred_commit_results: tuple[dict[str, Any], ...],
) -> str:
    lines = [
        "# Source-Control Temporary Ref Update Review",
        "",
        "Status: A32 temporary ref-update packet. Runtime updates only scoped `refs/codex/experiments/...` refs, verifies them, deletes them, and keeps HEAD plus branch refs unchanged.",
        "",
        "| Result | State | Temporary Ref | Ref Verified | Rollback | Branch Ref Updated |",
        "|---|---|---|---|---|---|",
    ]
    for result in ref_update_results:
        lines.append(
            f"| `{result.result_id}` | `{result.ref_update_state}` | "
            f"`{result.temporary_ref_name}` | "
            f"`{result.project_temporary_ref_verified}` | "
            f"`{result.project_temporary_ref_rollback_verified}` | "
            f"`{result.project_branch_ref_updated}` |"
        )
    lines.extend(["", "## Deferred Commit Object Results", ""])
    if not deferred_commit_results:
        lines.append("- none")
    else:
        for item in deferred_commit_results:
            focus = ", ".join(item["target_focus_node_ids"])
            lines.append(f"- `{focus}`: {item['deferred_reason']}")
    lines.extend(
        [
            "",
            "## Firewalls",
            "",
            "- temporary ref update: allowed only after A31 commit-object evidence",
            "- temporary ref namespace: `refs/codex/experiments/` only",
            "- temporary ref deletion: required",
            "- HEAD and branch refs: blocked",
            "- runtime push: blocked",
            "- runtime pull request creation: blocked",
            "- source registry mutation: blocked",
            "- formal construct status changes: blocked",
        ]
    )
    return "\n".join(lines) + "\n"


def _load_evidence_assets(
    *,
    asset_dirs: Iterable[Path],
    architecture: ConstructArchitecture,
    max_assets: int | None,
) -> tuple[EvidenceAsset, ...]:
    node_ids = {node.id for node in architecture.nodes}
    assets: list[EvidenceAsset] = []
    for asset_dir in asset_dirs:
        if not asset_dir.exists():
            continue
        for path in sorted(asset_dir.rglob("*.json")):
            if max_assets is not None and len(assets) >= max_assets:
                return tuple(assets)
            assets.append(_summarize_asset(path, node_ids))
    return tuple(assets)


def _write_artifact(path: Path, content: str) -> None:
    path.write_text(content, encoding="utf-8")


def _artifact_for(path: Path, artifact_type: str) -> ExecutionArtifact:
    digest = hashlib.sha256(path.read_bytes()).hexdigest()[:16]
    return ExecutionArtifact(
        path=str(path),
        artifact_type=artifact_type,
        content_hash=digest,
    )


def _load_reviewed_probe_approvals(
    *,
    approval_dirs: Iterable[Path],
    approval_files: Iterable[Path],
    max_approvals: int,
) -> tuple[ReviewedProbeApproval, ...]:
    paths: list[Path] = []
    for approval_dir in approval_dirs:
        if approval_dir.exists():
            paths.extend(sorted(approval_dir.rglob("*.json")))
    for approval_file in approval_files:
        if approval_file.exists():
            paths.append(approval_file)

    approvals: list[ReviewedProbeApproval] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        approvals.append(_approval_from_payload(payload, path))
        if len(approvals) >= max_approvals:
            break
    return tuple(approvals)


def _decision_artifact_from_probe_result(
    result: ValidationProbeExecutionResult,
) -> ReviewedDecisionArtifact:
    if result.status == "completed" and result.decision == "probe_passed":
        reviewed_decision = "advance_to_external_review_decision"
        required_action = (
            "external reviewer may open a status decision packet; no automatic transition is authorized"
        )
    elif result.status == "completed" and result.decision == "probe_failed":
        reviewed_decision = "return_to_rework_or_boundary_watch"
        required_action = "external reviewer should route the node to rework or boundary-watch review"
    else:
        reviewed_decision = "defer_until_probe_approval_is_resolved"
        required_action = "external reviewer should repair or reject the approval packet"
    decision_id = f"{result.node_id}_{result.approval_id}_decision"
    safe_decision_id = "".join(char if char.isalnum() or char in "._-" else "_" for char in decision_id)
    rationale = tuple(result.findings) + (
        f"Source probe status: {result.status}",
        f"Source probe decision: {result.decision}",
        "This artifact is review-only and does not change construct status.",
    )
    return ReviewedDecisionArtifact(
        decision_id=safe_decision_id,
        node_id=result.node_id,
        source_approval_id=result.approval_id,
        source_probe_type=result.probe_type,
        source_probe_decision=result.decision,
        reviewed_decision=reviewed_decision,
        rationale=rationale,
        required_external_action=required_action,
    )


def _approval_from_payload(payload: dict[str, Any], path: Path) -> ReviewedProbeApproval:
    budget = payload.get("budget")
    criteria = payload.get("criteria")
    return ReviewedProbeApproval(
        approval_id=str(payload.get("approval_id") or path.stem),
        node_id=str(payload.get("node_id") or ""),
        probe_type=str(payload.get("probe_type") or ""),
        approval_status=str(payload.get("approval_status") or payload.get("status") or "missing"),
        review_gate=str(payload.get("review_gate") or ""),
        budget=budget if isinstance(budget, dict) else {},
        criteria=criteria if isinstance(criteria, dict) else {},
        source_path=str(path),
        approved_by=str(payload["approved_by"]) if "approved_by" in payload else None,
    )


def _execute_reviewed_validation_probes(
    *,
    approvals: tuple[ReviewedProbeApproval, ...],
    controlled_report: ControlledResearchCycleReport,
    architecture: ConstructArchitecture,
) -> tuple[ValidationProbeExecutionResult, ...]:
    results: list[ValidationProbeExecutionResult] = []
    for approval in approvals:
        block_reason = _reviewed_probe_block_reason(
            approval=approval,
            controlled_report=controlled_report,
            architecture=architecture,
        )
        if block_reason is not None:
            results.append(
                ValidationProbeExecutionResult(
                    approval_id=approval.approval_id,
                    node_id=approval.node_id,
                    probe_type=approval.probe_type,
                    status="blocked",
                    decision="approval_blocked",
                    metrics={"block_reason": block_reason},
                    findings=(block_reason,),
                    allowed_next_action="return approval packet for review without running a probe",
                )
            )
            continue
        if approval.probe_type == "gate_readiness_validation":
            results.append(_execute_gate_readiness_validation(approval, controlled_report))
        elif approval.probe_type == "asset_support_validation":
            results.append(_execute_asset_support_validation(approval, controlled_report))
        elif approval.probe_type == "boundary_pressure_validation":
            results.append(_execute_boundary_pressure_validation(approval, controlled_report))
        elif approval.probe_type == "unmatched_pressure_validation":
            results.append(_execute_unmatched_pressure_validation(approval, controlled_report))
        else:
            results.append(
                ValidationProbeExecutionResult(
                    approval_id=approval.approval_id,
                    node_id=approval.node_id,
                    probe_type=approval.probe_type,
                    status="blocked",
                    decision="probe_type_blocked",
                    metrics={"allowed_probe_types": list(_allowed_reviewed_probe_types())},
                    findings=(f"Probe type is not allowed: {approval.probe_type}",),
                    allowed_next_action="submit a reviewed approval for an allowed local probe type",
                )
            )
    return tuple(results)


def _reviewed_probe_block_reason(
    *,
    approval: ReviewedProbeApproval,
    controlled_report: ControlledResearchCycleReport,
    architecture: ConstructArchitecture,
) -> str | None:
    if approval.approval_status != "approved":
        return f"Approval status is not approved: {approval.approval_status}"
    if approval.review_gate not in _allowed_reviewed_probe_gates():
        return f"Review gate is not allowed for local probe execution: {approval.review_gate}"
    if not approval.node_id:
        return "Approval packet does not name a node_id"
    if not any(node.id == approval.node_id for node in architecture.nodes):
        return f"Approval packet names an unknown node: {approval.node_id}"
    budget_max_assets = _int_from_any(approval.budget.get("max_assets"))
    if budget_max_assets is not None:
        counts = controlled_report.bounded_report.cycle_report.to_dict()["counts"]
        if counts["evidence_assets"] > budget_max_assets:
            return (
                f"Approval max_assets budget {budget_max_assets} is below "
                f"observed evidence assets {counts['evidence_assets']}"
            )
    return None


def _allowed_reviewed_probe_gates() -> tuple[str, ...]:
    return (
        "reviewed_validation_probe_execution",
        "external_owner_packet_review",
        "l2_5_or_l3_execution_approval",
        "boundary_watch_review",
    )


def _allowed_reviewed_probe_types() -> tuple[str, ...]:
    return (
        "gate_readiness_validation",
        "asset_support_validation",
        "boundary_pressure_validation",
        "unmatched_pressure_validation",
    )


def _execute_gate_readiness_validation(
    approval: ReviewedProbeApproval,
    controlled_report: ControlledResearchCycleReport,
) -> ValidationProbeExecutionResult:
    result_by_node = {result.node_id: result for result in controlled_report.gate_results}
    gate_result = result_by_node.get(approval.node_id)
    min_support = _int_from_any(approval.criteria.get("min_supporting_assets")) or 1
    ready = gate_result is not None and gate_result.status == "ready_for_review_gate_execution"
    supporting_assets = gate_result.supporting_asset_count if gate_result is not None else 0
    passed = ready and supporting_assets >= min_support
    return _validation_result(
        approval=approval,
        passed=passed,
        metrics={
            "ready_for_review_gate_execution": ready,
            "supporting_asset_count": supporting_assets,
            "min_supporting_assets": min_support,
        },
        pass_finding=(
            f"{approval.node_id} is ready for reviewed gate execution with "
            f"{supporting_assets} supporting assets"
        ),
        fail_finding=(
            f"{approval.node_id} is not ready or has fewer than {min_support} supporting assets"
        ),
    )


def _execute_asset_support_validation(
    approval: ReviewedProbeApproval,
    controlled_report: ControlledResearchCycleReport,
) -> ValidationProbeExecutionResult:
    assets = controlled_report.bounded_report.cycle_report.evidence_assets
    support_count = sum(1 for asset in assets if asset.matched_node_id == approval.node_id)
    min_support = _int_from_any(approval.criteria.get("min_supporting_assets")) or 1
    passed = support_count >= min_support
    return _validation_result(
        approval=approval,
        passed=passed,
        metrics={"supporting_asset_count": support_count, "min_supporting_assets": min_support},
        pass_finding=f"{approval.node_id} has {support_count} matched supporting assets",
        fail_finding=f"{approval.node_id} has only {support_count} matched supporting assets",
    )


def _execute_boundary_pressure_validation(
    approval: ReviewedProbeApproval,
    controlled_report: ControlledResearchCycleReport,
) -> ValidationProbeExecutionResult:
    hub_counts = dict(controlled_report.bounded_report.cycle_report.boundary_hubs)
    mentions = hub_counts.get(approval.node_id, 0)
    max_mentions = _int_from_any(approval.criteria.get("max_boundary_mentions")) or 20
    passed = mentions <= max_mentions
    return _validation_result(
        approval=approval,
        passed=passed,
        metrics={"boundary_mentions": mentions, "max_boundary_mentions": max_mentions},
        pass_finding=f"{approval.node_id} boundary pressure is within reviewed limit",
        fail_finding=f"{approval.node_id} boundary pressure exceeds reviewed limit",
    )


def _execute_unmatched_pressure_validation(
    approval: ReviewedProbeApproval,
    controlled_report: ControlledResearchCycleReport,
) -> ValidationProbeExecutionResult:
    counts = controlled_report.bounded_report.cycle_report.to_dict()["counts"]
    unmatched = counts["unmatched_assets"]
    max_unmatched = _int_from_any(approval.criteria.get("max_unmatched_assets")) or unmatched
    passed = unmatched <= max_unmatched
    return _validation_result(
        approval=approval,
        passed=passed,
        metrics={"unmatched_assets": unmatched, "max_unmatched_assets": max_unmatched},
        pass_finding="Unmatched evidence pressure is within reviewed limit",
        fail_finding="Unmatched evidence pressure exceeds reviewed limit",
    )


def _validation_result(
    *,
    approval: ReviewedProbeApproval,
    passed: bool,
    metrics: dict[str, Any],
    pass_finding: str,
    fail_finding: str,
) -> ValidationProbeExecutionResult:
    return ValidationProbeExecutionResult(
        approval_id=approval.approval_id,
        node_id=approval.node_id,
        probe_type=approval.probe_type,
        status="completed",
        decision="probe_passed" if passed else "probe_failed",
        metrics=metrics,
        findings=(pass_finding if passed else fail_finding,),
        allowed_next_action=(
            "write reviewed decision artifact; do not change construct status automatically"
            if passed
            else "return to rework or boundary-watch review; do not change construct status"
        ),
    )


def _int_from_any(value: Any) -> int | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            return None
    return None


def _proposal_packet_markdown(cycle_report: IntelligenceCycleReport) -> str:
    lines = [
        "# Transition Proposal Packet",
        "",
        "Status: review-gated proposal packet. No status changes are authorized by this file.",
        "",
        "| Node | Proposal | Priority | Required gate |",
        "|---|---|---|---|",
    ]
    for proposal in cycle_report.proposals:
        lines.append(
            f"| `{proposal.node_id}` | `{proposal.proposal_type}` | "
            f"`{proposal.priority}` | {proposal.required_review_gate} |"
        )
    lines.extend(["", "## Guardrails", ""])
    for guardrail in (
        "do_not_grant_reference_status",
        "do_not_grant_sixth_construct_status",
        "do_not_claim_subjective_consciousness",
        "do_not_overwrite_failure_history",
    ):
        lines.append(f"- `{guardrail}`")
    return "\n".join(lines) + "\n"


def _boundary_hub_report_markdown(cycle_report: IntelligenceCycleReport) -> str:
    lines = [
        "# Boundary Hub Report",
        "",
        "Status: generated from nearest-boundary structure.",
        "",
        "| Hub | Mentions |",
        "|---|---:|",
    ]
    for node_id, mentions in cycle_report.boundary_hubs:
        lines.append(f"| `{node_id}` | {mentions} |")
    lines.extend(
        [
            "",
            "## Execution Implication",
            "",
            "The highest-pressure hubs should be separated before broader frontier expansion.",
        ]
    )
    return "\n".join(lines) + "\n"


def _local_integrity_checks(
    architecture: ConstructArchitecture,
    cycle_report: IntelligenceCycleReport,
) -> dict[str, Any]:
    ids = [node.id for node in architecture.nodes]
    duplicate_node_ids = sorted(name for name, count in Counter(ids).items() if count > 1)
    id_set = set(ids)

    non_reference_missing_firewalls = []
    for node in architecture.nodes:
        if node.layer == "reference":
            continue
        missing = [
            claim for claim in REQUIRED_NON_REFERENCE_FIREWALLS if claim not in node.forbidden_claims
        ]
        if missing:
            non_reference_missing_firewalls.append({"id": node.id, "missing": missing})

    proposal_missing_guardrails = []
    proposal_unknown_nodes = []
    for proposal in cycle_report.proposals:
        if proposal.node_id not in id_set:
            proposal_unknown_nodes.append(proposal.node_id)
        missing = [
            guardrail
            for guardrail in REQUIRED_PROPOSAL_GUARDRAILS
            if guardrail not in proposal.forbidden_auto_actions
        ]
        if missing:
            proposal_missing_guardrails.append({"node_id": proposal.node_id, "missing": missing})

    counts = cycle_report.to_dict()["counts"]
    asset_count_consistent = (
        counts["evidence_assets"] == counts["matched_assets"] + counts["unmatched_assets"]
    )
    top_boundary_hub = (
        {"id": cycle_report.boundary_hubs[0][0], "mentions": cycle_report.boundary_hubs[0][1]}
        if cycle_report.boundary_hubs
        else None
    )
    passed = (
        not duplicate_node_ids
        and not non_reference_missing_firewalls
        and not proposal_missing_guardrails
        and not proposal_unknown_nodes
        and asset_count_consistent
    )
    return {
        "schema": "consciousness_benchmark.local_integrity_checks.v1",
        "passed": passed,
        "counts": {
            "architecture_nodes": len(ids),
            "evidence_assets": counts["evidence_assets"],
            "matched_assets": counts["matched_assets"],
            "unmatched_assets": counts["unmatched_assets"],
            "proposals": counts["proposals"],
        },
        "top_boundary_hub": top_boundary_hub,
        "checks": {
            "duplicate_node_ids": duplicate_node_ids,
            "non_reference_missing_firewalls": non_reference_missing_firewalls,
            "proposal_missing_guardrails": proposal_missing_guardrails,
            "proposal_unknown_nodes": proposal_unknown_nodes,
            "asset_count_consistent": asset_count_consistent,
        },
        "execution_boundary": {
            "status_changes_allowed": False,
            "experiment_execution_allowed": False,
            "allowed_actions": list(MEDIUM_RISK_ALLOWED_ACTIONS),
            "forbidden_actions": list(FORBIDDEN_EXECUTION_ACTIONS),
        },
    }


def _medium_risk_work_order_markdown(
    cycle_report: IntelligenceCycleReport,
    integrity_checks: dict[str, Any],
    *,
    proposal_limit_per_type: int = 8,
) -> str:
    grouped: dict[str, list[TransitionProposal]] = defaultdict(list)
    for proposal in cycle_report.proposals:
        grouped[proposal.proposal_type].append(proposal)

    lines = [
        "# Medium-Risk Work Order Drafts",
        "",
        "Status: draft-only local execution artifact. These work orders do not authorize construct promotion, experiment execution, or external outreach.",
        "",
        f"Local integrity checks passed: `{integrity_checks.get('passed')}`",
        "",
        "## Activation Boundary",
        "",
        "- A reviewer or operator must activate any work order before transition work starts.",
        "- Construct status changes remain forbidden in this layer.",
        "- Reference or sixth-construct status cannot be granted by these drafts.",
        "",
        "## Draft Queues",
        "",
    ]
    for proposal_type in sorted(grouped):
        proposals = grouped[proposal_type]
        lines.extend(
            [
                f"### `{proposal_type}`",
                "",
                "| Node | Priority | Required gate | Supporting assets |",
                "|---|---|---|---:|",
            ]
        )
        for proposal in proposals[:proposal_limit_per_type]:
            lines.append(
                f"| `{proposal.node_id}` | `{proposal.priority}` | "
                f"{proposal.required_review_gate} | {len(proposal.supporting_assets)} |"
            )
        omitted = len(proposals) - proposal_limit_per_type
        if omitted > 0:
            lines.append(f"| ... | ... | ... | {omitted} more omitted |")
        lines.extend(
            [
                "",
                "Draft next actions:",
                "",
                "1. Assign a reviewer for the required gate.",
                "2. Check supporting assets against the local integrity report.",
                "3. Split proposal evidence from boundary-debt evidence.",
                "4. Record any acceptance, rejection, or deferral in a separate reviewed decision artifact.",
                "",
            ]
        )
    return "\n".join(lines).rstrip() + "\n"


def _append_only_architecture_snapshot(
    *,
    architecture: ConstructArchitecture,
    cycle_report: IntelligenceCycleReport,
    integrity_checks: dict[str, Any],
    date_tag: str,
) -> dict[str, Any]:
    snapshot = architecture.to_dict()
    snapshot["snapshot_policy"] = {
        "mode": "append_only_medium_risk_execution_artifact",
        "date_tag": date_tag,
        "source_cycle_schema": "consciousness_benchmark.research_intelligence_cycle.v1",
        "status_changes_applied": False,
        "claim_boundary_changed": False,
    }
    snapshot["execution_context"] = {
        "risk_mode": "medium",
        "integrity_checks_passed": integrity_checks.get("passed"),
        "evidence_assets": len(cycle_report.evidence_assets),
        "matched_assets": len(cycle_report.evidence_assets) - len(cycle_report.unmatched_assets),
        "unmatched_assets": len(cycle_report.unmatched_assets),
        "proposals": len(cycle_report.proposals),
        "top_boundary_hubs": [
            {"id": node_id, "mentions": mentions}
            for node_id, mentions in cycle_report.boundary_hubs[:5]
        ],
    }
    return snapshot


def _select_gate_work_items(
    cycle_report: IntelligenceCycleReport,
    *,
    max_gate_executions: int,
) -> tuple[TransitionProposal, ...]:
    priority_order = {"critical": 0, "high": 1, "medium": 2, "guardrail": 3}
    return tuple(
        proposal
        for _index, proposal in sorted(
            enumerate(cycle_report.proposals),
            key=lambda item: (priority_order.get(item[1].priority, 99), item[0]),
        )[:max_gate_executions]
    )


def _run_local_gate_checks(
    *,
    architecture: ConstructArchitecture,
    cycle_report: IntelligenceCycleReport,
    integrity_checks: dict[str, Any],
    selected: tuple[TransitionProposal, ...],
) -> tuple[GateExecutionResult, ...]:
    assets_by_node = _group_assets_by_node(cycle_report.evidence_assets)
    top_hubs = {node_id for node_id, _mentions in cycle_report.boundary_hubs[:5]}
    results: list[GateExecutionResult] = []

    for proposal in selected:
        node = architecture.get(proposal.node_id)
        supporting_assets = assets_by_node.get(node.id, [])
        proposal_guardrails_ok = all(
            guardrail in proposal.forbidden_auto_actions
            for guardrail in REQUIRED_PROPOSAL_GUARDRAILS
        )
        if node.layer == "reference":
            firewall_ok = True
        else:
            firewall_ok = all(
                claim in node.forbidden_claims for claim in REQUIRED_NON_REFERENCE_FIREWALLS
            )
        boundary_hub_overlap = tuple(
            boundary for boundary in node.nearest_boundaries if boundary in top_hubs
        )
        executed_checks = (
            "supporting_asset_presence",
            "claim_firewall_enforced",
            "proposal_guardrails_enforced",
            "boundary_overlap_mapped",
            "review_gate_preserved",
        )
        critic_findings = _critic_findings_for_gate_result(
            proposal=proposal,
            node=node,
            supporting_asset_count=len(supporting_assets),
            boundary_hub_overlap=boundary_hub_overlap,
            integrity_passed=bool(integrity_checks.get("passed")),
            firewall_ok=firewall_ok,
            proposal_guardrails_ok=proposal_guardrails_ok,
        )
        if not integrity_checks.get("passed"):
            status = "blocked_by_integrity_failure"
            allowed_next_action = "fix local integrity failures before any review-gate work"
        elif not firewall_ok or not proposal_guardrails_ok:
            status = "blocked_by_claim_firewall"
            allowed_next_action = "restore claim firewalls before any transition review"
        elif len(supporting_assets) == 0:
            status = "needs_evidence_triage_before_gate"
            allowed_next_action = "triage unmatched evidence and attach supporting assets"
        else:
            status = "ready_for_review_gate_execution"
            allowed_next_action = f"open reviewed {proposal.required_review_gate} packet"

        results.append(
            GateExecutionResult(
                node_id=node.id,
                proposal_type=proposal.proposal_type,
                required_review_gate=proposal.required_review_gate,
                status=status,
                supporting_asset_count=len(supporting_assets),
                boundary_hub_overlap=boundary_hub_overlap,
                executed_checks=executed_checks,
                critic_findings=critic_findings,
                allowed_next_action=allowed_next_action,
            )
        )
    return tuple(results)


def _critic_findings_for_gate_result(
    *,
    proposal: TransitionProposal,
    node: ConstructNode,
    supporting_asset_count: int,
    boundary_hub_overlap: tuple[str, ...],
    integrity_passed: bool,
    firewall_ok: bool,
    proposal_guardrails_ok: bool,
) -> tuple[str, ...]:
    findings: list[str] = []
    if not integrity_passed:
        findings.append("local integrity checks did not pass")
    if not firewall_ok:
        findings.append("node claim firewall is incomplete")
    if not proposal_guardrails_ok:
        findings.append("proposal guardrails are incomplete")
    if supporting_asset_count == 0:
        findings.append("no matched supporting assets were found for this node")
    if boundary_hub_overlap:
        findings.append(
            "proposal touches high-pressure boundary hubs: "
            + ", ".join(boundary_hub_overlap)
        )
    if node.layer != "reference":
        findings.append("non-reference route remains forbidden from reference promotion")
    if proposal.priority in {"critical", "high"}:
        findings.append("priority is high enough for review-gate preparation")
    return tuple(findings)


def _build_controlled_thought_trace(
    *,
    cycle_report: IntelligenceCycleReport,
    integrity_checks: dict[str, Any],
    selected: tuple[TransitionProposal, ...],
    gate_results: tuple[GateExecutionResult, ...],
) -> tuple[ThoughtStep, ...]:
    counts = cycle_report.to_dict()["counts"]
    top_hub = cycle_report.boundary_hubs[0][0] if cycle_report.boundary_hubs else "none"
    selected_nodes = ", ".join(proposal.node_id for proposal in selected) or "none"
    ready_count = sum(1 for result in gate_results if result.status == "ready_for_review_gate_execution")
    blocked_count = len(gate_results) - ready_count
    return (
        ThoughtStep(
            phase="observe",
            focus="evidence_state",
            conclusion=(
                f"{counts['evidence_assets']} assets observed; "
                f"{counts['matched_assets']} matched and {counts['unmatched_assets']} unmatched."
            ),
            evidence=("research_intelligence_cycle",),
        ),
        ThoughtStep(
            phase="orient",
            focus="boundary_pressure",
            conclusion=f"Top pressure hub is {top_hub}; gate work should preserve boundary separation.",
            evidence=("boundary_hubs",),
        ),
        ThoughtStep(
            phase="select",
            focus="gate_work_items",
            conclusion=f"Selected {len(selected)} proposals for local gate checks: {selected_nodes}.",
            evidence=("transition_proposals",),
        ),
        ThoughtStep(
            phase="critic",
            focus="claim_and_execution_firewall",
            conclusion=(
                "Integrity passed; local execution may proceed."
                if integrity_checks.get("passed")
                else "Integrity failed; local execution must stop at diagnostics."
            ),
            evidence=("local_integrity_checks",),
        ),
        ThoughtStep(
            phase="act",
            focus="local_gate_checks",
            conclusion=f"Executed {len(gate_results)} local gate checks; {ready_count} ready, {blocked_count} blocked or triage-needed.",
            evidence=("gate_execution_results",),
        ),
        ThoughtStep(
            phase="remember",
            focus="append_only_memory",
            conclusion="Wrote memory record for future review without changing construct status.",
            evidence=("autonomous_memory_record",),
        ),
    )


def _build_autonomous_memory_record(
    *,
    cycle_report: IntelligenceCycleReport,
    integrity_checks: dict[str, Any],
    gate_results: tuple[GateExecutionResult, ...],
    date_tag: str,
) -> AutonomousMemoryRecord:
    counts = cycle_report.to_dict()["counts"]
    ready_nodes = tuple(
        result.node_id
        for result in gate_results
        if result.status == "ready_for_review_gate_execution"
    )
    unresolved = [
        f"{counts['unmatched_assets']} unmatched evidence assets require triage",
    ]
    unresolved.extend(
        f"{result.node_id}: {result.status}"
        for result in gate_results
        if result.status != "ready_for_review_gate_execution"
    )
    cycle_seed = json.dumps(
        {
            "date_tag": date_tag,
            "counts": counts,
            "ready_nodes": ready_nodes,
            "integrity_passed": integrity_checks.get("passed"),
        },
        sort_keys=True,
    ).encode("utf-8")
    cycle_id = hashlib.sha256(cycle_seed).hexdigest()[:16]
    retained_facts = (
        f"evidence_assets={counts['evidence_assets']}",
        f"matched_assets={counts['matched_assets']}",
        f"unmatched_assets={counts['unmatched_assets']}",
        f"transition_proposals={counts['proposals']}",
        f"integrity_passed={integrity_checks.get('passed')}",
        "ready_nodes=" + ",".join(ready_nodes),
    )
    return AutonomousMemoryRecord(
        cycle_id=cycle_id,
        autonomy_level="A4_controlled_gate_executor",
        retained_facts=retained_facts,
        unresolved_items=tuple(unresolved),
    )


def _thought_trace_markdown(thought_trace: tuple[ThoughtStep, ...]) -> str:
    lines = [
        "# Controlled Thought Trace",
        "",
        "Status: symbolic deliberation trace. This file records bounded reasoning, not subjective thought.",
        "",
        "| Phase | Focus | Conclusion | Evidence |",
        "|---|---|---|---|",
    ]
    for step in thought_trace:
        lines.append(
            f"| `{step.phase}` | {step.focus} | {step.conclusion} | "
            f"{', '.join(step.evidence)} |"
        )
    return "\n".join(lines) + "\n"


def _scan_asset_inventory(
    *,
    asset_dirs: Iterable[Path],
    max_assets: int | None,
) -> AssetInventorySnapshot:
    source_dirs = tuple(str(asset_dir.resolve()) for asset_dir in asset_dirs)
    path_hashes: dict[str, str] = {}
    for asset_dir in (Path(source_dir) for source_dir in source_dirs):
        if not asset_dir.exists():
            continue
        for path in sorted(asset_dir.rglob("*.json")):
            if max_assets is not None and len(path_hashes) >= max_assets:
                return _inventory_from_hashes(path_hashes, asset_dirs=source_dirs)
            path_hashes[str(path)] = hashlib.sha256(path.read_bytes()).hexdigest()[:16]
    return _inventory_from_hashes(path_hashes, asset_dirs=source_dirs)


def _inventory_from_hashes(
    path_hashes: dict[str, str],
    *,
    asset_dirs: Iterable[str] = (),
) -> AssetInventorySnapshot:
    raw = json.dumps(dict(sorted(path_hashes.items())), sort_keys=True).encode("utf-8")
    return AssetInventorySnapshot(
        asset_count=len(path_hashes),
        asset_dirs=tuple(asset_dirs),
        inventory_hash=hashlib.sha256(raw).hexdigest()[:16],
        path_hashes=path_hashes,
    )


def _load_previous_inventory(state_file: Path) -> AssetInventorySnapshot | None:
    if not state_file.exists():
        return None
    try:
        payload = json.loads(state_file.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, UnicodeDecodeError):
        return None
    inventory = payload.get("asset_inventory")
    if not isinstance(inventory, dict):
        return None
    path_hashes = inventory.get("path_hashes")
    if not isinstance(path_hashes, dict):
        return None
    asset_dirs = inventory.get("asset_dirs")
    clean_asset_dirs = (
        tuple(str(asset_dir) for asset_dir in asset_dirs)
        if isinstance(asset_dirs, list)
        else ()
    )
    clean_hashes = {
        str(path): str(content_hash)
        for path, content_hash in path_hashes.items()
        if isinstance(path, str)
    }
    return _inventory_from_hashes(clean_hashes, asset_dirs=clean_asset_dirs)


def _asset_change_set(
    previous: AssetInventorySnapshot | None,
    current: AssetInventorySnapshot,
) -> AssetChangeSet:
    if previous is None:
        return AssetChangeSet(
            added=tuple(sorted(current.path_hashes)),
            changed=(),
            removed=(),
            unchanged_count=0,
            previous_inventory_hash=None,
            current_inventory_hash=current.inventory_hash,
        )

    previous_paths = set(previous.path_hashes)
    current_paths = set(current.path_hashes)
    added = tuple(sorted(current_paths - previous_paths))
    removed = tuple(sorted(previous_paths - current_paths))
    shared = previous_paths & current_paths
    changed = tuple(
        sorted(
            path
            for path in shared
            if previous.path_hashes.get(path) != current.path_hashes.get(path)
        )
    )
    unchanged_count = sum(
        1
        for path in shared
        if previous.path_hashes.get(path) == current.path_hashes.get(path)
    )
    return AssetChangeSet(
        added=added,
        changed=changed,
        removed=removed,
        unchanged_count=unchanged_count,
        previous_inventory_hash=previous.inventory_hash,
        current_inventory_hash=current.inventory_hash,
    )


def _select_autonomous_goals(
    *,
    controlled_report: ControlledResearchCycleReport,
    asset_changes: AssetChangeSet,
    max_goals: int,
) -> tuple[AutonomousGoal, ...]:
    counts = controlled_report.bounded_report.cycle_report.to_dict()["counts"]
    ready_gate_count = sum(
        1
        for result in controlled_report.gate_results
        if result.status == "ready_for_review_gate_execution"
    )
    goals: list[AutonomousGoal] = []
    if asset_changes.has_changes:
        goals.append(
            AutonomousGoal(
                goal_id="asset_delta_triage",
                priority="critical",
                rationale="New, changed, or removed evidence assets can alter construct-route pressure.",
                probe_type="asset_change_probe",
            )
        )
    if counts["unmatched_assets"] > 0:
        goals.append(
            AutonomousGoal(
                goal_id="unmatched_evidence_triage",
                priority="high",
                rationale="Unmatched assets are the largest blind spot in the current architecture memory.",
                probe_type="unmatched_asset_probe",
            )
        )
    if ready_gate_count > 0:
        goals.append(
            AutonomousGoal(
                goal_id="review_gate_preflight",
                priority="high",
                rationale="Selected gate checks are ready for reviewed packet preparation.",
                probe_type="gate_readiness_probe",
            )
        )
    if controlled_report.bounded_report.cycle_report.boundary_hubs:
        goals.append(
            AutonomousGoal(
                goal_id="boundary_pressure_watch",
                priority="medium",
                rationale="Boundary hubs should be watched before expanding frontier work.",
                probe_type="boundary_pressure_probe",
            )
        )
    if not goals:
        goals.append(
            AutonomousGoal(
                goal_id="idle_monitoring",
                priority="low",
                rationale="No changes or open local probes were detected; preserve state and wait.",
                probe_type="idle_probe",
                requires_review_to_apply=False,
            )
        )
    priority_order = {"critical": 0, "high": 1, "medium": 2, "low": 3}
    return tuple(sorted(goals, key=lambda goal: priority_order.get(goal.priority, 99))[:max_goals])


def _run_safe_local_probes(
    *,
    goals: tuple[AutonomousGoal, ...],
    controlled_report: ControlledResearchCycleReport,
    asset_changes: AssetChangeSet,
) -> tuple[SafeProbeResult, ...]:
    results: list[SafeProbeResult] = []
    for goal in goals:
        if goal.probe_type == "asset_change_probe":
            results.append(_asset_change_probe(goal, asset_changes))
        elif goal.probe_type == "unmatched_asset_probe":
            results.append(_unmatched_asset_probe(goal, controlled_report))
        elif goal.probe_type == "gate_readiness_probe":
            results.append(_gate_readiness_probe(goal, controlled_report))
        elif goal.probe_type == "boundary_pressure_probe":
            results.append(_boundary_pressure_probe(goal, controlled_report))
        else:
            results.append(
                SafeProbeResult(
                    probe_id="idle_probe",
                    goal_id=goal.goal_id,
                    status="completed",
                    metrics={"open_actions": 0},
                    findings=("No local change-driven action was selected.",),
                    allowed_next_action="wait for the next monitored asset change",
                )
            )
    return tuple(results)


def _asset_change_probe(goal: AutonomousGoal, asset_changes: AssetChangeSet) -> SafeProbeResult:
    change_data = asset_changes.to_dict()
    counts = change_data["counts"]
    findings = (
        f"{counts['added']} assets added",
        f"{counts['changed']} assets changed",
        f"{counts['removed']} assets removed",
    )
    return SafeProbeResult(
        probe_id="asset_change_probe",
        goal_id=goal.goal_id,
        status="completed",
        metrics=counts,
        findings=findings,
        allowed_next_action="review added and changed assets before accepting new transition pressure",
    )


def _unmatched_asset_probe(
    goal: AutonomousGoal,
    controlled_report: ControlledResearchCycleReport,
) -> SafeProbeResult:
    unmatched = controlled_report.bounded_report.cycle_report.unmatched_assets
    route_hint_counts = Counter(asset.route_hint or "none" for asset in unmatched)
    top_hints = [
        {"route_hint": route_hint, "count": count}
        for route_hint, count in route_hint_counts.most_common(10)
    ]
    findings = (
        f"{len(unmatched)} unmatched assets remain outside known architecture nodes",
        "top unmatched hints: " + ", ".join(item["route_hint"] for item in top_hints[:5]),
    )
    return SafeProbeResult(
        probe_id="unmatched_asset_probe",
        goal_id=goal.goal_id,
        status="completed",
        metrics={"unmatched_assets": len(unmatched), "top_route_hints": top_hints},
        findings=findings,
        allowed_next_action="add reviewed route mappings or classify unmatched assets as external evidence",
    )


def _gate_readiness_probe(
    goal: AutonomousGoal,
    controlled_report: ControlledResearchCycleReport,
) -> SafeProbeResult:
    ready = [
        result
        for result in controlled_report.gate_results
        if result.status == "ready_for_review_gate_execution"
    ]
    nodes = [result.node_id for result in ready]
    supporting_assets = {
        result.node_id: result.supporting_asset_count for result in ready
    }
    findings = (
        f"{len(ready)} selected gates are ready for reviewed execution",
        "ready nodes: " + ", ".join(nodes),
    )
    return SafeProbeResult(
        probe_id="gate_readiness_probe",
        goal_id=goal.goal_id,
        status="completed",
        metrics={"ready_gate_count": len(ready), "supporting_assets": supporting_assets},
        findings=findings,
        allowed_next_action="open reviewed external-owner packets for ready gates",
    )


def _boundary_pressure_probe(
    goal: AutonomousGoal,
    controlled_report: ControlledResearchCycleReport,
) -> SafeProbeResult:
    hubs = controlled_report.bounded_report.cycle_report.boundary_hubs[:5]
    findings = tuple(
        f"{node_id} has {mentions} nearest-boundary mentions"
        for node_id, mentions in hubs
    )
    return SafeProbeResult(
        probe_id="boundary_pressure_probe",
        goal_id=goal.goal_id,
        status="completed",
        metrics={
            "top_boundary_hubs": [
                {"id": node_id, "mentions": mentions} for node_id, mentions in hubs
            ]
        },
        findings=findings,
        allowed_next_action="prioritize boundary separation before opening new frontier candidates",
    )


def _build_autonomous_loop_memory_record(
    *,
    controlled_report: ControlledResearchCycleReport,
    asset_changes: AssetChangeSet,
    goals: tuple[AutonomousGoal, ...],
    probe_results: tuple[SafeProbeResult, ...],
    date_tag: str,
) -> AutonomousMemoryRecord:
    counts = controlled_report.bounded_report.cycle_report.to_dict()["counts"]
    change_counts = asset_changes.to_dict()["counts"]
    ready_nodes = [
        result.node_id
        for result in controlled_report.gate_results
        if result.status == "ready_for_review_gate_execution"
    ]
    cycle_seed = json.dumps(
        {
            "date_tag": date_tag,
            "counts": counts,
            "changes": change_counts,
            "goals": [goal.goal_id for goal in goals],
            "probes": [result.probe_id for result in probe_results],
        },
        sort_keys=True,
    ).encode("utf-8")
    retained_facts = (
        f"evidence_assets={counts['evidence_assets']}",
        f"matched_assets={counts['matched_assets']}",
        f"unmatched_assets={counts['unmatched_assets']}",
        f"asset_changes_added={change_counts['added']}",
        f"asset_changes_changed={change_counts['changed']}",
        f"asset_changes_removed={change_counts['removed']}",
        "selected_goals=" + ",".join(goal.goal_id for goal in goals),
        "safe_probes=" + ",".join(result.probe_id for result in probe_results),
        "ready_nodes=" + ",".join(ready_nodes),
    )
    unresolved = [f"{counts['unmatched_assets']} unmatched evidence assets require triage"]
    unresolved.extend(
        result.allowed_next_action
        for result in probe_results
        if result.allowed_next_action
    )
    return AutonomousMemoryRecord(
        cycle_id=hashlib.sha256(cycle_seed).hexdigest()[:16],
        autonomy_level="A5_invoked_autonomous_research_loop_prototype",
        retained_facts=retained_facts,
        unresolved_items=tuple(dict.fromkeys(unresolved)),
    )


def _autonomous_goal_plan_markdown(
    goals: tuple[AutonomousGoal, ...],
    asset_changes: AssetChangeSet,
) -> str:
    counts = asset_changes.to_dict()["counts"]
    lines = [
        "# Autonomous Goal Plan",
        "",
        "Status: self-selected local goals after invocation. This plan does not authorize status changes.",
        "",
        f"Asset changes: +{counts['added']} / ~{counts['changed']} / -{counts['removed']}",
        "",
        "| Goal | Priority | Probe | Review required |",
        "|---|---|---|---|",
    ]
    for goal in goals:
        review = "yes" if goal.requires_review_to_apply else "no"
        lines.append(f"| `{goal.goal_id}` | `{goal.priority}` | `{goal.probe_type}` | {review} |")
    return "\n".join(lines) + "\n"


def _next_wakeup_plan_markdown(
    state_file: Path,
    output_dir: Path,
    asset_dirs: tuple[Path, ...],
    goals: tuple[AutonomousGoal, ...],
) -> str:
    asset_args = " ".join(f'--asset-dir "{asset_dir}"' for asset_dir in asset_dirs)
    lines = [
        "# Next Wakeup Plan",
        "",
        "Status: runnable plan for an external scheduler or operator. The loop does not install a scheduler by itself.",
        "",
        f"State file: `{state_file}`",
        f"Output dir: `{output_dir}`",
        "",
        "Recommended next invocation:",
        "",
        "```powershell",
        "python -m consciousness_benchmark intelligence-loop "
        f"{asset_args} --output-dir \"{output_dir}\" --state-file \"{state_file}\"",
        "```",
        "",
        "Open goals to revisit:",
        "",
    ]
    for goal in goals:
        lines.append(f"- `{goal.goal_id}`")
    return "\n".join(lines) + "\n"


def _autonomous_loop_state_payload(
    *,
    asset_inventory: AssetInventorySnapshot,
    asset_changes: AssetChangeSet,
    memory_record: AutonomousMemoryRecord,
    goals: tuple[AutonomousGoal, ...],
    probe_results: tuple[SafeProbeResult, ...],
    date_tag: str,
) -> dict[str, Any]:
    return {
        "schema": "consciousness_benchmark.autonomous_loop_state.v1",
        "date_tag": date_tag,
        "asset_inventory": asset_inventory.to_dict(),
        "last_asset_changes": asset_changes.to_dict(),
        "last_memory_record": memory_record.to_dict(),
        "last_goals": [goal.to_dict() for goal in goals],
        "last_probe_results": [result.to_dict() for result in probe_results],
        "policy": {
            "can_self_start": False,
            "status_changes_allowed": False,
            "experiment_execution_allowed": False,
            "claim_escalation_allowed": False,
        },
    }


def _summarize_asset(path: Path, node_ids: set[str]) -> EvidenceAsset:
    raw = path.read_bytes()
    content_hash = hashlib.sha256(raw).hexdigest()[:16]
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        payload = {}
    if not isinstance(payload, dict):
        payload = {}

    route_hint = _first_string(
        payload,
        (
            "id",
            "route_id",
            "route",
            "target_preconstruct",
            "target_construct",
            "target_candidate",
            "candidate_name",
            "validation_candidate_name",
        ),
    )
    matched_node_id = _match_node_id(path.stem, payload, node_ids)
    return EvidenceAsset(
        path=str(path),
        asset_id=path.stem,
        matched_node_id=matched_node_id,
        asset_schema=_string_or_none(payload.get("asset_schema")),
        decision=_string_or_none(payload.get("decision")),
        status=_string_or_none(payload.get("status")),
        route_hint=route_hint,
        content_hash=content_hash,
    )


def _first_string(payload: dict[str, Any], keys: tuple[str, ...]) -> str | None:
    for key in keys:
        value = payload.get(key)
        if isinstance(value, str):
            return value
    return None


def _string_or_none(value: Any) -> str | None:
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        return json.dumps(value, sort_keys=True)
    return None


def _match_node_id(stem: str, payload: dict[str, Any], node_ids: set[str]) -> str | None:
    for key in (
        "id",
        "route_id",
        "route",
        "target_preconstruct",
        "target_construct",
        "target_candidate",
        "candidate_name",
        "validation_candidate_name",
    ):
        value = payload.get(key)
        if isinstance(value, str) and value in node_ids:
            return value

    matches = sorted((node_id for node_id in node_ids if node_id in stem), key=len, reverse=True)
    if matches:
        return matches[0]

    stripped = stem
    changed = True
    while changed:
        changed = False
        for suffix in KNOWN_SUFFIXES:
            if stripped.endswith(suffix):
                stripped = stripped[: -len(suffix)]
                changed = True
    if stripped in node_ids:
        return stripped
    return None


def _group_assets_by_node(evidence_assets: tuple[EvidenceAsset, ...]) -> dict[str, list[EvidenceAsset]]:
    grouped: dict[str, list[EvidenceAsset]] = defaultdict(list)
    for asset in evidence_assets:
        if asset.matched_node_id is not None:
            grouped[asset.matched_node_id].append(asset)
    return grouped


def _build_transition_proposals(
    architecture: ConstructArchitecture,
    assets_by_node: dict[str, list[EvidenceAsset]],
) -> tuple[TransitionProposal, ...]:
    proposals: list[TransitionProposal] = []
    work_queues = architecture.work_queues()

    for node_id in work_queues["l3_validation_candidate_queue"]:
        node = architecture.get(node_id)
        proposals.append(
            _proposal_for_node(
                node,
                assets_by_node,
                proposal_type="prepare_l3_external_owner_review",
                priority="critical",
                rationale="Validation candidates are mature enough for external-owner review, but cannot become references without L3 evidence.",
                required_review_gate="external_owner_packet_review",
            )
        )

    for node_id in work_queues["packet_ready_candidate_only_queue"]:
        node = architecture.get(node_id)
        proposals.append(
            _proposal_for_node(
                node,
                assets_by_node,
                proposal_type="prepare_l2_5_or_l3_execution_packet",
                priority="high",
                rationale="Packet-ready candidate-only route has internal rework progress but still lacks clean-room or external execution.",
                required_review_gate="l2_5_or_l3_execution_approval",
            )
        )

    for node_id in work_queues["batch5_governed_rework_queue"]:
        node = architecture.get(node_id)
        proposals.append(
            _proposal_for_node(
                node,
                assets_by_node,
                proposal_type="continue_batch5_governed_rework_review",
                priority="high",
                rationale="Batch5 governed rework routes sit on high-pressure hubs and should be reviewed before opening broader frontier work.",
                required_review_gate="batch5_governance_review",
            )
        )

    for node_id in work_queues["severe_boundary_watch_queue"]:
        node = architecture.get(node_id)
        proposals.append(
            _proposal_for_node(
                node,
                assets_by_node,
                proposal_type="run_boundary_hub_separation_review",
                priority="high",
                rationale="Severe boundary-watch routes need pairwise separation before any validation-candidate review.",
                required_review_gate="boundary_watch_review",
            )
        )

    for node_id in work_queues["substitute_pool"]:
        node = architecture.get(node_id)
        proposals.append(
            _proposal_for_node(
                node,
                assets_by_node,
                proposal_type="retain_as_substitute_or_write_fresh_scout",
                priority="medium",
                rationale="Substitute routes are useful variation sources but are not evidence until a frozen scout path is opened.",
                required_review_gate="fresh_scout_spec_review",
            )
        )

    for node_id in work_queues["failure_bank"]:
        node = architecture.get(node_id)
        proposals.append(
            _proposal_for_node(
                node,
                assets_by_node,
                proposal_type="retain_failure_bank_control",
                priority="guardrail",
                rationale="Failure-bank route should remain a negative control unless a new definition and boundary mechanism are supplied.",
                required_review_gate="failure_reopen_review",
            )
        )

    return tuple(proposals)


def _proposal_for_node(
    node: ConstructNode,
    assets_by_node: dict[str, list[EvidenceAsset]],
    *,
    proposal_type: str,
    priority: str,
    rationale: str,
    required_review_gate: str,
) -> TransitionProposal:
    supporting_assets = tuple(asset.path for asset in assets_by_node.get(node.id, ())[:8])
    return TransitionProposal(
        node_id=node.id,
        proposal_type=proposal_type,
        priority=priority,
        rationale=rationale,
        required_review_gate=required_review_gate,
        supporting_assets=supporting_assets,
    )


def _build_execution_plan(
    architecture: ConstructArchitecture,
    proposals: tuple[TransitionProposal, ...],
    evidence_assets: tuple[EvidenceAsset, ...],
) -> tuple[ExecutionPlanStep, ...]:
    unmatched_count = sum(1 for asset in evidence_assets if asset.matched_node_id is None)
    proposal_counts = Counter(proposal.proposal_type for proposal in proposals)
    top_hub = architecture.boundary_hubs(limit=1)[0][0]
    return (
        ExecutionPlanStep(
            step_id="observe",
            action=f"Review {len(evidence_assets)} ingested evidence assets and {unmatched_count} unmatched assets.",
            autonomy_level="A2_advisory",
            requires_approval=False,
            rationale="Read-only observation can run without changing project state.",
        ),
        ExecutionPlanStep(
            step_id="orient",
            action=f"Prioritize boundary-hub pressure around {top_hub}.",
            autonomy_level="A2_advisory",
            requires_approval=False,
            rationale="Boundary-hub ranking is derived from architecture metadata.",
        ),
        ExecutionPlanStep(
            step_id="propose",
            action=f"Prepare review packets for {proposal_counts.get('prepare_l3_external_owner_review', 0)} L3 candidates and {proposal_counts.get('prepare_l2_5_or_l3_execution_packet', 0)} packet-ready candidates.",
            autonomy_level="A2_advisory",
            requires_approval=True,
            rationale="Transition proposals require review before any status-changing work.",
        ),
        ExecutionPlanStep(
            step_id="guard",
            action="Keep all proposals advisory; do not grant reference or sixth-construct status.",
            autonomy_level="A2_guardrail",
            requires_approval=False,
            rationale="Claim firewall remains active during autonomous planning.",
        ),
    )
